style.css.content:
/*
Theme Name: Genosys
Author: Genosys
Description: Persian RTL theme with a full-screen product slider, responsive header and custom 404 page.
Version: 1.5.86
Requires at least: 6.0
Requires PHP: 7.4
License: GNU General Public License v2 or later
License URI: https://www.gnu.org/licenses/gpl-2.0.html
Text Domain: genosys
Tags: custom-logo, custom-menu, rtl-language-support
*/

@font-face {
    font-family: Vazirmatn;
    src: url("assets/fonts/Vazirmatn-Variable.woff2") format("woff2");
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
}
:root { --ink: #455660; --accent: #c8103b; --muted: #78848c; --nav-light: #e9edef; --header-height: 102px; }
* { box-sizing: border-box; }
body { margin: 0; background: #fff; color: var(--ink); direction: rtl; font-family: Vazirmatn, Tahoma, Arial, sans-serif; line-height: 1.75; }
button, input { font: inherit; }
a:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 5px; }
[hidden] { display: none !important; }
.site-header { background: transparent; }
.header-inner { display: flex; align-items: center; gap: 40px; min-height: var(--header-height); padding: 24px clamp(24px, 4vw, 76px); max-width: 2000px; margin-inline: auto; }
.site-branding { margin-inline-end: auto; flex: 0 0 auto; max-width: calc(100% - 64px); }
.brand-link, .custom-logo-link { display: block; line-height: 0; }
.brand-logo, .custom-logo { display: block; width: 196px; max-width: 100%; height: auto; object-fit: contain; }
.custom-logo { max-height: 60px; }
.primary-navigation { min-width: 0; }
.primary-menu { display: flex; flex-wrap: nowrap; align-items: center; column-gap: clamp(24px, 2.5vw, 48px); row-gap: 4px; padding: 0; margin: 0; list-style: none; }
.primary-menu li { position: relative; }
.primary-menu a { display: block; padding-block: 10px; color: inherit; text-decoration: none; font-size: 16px; font-weight: 400; overflow-wrap: anywhere; transition: color 180ms ease; }
.primary-menu a:hover, .primary-menu .current-menu-item > a { color: var(--accent); }
.primary-menu .nav-login { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 9px 24px; border: 1px solid #ffffff12; border-radius: 999px; background: linear-gradient(120deg, #c8103b, #9f1536, #c8103b); background-size: 200% 100%; background-position: 0% center; color: var(--nav-light); line-height: 1.5; white-space: nowrap; box-shadow: 0 4px 16px #c8103b22; transition: background-position 240ms ease, box-shadow 240ms ease; }
.primary-menu .nav-login:hover, .primary-menu .nav-login:focus-visible { background-position: 100% center; color: var(--nav-light); box-shadow: 0 5px 20px #c8103b40; text-decoration: none; }
.primary-menu .sub-menu { list-style: none; margin: 0; padding: 8px 16px; background: #fff; min-width: 180px; }
.primary-menu > li > .sub-menu { position: absolute; inset-inline-start: 0; top: 100%; z-index: 10; display: none; box-shadow: 0 8px 24px #45566015; }
.primary-menu > li:last-child > .sub-menu { inset-inline-start: auto; inset-inline-end: 0; }
.primary-menu > li:hover > .sub-menu, .primary-menu > li:focus-within > .sub-menu { display: block; }
.sub-menu a { font-size: 15px; }
.menu-toggle { display: none; align-items: center; justify-content: center; flex: 0 0 44px; width: 44px; height: 44px; padding: 8px; border: 0; background: transparent; color: #dd0020; cursor: pointer; }
.menu-toggle svg { display: block; width: 22px; height: 22px; }
.menu-toggle .menu-open-icon { width: 28px; height: 24px; }
.mobile-menu-topbar { display: none; }
.menu-close-icon { display: none !important; }
.menu-toggle[aria-expanded="true"] .menu-open-icon { display: none; }
.menu-toggle[aria-expanded="true"] .menu-close-icon { display: block !important; }
.skip-link { position: absolute; top: -100px; right: 24px; background: #fff; padding: 12px; z-index: 100; }
.skip-link:focus { top: 12px; }
.site-main { min-height: calc(100vh - var(--header-height)); }

/* Missing URLs keep the original Persian 404 layout. */
.error-page { display: grid; place-items: center; padding: 56px 24px 80px; }
.error-content { width: 100%; max-width: 540px; text-align: center; }
.error-code { margin: 0 0 8px; color: var(--accent); font-size: clamp(84px, 14vw, 140px); line-height: 1.15; font-weight: 300; }
.error-title { margin: 0 0 16px; font-size: clamp(24px, 4vw, 34px); line-height: 1.6; font-weight: 500; }
.error-description { margin: 0 auto 32px; max-width: 440px; color: var(--muted); }
.home-button { display: inline-flex; align-items: center; justify-content: center; gap: 12px; min-height: 48px; padding: 12px 24px; border: 1px solid var(--ink); border-radius: 30px; color: var(--ink); text-decoration: none; font-size: 15px; }
.home-button:hover { background: var(--ink); color: #fff; }
.home-button svg { flex-shrink: 0; }

@media (max-width: 1050px) {
    .header-inner { gap: 28px; }
    .primary-menu { column-gap: 24px; }
    .primary-menu a { font-size: 15px; }
    .brand-logo, .custom-logo { width: 172px; }
}
@media (max-width: 820px) {
    :root { --header-height: 82px; }
    .header-inner { gap: 16px; flex-wrap: wrap; padding: 18px 20px; }
    .brand-logo, .custom-logo { width: 156px; }
    .custom-logo { max-height: 44px; }
    .js .menu-toggle { display: inline-flex; }
    .primary-navigation { flex: 1 0 100%; width: 100%; order: 3; border-top: 1px solid #edf0f1; padding-top: 8px; }
    .primary-menu { flex-direction: column; align-items: stretch; gap: 0; }
    .primary-menu a { min-height: 48px; padding: 12px 4px; font-size: 17px; }
    .primary-menu > li > .sub-menu { display: block; position: static; box-shadow: none; padding: 0 20px 8px 0; min-width: 0; }
    .sub-menu a { font-size: 15px; }
    .error-page { padding: 48px 24px 64px; }
}
@media (max-width: 360px) {
    .header-inner { padding-inline: 16px; }
    .brand-logo, .custom-logo { width: 146px; }
    .error-page { padding-inline: 20px; }
}

/* Full-screen photography, with the existing RTL navbar over the image. */
body.home { position: relative; --admin-bar-height: 0px; }
body.home.admin-bar { --admin-bar-height: 32px; }
.site-header.site-header--banner { position: absolute; inset: 0 0 auto; z-index: 20; color: var(--nav-light); }
.home .primary-menu .sub-menu { color: var(--ink); }
.home .banner-main { min-height: 0; }
.hero-banner { position: relative; width: 100%; height: calc(100vh - var(--admin-bar-height, 0px)); height: calc(100svh - var(--admin-bar-height, 0px)); overflow: hidden; isolation: isolate; background: #e9eced; touch-action: pan-y; }
.hero-slides { position: absolute; inset: 0; z-index: 0; overflow: hidden; direction: ltr; }
.hero-banner::after { content: ""; position: absolute; inset: 0; z-index: 1; height: 100%; background: linear-gradient(to bottom, rgba(0,0,0,.82) 0%, rgba(0,0,0,.72) 18%, rgba(0,0,0,.46) 42%, rgba(0,0,0,.20) 68%, rgba(0,0,0,.06) 85%, rgba(0,0,0,0) 96%, rgba(0,0,0,0) 100%); pointer-events: none; }
.hero-slide { position: absolute; inset: 0; margin: 0; visibility: hidden; transform: translateX(-100%); transition: transform 700ms cubic-bezier(.22,.61,.36,1); }
.hero-slide.is-drag-target { visibility: visible; z-index: 1; }
.hero-banner.is-dragging .hero-slide { transition: none; }
.hero-slide img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: center; user-select: none; }
.hero-banner[data-direction="previous"] .hero-slide { transform: translateX(100%); }
.hero-banner .hero-slide.is-active { visibility: visible; transform: translateX(0); z-index: 2; }
.hero-banner .hero-slide.is-leaving { visibility: visible; transform: translateX(100%); z-index: 1; }
.hero-banner[data-direction="previous"] .hero-slide.is-leaving { transform: translateX(-100%); }
.banner-controls { display: none; }
.hero-banner.is-ready .banner-controls { display: block; }
.banner-arrow { position: absolute; top: 55%; z-index: 3; display: grid; place-items: center; width: 56px; height: 64px; padding: 12px; border: 0; background: transparent; color: #fff; filter: drop-shadow(0 1px 2px #0008); cursor: pointer; transform: translateY(-50%); }
.banner-arrow svg { display: block; width: 28px; height: 40px; }
.banner-previous { right: clamp(16px, 3.5vw, 68px); }
.banner-next { left: clamp(16px, 3.5vw, 68px); }
.banner-arrow:hover { color: var(--ink); filter: drop-shadow(0 1px 2px #fff9); }
.banner-pagination { position: absolute; bottom: max(18px, env(safe-area-inset-bottom)); left: 50%; z-index: 3; display: flex; align-items: center; gap: 0; transform: translateX(-50%); }
.banner-dot, .banner-playback { display: grid; place-items: center; width: 44px; height: 44px; padding: 0; border: 0; background: transparent; color: var(--ink); cursor: pointer; }
.banner-dot span { display: block; width: 7px; height: 7px; border: 1px solid var(--ink); border-radius: 50%; box-shadow: 0 0 0 1px #ffffff60; }
.banner-dot[aria-pressed="true"] span { background: var(--ink); }
.banner-playback svg { display: block; width: 18px; height: 18px; }
.banner-playback .banner-play-icon { display: none; }
.banner-playback[data-paused="true"] .banner-pause-icon { display: none; }
.banner-playback[data-paused="true"] .banner-play-icon { display: block; }
.screen-reader-text { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); clip-path: inset(50%); white-space: nowrap; border: 0; }
@media (hover: hover) and (pointer: fine) {
    .hero-banner.is-ready .hero-slides { cursor: grab; }
    .hero-banner.is-pointer-down .hero-slides { cursor: grabbing; }
}
@media (min-width: 821px) {
    .home .primary-menu > li:not(.menu-item-login) > a:hover, .home .primary-menu > li:not(.menu-item-login) > a:focus-visible, .home .primary-menu > .current-menu-item:not(.menu-item-login) > a { color: #efafc0; text-decoration: none; }
    @supports ((background-clip: text) or (-webkit-background-clip: text)) {
        .home .primary-menu > li:not(.menu-item-login) > a:hover, .home .primary-menu > li:not(.menu-item-login) > a:focus-visible, .home .primary-menu > .current-menu-item:not(.menu-item-login) > a { background-image: linear-gradient(115deg, #eef0f2 0%, #eaa1b5 100%); -webkit-background-clip: text; background-clip: text; color: transparent; }
    }
}
@media (max-width: 820px) {
    .home .primary-navigation { max-height: calc(100svh - var(--header-height) - var(--admin-bar-height)); overflow-y: auto; padding: 12px 20px; border: 1px solid #ffffff90; border-radius: 4px; background: #fffffff5; color: var(--ink); box-shadow: 0 8px 24px #45566015; }
    .hero-slide.slide-eco img { object-position: 50% center; }
    .hero-slide.slide-skincare img { object-position: 47% center; }
    .hero-slide.slide-ampoules img { object-position: 82% center; }
    .hero-slide.slide-hair img { object-position: 71% center; }
    .banner-arrow { width: 44px; height: 52px; padding: 10px; top: 57%; }
    .banner-arrow svg { width: 22px; height: 32px; }
    .banner-previous { right: 6px; }
    .banner-next { left: 6px; }
    .banner-pagination { bottom: max(14px, env(safe-area-inset-bottom)); }
}
@media (max-width: 782px) {
    body.home.admin-bar { --admin-bar-height: 46px; }
}

/* The mobile menu becomes a full-screen glass panel only when JavaScript is available. */
@media (max-width: 820px) {
    html.js.mobile-menu-open, .js body.mobile-menu-open { overflow: hidden; overscroll-behavior: none; }
    .js body.mobile-menu-open .site-header { position: relative; z-index: 100000; }
    .js body.mobile-menu-open .site-header.site-header--banner { position: absolute; }
    .js .primary-navigation { position: fixed; inset: 0; z-index: 40; display: flex; flex-direction: column; width: 100%; height: 100vh; height: 100dvh; max-height: none; margin: 0; padding: max(24px, env(safe-area-inset-top)) max(24px, env(safe-area-inset-right)) max(32px, env(safe-area-inset-bottom)) max(24px, env(safe-area-inset-left)); border: 0; border-radius: 0; background: rgba(16, 24, 30, .84); color: var(--nav-light); box-shadow: none; overflow-x: hidden; overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; touch-action: pan-y; animation: mobile-menu-reveal 200ms ease-out; }
    .js .primary-navigation .mobile-menu-topbar { display: flex; align-items: center; justify-content: space-between; flex-shrink: 0; gap: 24px; width: 100%; max-width: 640px; margin-inline: auto; }
    .mobile-menu-brand { display: block; flex: 0 1 156px; min-width: 0; line-height: 0; }
    .mobile-menu-brand img { display: block; width: 156px; max-width: 100%; height: auto; }
    .mobile-menu-close { display: grid; place-items: center; flex: 0 0 44px; width: 44px; height: 44px; padding: 10px; border: 1px solid #ffffff40; border-radius: 50%; background: #ffffff0d; color: #fff; cursor: pointer; }
    .mobile-menu-close svg { display: block; width: 22px; height: 22px; }
    .mobile-menu-close:hover { background: #ffffff26; }
    .js .primary-navigation .primary-menu { width: 100%; max-width: 600px; margin: clamp(48px, 10svh, 100px) auto auto; gap: 0; }
    .js .primary-navigation .primary-menu > li { border-bottom: 1px solid #ffffff26; }
    .js .primary-navigation .primary-menu > li > a { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 76px; padding: 20px 4px; color: var(--nav-light); font-size: clamp(22px, 4vw, 28px); font-weight: 400; line-height: 1.5; }
    .js .primary-navigation .primary-menu > li > a::after { content: ""; flex: 0 0 8px; width: 8px; height: 8px; margin-inline-end: 4px; border-bottom: 1px solid currentColor; border-left: 1px solid currentColor; transform: rotate(45deg); opacity: .6; }
    .js .primary-navigation .primary-menu a:hover, .js .primary-navigation .primary-menu .current-menu-item > a { color: #efafc0; background: linear-gradient(110deg, #c8103b12, #ffffff0d); }
    .js .primary-navigation .primary-menu .menu-item-login { display: flex; align-items: center; min-height: 76px; border-bottom: 0; }
    .js .primary-navigation .primary-menu .nav-login { justify-content: center; width: 100%; min-height: 48px; padding: 12px 24px; border-radius: 14px; background: linear-gradient(120deg, #c8103b, #9f1536, #c8103b); background-size: 200% 100%; background-position: 0% center; color: var(--nav-light); font-size: 18px; }
    .js .primary-navigation .primary-menu .nav-login::after { display: none; }
    .js .primary-navigation .primary-menu .nav-login:hover, .js .primary-navigation .primary-menu .nav-login:focus-visible { background-position: 100% center; color: var(--nav-light); }
    .js .primary-navigation .primary-menu .sub-menu { position: static; display: block; min-width: 0; padding: 0 20px 14px 0; background: transparent; color: var(--nav-light); box-shadow: none; }
    .js .primary-navigation .sub-menu a { padding: 10px 4px; font-size: 17px; }
    .js .primary-navigation a:focus-visible, .js .primary-navigation button:focus-visible { outline-color: #fff; }
    @supports ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
        .js .primary-navigation { background: linear-gradient(180deg, rgba(16, 24, 30, .66), rgba(16, 24, 30, .62)); -webkit-backdrop-filter: blur(26px) saturate(115%); backdrop-filter: blur(26px) saturate(115%); }
    }
}
@media (max-width: 820px) and (max-height: 520px) {
    .js .primary-navigation { padding-block: 16px; }
    .js .primary-navigation .primary-menu { margin-top: 24px; }
    .js .primary-navigation .primary-menu > li > a { min-height: 56px; padding-block: 12px; font-size: 22px; }
    .js .primary-navigation .primary-menu .menu-item-login { min-height: 64px; }
    .js .primary-navigation .primary-menu .nav-login { font-size: 18px; }
}
@keyframes mobile-menu-reveal { from { opacity: 0; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
    .hero-slide { transition: none; }
    .js .primary-navigation { animation: none; }
    .primary-menu a { transition: none; }
}

/* Two equally sized image cards below the finished homepage banner. */
.home-feature-section { padding: clamp(40px, 3.8vw, 82px) clamp(20px, 2.5vw, 76px); background: #fff; }
.home-feature-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: clamp(20px, 1.3vw, 28px); }
.home-feature-card { position: relative; display: flex; flex-direction: column; justify-content: flex-end; width: 100%; aspect-ratio: 1.76; min-width: 0; min-height: 300px; overflow: hidden; isolation: isolate; border-radius: 18px; background: #dce1e3; }
.home-feature-image { position: absolute; inset: 0; z-index: 0; display: block; width: 100%; height: 100%; object-fit: cover; object-position: center; transition: transform 450ms cubic-bezier(.22,.61,.36,1); }
.home-feature-card::after { content: ""; position: absolute; inset: 0; z-index: 1; background: linear-gradient(to top, rgba(16,24,30,.82) 0%, rgba(16,24,30,.38) 38%, rgba(16,24,30,0) 74%); pointer-events: none; }
.home-feature-content { position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; align-self: flex-start; width: fit-content; max-width: 100%; gap: clamp(18px, 1vw, 22px); padding: clamp(24px, 2.05vw, 44px); text-align: center; }
.home-feature-title { margin: 0; color: var(--nav-light); font-size: clamp(24px, 1.8vw, 38px); font-weight: 500; line-height: 1.45; }
.home-feature-title-link, .home-feature-title-link:hover { color: inherit; text-decoration: none; }
.home-feature-button { display: inline-flex; align-items: center; justify-content: center; min-height: clamp(48px, 3vw, 64px); max-width: 100%; padding: 10px clamp(24px, 1.8vw, 38px); border: 1px solid #ffffff12; border-radius: 999px; background: linear-gradient(120deg, #c8103b, #9f1536, #c8103b); background-size: 200% 100%; background-position: 0% center; color: var(--nav-light); font-size: clamp(15px, .9vw, 18px); font-weight: 500; line-height: 1.5; text-decoration: none; box-shadow: 0 4px 16px #c8103b22; transition: background-position 240ms ease, box-shadow 240ms ease; }
.home-feature-button:hover, .home-feature-button:focus-visible { background-position: 100% center; color: var(--nav-light); box-shadow: 0 5px 20px #c8103b40; }
.home-feature-button:focus-visible { outline-color: var(--nav-light); }
@media (hover: hover) and (pointer: fine) {
    .home-feature-card:hover .home-feature-image { transform: scale(1.025); }
}
@media (max-width: 820px) {
    .home-feature-grid { grid-template-columns: minmax(0, 1fr); gap: 24px; }
    .home-feature-card { aspect-ratio: 1.6; min-height: 300px; border-radius: 14px; }
    .home-feature-club .home-feature-image { object-position: 35% center; }
    .home-feature-content { gap: 18px; padding: 28px; }
    .home-feature-title { font-size: clamp(22px, 3.4vw, 28px); }
    .home-feature-button { min-height: 48px; padding: 10px 24px; font-size: 14px; }
}
@media (max-width: 360px) {
    .home-feature-content { padding: 24px; }
}
@media (prefers-reduced-motion: reduce) {
    .home-feature-image, .home-feature-button { transition: none; }
    .home-feature-card:hover .home-feature-image { transform: none; }
}

assets/css/account-dashboard.css.content:
/* Account dashboard only. Other WooCommerce account endpoints keep their layouts. */
.gaccount {
    --gaccount-red: #cf0636;
    --gaccount-deep: #a70828;
    --gaccount-ink: #1d1d24;
    --gaccount-muted: #89847f;
    --gaccount-line: #e5e2e1;
    direction: rtl;
    color: var(--gaccount-ink);
    background: #fff;
    font-family: Vazirmatn, Tahoma, Arial, sans-serif;
    line-height: 1.75;
    min-height: 65vh;
}
.gaccount *, .gaccount *::before, .gaccount *::after { box-sizing: border-box; }
.gaccount [hidden] { display: none !important; }
.gaccount input, .gaccount select, .gaccount button { font-family: inherit; }
.gaccount button { cursor: pointer; }
.gaccount :where(a) { color: inherit; }
.gaccount svg { display: block; flex-shrink: 0; }
.gaccount__container { width: min(1420px, calc(100% - 64px)); margin-inline: auto; padding: 22px 0 90px; }
.gaccount__breadcrumb { display: flex; gap: 5px; align-items: center; margin: 0 0 18px; color: var(--gaccount-muted); font-size: 14px; }
.gaccount__breadcrumb a { text-decoration: none; }
.gaccount__breadcrumb a:hover { color: var(--gaccount-red); }
.gaccount__title { margin: 0 0 33px; font-size: 48px; line-height: 1.55; font-weight: 800; letter-spacing: -.8px; }
.gaccount__layout { display: grid; grid-template-columns: minmax(280px, 388px) minmax(0, 1fr); gap: 30px; align-items: start; }
.gaccount__sidebar, .gaccount__content { min-width: 0; }
.gaccount__content { display: grid; gap: 23px; }
.gaccount__identity { display: flex; flex-direction: column; align-items: center; min-height: 350px; padding: 32px 24px 29px; border: 1px solid #ffc7d2; border-radius: 34px; background: radial-gradient(ellipse at 24% 110%, #edb8bd 0, #f8e1e3 35%, #fffcfc 70%, #fff 87%); box-shadow: 0 18px 26px -22px #b83e5166; text-align: center; }
.gaccount__avatar { display: grid; place-items: center; flex-shrink: 0; overflow: hidden; border-radius: 50%; background: linear-gradient(135deg, #d20a38, #a50728); color: #fff; font-size: 49px; font-weight: 500; line-height: 1; box-shadow: 0 20px 25px -13px #b80a3c9e; }
.gaccount__avatar img { display: block; width: 100%; height: 100%; max-width: none; object-fit: cover; }
.gaccount__avatar--sidebar { width: 115px; height: 115px; margin-bottom: 14px; }
.gaccount__identity h2, .gaccount__identity-name { margin: 0 0 1px; color: var(--gaccount-ink); font-size: 24px; font-weight: 750; line-height: 1.6; overflow-wrap: anywhere; }
.gaccount__phone-small { margin: 0 0 16px; color: var(--gaccount-muted); font-size: 14px; direction: ltr; unicode-bidi: isolate; }
.gaccount__badge { display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; gap: 8px; min-height: 40px; max-width: 100%; padding: 6px 15px; border: 1px solid transparent; border-radius: 999px; background: linear-gradient(125deg, #ce0a36, #a70828); color: #fff; font-size: 16px; font-weight: 750; line-height: 1.6; white-space: nowrap; box-shadow: 0 14px 20px -12px #b70a3e91; }
.gaccount__badge svg { width: 18px; height: 18px; }
.gaccount__badge[data-membership="new"] { background: #fff; border-color: #ff8da7; color: #c00c34; box-shadow: none; }
.gaccount__badge[data-membership="returning"] { background: #25262b; color: #fff; box-shadow: 0 13px 18px -10px #2424265c; }
.gaccount__badge[data-membership="returning"] svg { color: #f4bf52; }
.gaccount__membership-date { margin: 12px 0 0; color: var(--gaccount-muted); font-size: 14px; }
