    .gaccount__card-header h2 { font-size: 17px; }
    .gaccount__card-header .gaccount__button { font-size: 11px; padding-inline: 9px; }
    .gaccount__hero-heading h2, .gaccount__hero-name { font-size: 20px; }
    .gaccount__hero .gaccount__badge { font-size: 11px; }
}
@media (prefers-reduced-motion: reduce) {
    .gaccount *, .gaccount *::before, .gaccount *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
}

assets/css/account-menu.css.content:
/* Navbar and its account/search states. Banner styles are unchanged. */
.site-header {
    background: #fff;
    color: #3b4553;
}
.site-header { z-index: 30; box-shadow: 0 1px 0 rgba(36, 42, 49, .04); }
.site-header.site-header--banner { background: transparent; box-shadow: none; }
.site-header .header-inner {
    position: relative;
    width: 100%;
    max-width: 1720px;
    min-height: 100px;
    gap: 0;
    padding: 12px clamp(40px, 4vw, 72px);
}
.site-header .site-branding { flex: 0 0 auto; max-width: none; margin: 0; }
.site-header .brand-logo,
.site-header .custom-logo { width: 206px; max-width: 100%; height: auto; max-height: 58px; }

@media (min-width: 821px) {
    .site-header .primary-navigation { margin-inline-start: 58px; }
    .site-header .primary-menu { gap: clamp(32px, 2.6vw, 50px); }
    .site-header .primary-menu > li > a {
        position: relative;
        padding: 13px 0 18px;
        color: #3b4553;
        font-size: 17px;
        font-weight: 600;
        line-height: 1.5;
        white-space: nowrap;
        background-image: none;
    }
    .site-header .primary-menu > li > a::after {
        position: absolute;
        inset-inline: 0;
        bottom: 5px;
        height: 3px;
        border-radius: 1px;
        background: #c8103b;
        content: '';
        opacity: 0;
        transform: scaleX(.65);
        transition: opacity 180ms ease, transform 180ms ease;
    }
    .site-header .primary-menu > li > a:hover,
    .site-header .primary-menu > li > a:focus-visible,
    .site-header .primary-menu > .current-menu-item > a,
    .site-header .primary-menu > .current-menu-ancestor > a,
    .site-header.site-header--banner .primary-menu > li > a:hover,
    .site-header.site-header--banner .primary-menu > li > a:focus-visible,
    .site-header.site-header--banner .primary-menu > .current-menu-item > a {
        color: #c8103b;
        background-image: none;
        -webkit-text-fill-color: currentColor;
    }
    .site-header .primary-menu > .current-menu-item > a::after,
    .site-header .primary-menu > .current-menu-ancestor > a::after,
    .site-header .primary-menu > li > a:hover::after,
    .site-header .primary-menu > li > a:focus-visible::after { opacity: 1; transform: scaleX(1); }
    .site-header.site-header--banner .primary-menu > li > a { color: #f4f6f7; }
    .site-header.site-header--banner .primary-menu > li > a:hover,
    .site-header.site-header--banner .primary-menu > li > a:focus-visible,
    .site-header.site-header--banner .primary-menu > .current-menu-item > a,
    .site-header.site-header--banner .primary-menu > .current-menu-ancestor > a { color: #f2a5b8; }
    .site-header.site-header--banner .primary-menu > li > a::after { background: #f2a5b8; }
}

.header-actions {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 4px;
    direction: ltr;
    margin-right: auto;
}
.nav-account-menu,
.header-search { position: relative; flex: 0 0 auto; }
.header-search { flex-basis: 48px; width: 48px; height: 48px; }
.header-actions .nav-icon-button {
    position: relative;
    display: grid;
    place-items: center;
    flex: 0 0 48px;
    width: 48px;
    height: 48px;
    padding: 11px;
    border: 0;
    border-radius: 50%;
    background: #f4f4f4;
    color: #3b4553;
    text-decoration: none;
    cursor: pointer;
    transition: color 180ms ease, background-color 180ms ease, box-shadow 180ms ease;
}
.header-actions .nav-icon-button svg { display: block; width: 26px; height: 26px; }
.header-actions .nav-icon-button:hover,
.header-actions .nav-icon-button:focus-visible { background: #fbe9ed; color: #c8103b; }
.header-actions .nav-account-toggle[aria-expanded='true'] {
    background: linear-gradient(135deg, #d30a3c, #a8072f);
    color: #fff;
    box-shadow: 0 10px 18px rgba(183, 6, 51, .24);
}
.header-actions .nav-account-menu--guest .nav-account-toggle[aria-expanded='true'] {
    background: #f4f4f4;
    color: #3b4553;
    box-shadow: none;
}
.site-header.site-header--banner .header-actions .nav-icon-button {
    background: transparent;
    color: #f4f6f7;
    box-shadow: none;
}
.site-header.site-header--banner .header-actions .nav-icon-button:hover,
.site-header.site-header--banner .header-actions .nav-icon-button:focus-visible {
    background: transparent;
    color: #f2a5b8;
}
.site-header.site-header--banner .header-actions .nav-account-toggle[aria-expanded='true'] {
    background: linear-gradient(135deg, #d30a3c, #a8072f);
    color: #fff;
    box-shadow: 0 10px 18px rgba(183, 6, 51, .24);
}
.site-header.site-header--banner .header-actions .nav-account-menu--guest .nav-account-toggle[aria-expanded='true'] {
    background: transparent;
    color: #f4f6f7;
    box-shadow: none;
}
.nav-count-badge,
.nav-guest-indicator {
    position: absolute;
    top: -5px;
    left: -4px;
    display: grid;
    place-items: center;
    min-width: 21px;
    height: 21px;
    padding: 0 3px;
    border-radius: 50%;
    background: #c8103b;
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    line-height: 1;
}
.nav-guest-indicator { top: 1px; left: 0; min-width: 15px; width: 15px; height: 15px; padding: 0; }

.nav-account-dropdown {
    position: absolute;
    top: calc(100% + 12px);
    left: 0;
    z-index: 80;
    width: 280px;
    padding: 9px;
    border: 1px solid #ededed;
    border-radius: 23px;
    background: #fff;
    color: #202127;
    box-shadow: 0 17px 27px rgba(22, 25, 29, .19), 0 0 0 4px rgba(241, 241, 241, .48);
}
.nav-account-dropdown:not([hidden]) {
    transform-origin: top left;
    animation: genosys-account-reveal 210ms cubic-bezier(.2, .8, .2, 1) both;
}
@keyframes genosys-account-reveal {
    from { opacity: 0; transform: translateY(-8px) scale(.97); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}
.nav-account-dropdown::before {
    position: absolute;
    top: -9px;
    left: 21px;
    width: 17px;
    height: 17px;
    border-top: 1px solid #ededed;
    border-left: 1px solid #ededed;
    background: #fff;
    content: '';
    transform: rotate(45deg);
}
.account-panel-identity {
    display: flex;
    align-items: center;
    min-height: 72px;
    gap: 10px;
    padding: 10px 12px;
    border: 1px solid #f5b5c0;
    border-radius: 16px;
    background: linear-gradient(120deg, #f6c2ca 0%, #fae4e7 52%, #fff7f8 100%);
}
.account-panel-identity--guest { min-height: 84px; }
.account-panel-avatar {
    display: grid;
    place-items: center;
    flex: 0 0 44px;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: linear-gradient(135deg, #d00638, #a4062e);
    color: #fff;
    font-size: 22px;
    font-weight: 700;
    line-height: 1;
    box-shadow: 0 7px 12px rgba(188, 4, 49, .22);
}
.account-panel-avatar svg { width: 22px; height: 22px; }
.account-panel-identity-copy,
.account-panel-row-copy { display: flex; flex: 1 1 auto; min-width: 0; flex-direction: column; text-align: right; }
.account-panel-identity-copy strong {
    color: #202127;
    font-size: 15px;
    font-weight: 700;
    line-height: 1.5;
    overflow-wrap: anywhere;
}
.account-panel-identity-copy small { color: #828184; font-size: 11px; line-height: 1.6; }
.account-panel-identity--guest .account-panel-identity-copy strong { font-size: 14px; }
.account-panel-identity--guest .account-panel-identity-copy small { max-width: 160px; }
.nav-account-dropdown .account-panel-row {
    display: flex;
    align-items: center;
    min-height: 56px;
    gap: 10px;
    padding: 7px 11px;
    border-radius: 13px;
    color: #202127;
    text-decoration: none;
    transition: background-color 180ms ease;
}
.nav-account-dropdown .account-panel-row:hover,
.nav-account-dropdown .account-panel-row:focus-visible { background: #fff3f5; }
.account-panel-row-icon {
    display: grid;
    place-items: center;
    flex: 0 0 38px;
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: #f4f4f4;
    color: #404a55;
}
.account-panel-row-icon svg { width: 19px; height: 19px; }
.account-panel-row-copy strong { font-size: 14px; font-weight: 700; line-height: 1.4; }
.account-panel-row-copy small { color: #88878a; font-size: 11px; line-height: 1.5; }
.account-panel-order-count {
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    min-width: 22px;
    height: 22px;
    margin-inline-start: auto;
    padding: 0 5px;
    border-radius: 50%;
    background: #c8103b;
    color: #fff;
    font-size: 11px;
    line-height: 1;
}
.account-panel-divider { height: 1px; margin: 5px 9px 3px; background: #e8e8e8; }
.nav-account-dropdown .account-panel-row--logout { min-height: 52px; color: #c8103b; }
.account-panel-row--logout .account-panel-row-icon { background: #fcebef; color: #c8103b; }

.nav-account-dropdown .account-panel-login {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 52px;
    gap: 9px;
    margin-top: 6px;
    border-radius: 40px;
    background: linear-gradient(110deg, #d10a3c, #a80830);
    color: #fff;
    font-size: 15px;
    font-weight: 700;
    text-decoration: none;
    box-shadow: 0 9px 15px rgba(195, 4, 51, .2);
    transition: box-shadow 180ms ease, transform 180ms ease;
}
.nav-account-dropdown .account-panel-login:hover,
.nav-account-dropdown .account-panel-login:focus-visible { color: #fff; box-shadow: 0 14px 23px rgba(195, 4, 51, .33); transform: translateY(-1px); }
.account-panel-login svg { width: 17px; height: 17px; }
.account-panel-login-note { margin: 8px 0 5px; color: #8a898c; font-size: 11px; text-align: center; }

.header-search-form {
    position: absolute;
    top: 50%;
    left: 0;
    z-index: 85;
    display: flex;
    align-items: center;
    width: 260px;
    height: 44px;
    gap: 8px;
    padding: 0 11px;
    border: 1px solid #eda8b7;
    border-radius: 24px;
    background: #fff;
    direction: rtl;
    box-shadow: 0 0 0 3px rgba(251, 231, 235, .9), 0 7px 15px rgba(75, 31, 43, .13);
    transform: translateY(-50%);
}
.header-search-form:not([hidden]) {
    transform-origin: left center;
    animation: genosys-search-reveal 220ms cubic-bezier(.2, .8, .2, 1) both;
}
@keyframes genosys-search-reveal {
    from { opacity: 0; transform: translateY(-50%) translateX(-8px) scaleX(.94); }
    to { opacity: 1; transform: translateY(-50%) translateX(0) scaleX(1); }
}
.header-search-form button {
    display: grid;
    place-items: center;
    flex: 0 0 23px;
    width: 23px;
    height: 23px;
    padding: 0;
    border: 0;
    background: transparent;
    color: #c8103b;
    cursor: pointer;
}
.header-search-form button svg { width: 21px; height: 21px; }
.header-search-form input {
    flex: 1 1 auto;
    min-width: 0;
    height: 100%;
    padding: 0;
    border: 0;
    outline: 0;
    background: transparent;
    color: #202127;
    font-size: 14px;
    text-align: right;
}
.header-search-form input::placeholder { color: #868488; opacity: 1; }
.header-search-form input::-webkit-search-cancel-button { cursor: pointer; }
.header-search-form kbd { display: none; }

.mobile-menu-commerce { display: none; }

@media (max-width: 1199px) and (min-width: 821px) {
    .site-header .header-inner { padding-inline: clamp(28px, 3vw, 40px); }
    .site-header .brand-logo,
    .site-header .custom-logo { width: 174px; }
    .site-header .primary-navigation { margin-inline-start: 29px; }
    .site-header .primary-menu { gap: 25px; }
    .site-header .primary-menu > li > a { font-size: 15px; }
    .header-actions { gap: 4px; }
    .header-actions .nav-icon-button { flex-basis: 44px; width: 44px; height: 44px; padding: 9px; }
    .header-search { flex-basis: 44px; width: 44px; height: 44px; }
    .header-search-form { width: min(240px, 28vw); height: 42px; }
}
@media (max-width: 950px) and (min-width: 821px) {
    .site-header .brand-logo,
    .site-header .custom-logo { width: 150px; }
    .site-header .primary-navigation { margin-inline-start: 19px; }
    .site-header .primary-menu { gap: 16px; }
    .site-header .primary-menu > li > a { font-size: 14px; }
    .header-actions .nav-icon-button { flex-basis: 44px; width: 44px; height: 44px; padding: 9px; }
    .header-search-form { width: min(210px, 22vw); }
    .header-search-form input { font-size: 13px; }
}

@media (max-width: 820px) {
    .site-header .header-inner { min-height: 76px; flex-wrap: wrap; gap: 8px; padding: 12px 20px; }
    .site-header .site-branding { order: 1; }
    .site-header .brand-logo,
    .site-header .custom-logo { width: 118px; max-height: 40px; }
    .site-header .primary-navigation { order: 4; }
    .site-header .header-actions { order: 2; gap: 4px; margin-right: auto; }
    .site-header .header-actions .nav-cart-link,
    .site-header .header-actions .nav-account-menu { display: none; }
    .site-header .menu-toggle { order: 3; flex-basis: 40px; width: 40px; height: 40px; padding: 6px; }
    .header-actions .nav-icon-button { flex-basis: 40px; width: 40px; height: 40px; padding: 9px; }
    .header-search { flex-basis: 40px; width: 40px; height: 40px; }
    .header-actions .nav-icon-button svg { width: 22px; height: 22px; }
    .nav-count-badge { top: -5px; left: -4px; min-width: 18px; height: 18px; font-size: 10px; }
    .nav-guest-indicator { width: 12px; min-width: 12px; height: 12px; }
    .nav-account-menu,
    .header-search { position: static; }
    .nav-account-dropdown {
        top: calc(100% + 8px);
        left: 12px;
        width: min(280px, calc(100vw - 24px));
    }
    .header-search-form {
        position: absolute;
        top: calc(100% + 8px);
        left: 20px;
        width: min(280px, calc(100vw - 40px));
        height: 44px;
        transform: none;
    }
    .header-search-form:not([hidden]) { transform-origin: left top; animation-name: genosys-mobile-search-reveal; }

    .js .primary-navigation .primary-menu { margin: clamp(28px, 6svh, 56px) auto 0; }
    .mobile-menu-commerce {
        display: block;
        width: 100%;
        max-width: 600px;
        margin: 22px auto 0;
        padding: 18px 0 0;
        border-top: 1px solid #ffffff3b;
        direction: rtl;
        color: #fff;
    }
    .mobile-menu-commerce__profile {
        display: flex;
        align-items: center;
        gap: 12px;
        min-height: 68px;
        padding: 11px 13px;
        border: 1px solid #ffffff42;
        border-radius: 17px;
        background: linear-gradient(115deg, #ffffff23, #ffffff0b);
    }
    .mobile-menu-commerce__avatar {
        display: grid;
        place-items: center;
        flex: 0 0 43px;
        width: 43px;
        height: 43px;
        border-radius: 50%;
        background: linear-gradient(120deg, #d10a3c, #a80830);
        color: #fff;
        font-size: 21px;
        font-weight: 700;
        line-height: 1;
        box-shadow: 0 5px 12px #51051c55;
    }
    .mobile-menu-commerce__avatar svg { width: 23px; height: 23px; }
    .mobile-menu-commerce__profile-copy,
    .mobile-menu-commerce__card-copy { display: flex; flex-direction: column; min-width: 0; }
    .mobile-menu-commerce__profile-copy strong { font-size: 16px; font-weight: 700; line-height: 1.5; }
    .mobile-menu-commerce__profile-copy small { color: #ffffffba; font-size: 12px; line-height: 1.5; }
    .mobile-menu-commerce__cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 11px; }
    .mobile-menu-commerce__card {
        position: relative;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: flex-start;
        gap: 7px;
        min-width: 0;
        min-height: 108px;
        padding: 12px 14px;
        border: 1px solid #ffffff40;
        border-radius: 17px;
        background: #ffffff16;
        color: #fff;
        text-decoration: none;
        transition: background 180ms ease, border-color 180ms ease;
    }
    .mobile-menu-commerce__card:hover,
    .mobile-menu-commerce__card:focus-visible { border-color: #ffffff8c; background: #ffffff27; color: #fff; }
    .mobile-menu-commerce__card--login { border-color: #e96c89; background: linear-gradient(115deg, #d10a3c, #a80830); }
    .mobile-menu-commerce__card--login:hover,
    .mobile-menu-commerce__card--login:focus-visible { background: linear-gradient(115deg, #e31347, #bd0a38); }
    .mobile-menu-commerce__card-icon { display: grid; place-items: center; flex: 0 0 33px; width: 33px; height: 33px; border-radius: 50%; background: #ffffff28; }
    .mobile-menu-commerce__card-icon svg { display: block; width: 19px; height: 19px; }
    .mobile-menu-commerce__card-copy strong { color: #fff; font-size: 15px; font-weight: 700; line-height: 1.4; }
    .mobile-menu-commerce__card-copy small { color: #ffffffb8; font-size: 11px; line-height: 1.45; }
    .mobile-menu-commerce__count { position: absolute; top: 12px; left: 12px; display: grid; place-items: center; min-width: 22px; height: 22px; padding: 0 4px; border-radius: 99px; background: #d10a3c; color: #fff; font-size: 11px; font-weight: 700; line-height: 1; }
    .mobile-menu-commerce__secondary { display: grid; gap: 2px; margin-top: 9px; }
    .mobile-menu-commerce__secondary-link {
        position: relative;
        display: flex;
        align-items: center;
        gap: 10px;
        min-height: 54px;
        padding: 8px 5px;
        border-bottom: 1px solid #ffffff29;
        color: #fff;
        text-decoration: none;
        transition: color 180ms ease, background 180ms ease;
    }
    .mobile-menu-commerce__secondary-link:hover,
    .mobile-menu-commerce__secondary-link:focus-visible { background: #ffffff13; color: #fff; }
    .mobile-menu-commerce__secondary-link .mobile-menu-commerce__card-icon { flex-basis: 34px; width: 34px; height: 34px; background: #ffffff1f; }
    .mobile-menu-commerce__secondary-link .mobile-menu-commerce__card-copy strong { font-size: 14px; }
    .mobile-menu-commerce__secondary-link .mobile-menu-commerce__count { position: static; margin-inline-start: auto; }
    .mobile-menu-commerce__secondary-link--logout,
    .mobile-menu-commerce__secondary-link--logout .mobile-menu-commerce__card-copy strong { color: #ffa7bb; }
    .mobile-menu-commerce__secondary-link--logout:hover,
    .mobile-menu-commerce__secondary-link--logout:focus-visible { color: #ffc8d3; }
}
@keyframes genosys-mobile-search-reveal {
    from { opacity: 0; transform: translateY(-8px) scale(.97); }
    to { opacity: 1; transform: none; }
}
@media (max-width: 360px) {
    .site-header .header-inner { gap: 6px; padding-inline: 16px; }
    .site-header .brand-logo,
    .site-header .custom-logo { width: 104px; }
    .site-header .menu-toggle { flex-basis: 36px; width: 36px; height: 36px; }
    .header-actions .nav-icon-button { flex-basis: 36px; width: 36px; height: 36px; padding: 8px; }
    .header-search { flex-basis: 36px; width: 36px; height: 36px; }
    .header-actions .nav-icon-button svg { width: 20px; height: 20px; }
    .header-search-form { left: 16px; width: min(280px, calc(100vw - 32px)); }
}
@media (prefers-reduced-motion: reduce) {
    .header-actions .nav-icon-button,
    .account-panel-row,
    .account-panel-login,
    .site-header .primary-menu > li > a::after { transition: none; }
    .nav-account-dropdown:not([hidden]),
    .header-search-form:not([hidden]) { animation: none; }
    .mobile-menu-commerce__card,
    .mobile-menu-commerce__secondary-link { transition: none; }
}

assets/css/add-to-cart-animation.css.content:
/* Decorative purchase feedback must not change header or mobile-menu layout. */

body.single-product .single_add_to_cart_button[aria-disabled='true'] { cursor: progress; }
body.single-product .gca-inline-feedback { margin-top: 16px; }

.genosys-add-animation {
    position: fixed;
    inset: 0;
    z-index: 99990;
    overflow: hidden;
    pointer-events: none;
    direction: rtl;
}

.genosys-add-animation .gca-veil {
    position: absolute;
    inset: 0;
    background: rgba(255, 255, 255, .62);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
    opacity: 0;
    transition: opacity 240ms ease;
}

.genosys-add-animation.is-active .gca-veil { opacity: 1; }

.genosys-add-animation .gca-basket {
    position: absolute;
    width: 200px;
    height: 170px;
    opacity: 0;
    transform: translate(-50%, -50%);
    transform-origin: center center;
    will-change: transform, opacity;
    isolation: isolate;
}

.genosys-add-animation .gca-basket-back,
.genosys-add-animation .gca-basket-front,
.genosys-add-animation .gca-flap {
    position: absolute;
    display: block;
    overflow: visible;
    width: 100%;
    height: 100%;
}

.genosys-add-animation .gca-basket-back { z-index: 1; }

.genosys-add-animation .gca-product {
    position: absolute;
    z-index: 2;
    display: block;
    max-width: none;
    object-fit: contain;
    transform-origin: center center;
    will-change: transform, opacity;
    filter: drop-shadow(0 8px 12px rgba(49, 18, 27, .17));
}

.genosys-add-animation .gca-product img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.genosys-add-animation .gca-basket-front {
    z-index: 3;
    filter: drop-shadow(0 14px 14px rgba(57, 9, 25, .19));
}

.genosys-add-animation .gca-flap {
    z-index: 4;
    top: 26px;
    width: 50%;
    height: 50px;
    will-change: transform;
    transition: transform 250ms cubic-bezier(.2, .85, .25, 1);
}

.genosys-add-animation .gca-flap--left {
    left: 0;
    transform-origin: 24px 42px;
    transform: rotate(-72deg);
}

.genosys-add-animation .gca-flap--right {
    right: 0;
    transform-origin: 76px 42px;
    transform: rotate(72deg);
}

.genosys-add-animation .gca-basket.is-closed .gca-flap { transform: rotate(0); }

.genosys-add-animation .gca-toast {
    position: fixed;
    right: auto;
    bottom: max(24px, env(safe-area-inset-bottom));
    left: 50%;
    z-index: 5;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 22px;
    width: max-content;
    max-width: calc(100vw - 32px);
    min-height: 56px;
    padding: 12px 20px;
    border: 1px solid rgba(255, 255, 255, .1);
    border-radius: 16px;
    background: #26292e;
    color: #fff;
    font: 600 14px/1.6 Vazirmatn, Tahoma, Arial, sans-serif;
    box-shadow: 0 14px 32px rgba(24, 26, 31, .25);
    opacity: 0;
    visibility: hidden;
    transform: translate(-50%, 16px);
    transition: opacity 220ms ease, transform 220ms ease, visibility 220ms ease;
    pointer-events: none;
}

.genosys-add-animation .gca-toast.is-visible {
    opacity: 1;
    visibility: visible;
    transform: translate(-50%, 0);
    pointer-events: auto;
}

.genosys-add-animation .gca-toast a {
    flex: 0 0 auto;
    color: #ffc6d3;
    font-weight: 700;
    text-decoration: none;
    white-space: nowrap;
}

.genosys-add-animation .gca-toast-message { min-width: 0; overflow-wrap: anywhere; }

.genosys-add-animation .gca-toast a:hover,
.genosys-add-animation .gca-toast a:focus-visible { color: #fff; text-decoration: underline; }

body.single-product .nav-count-badge.gca-badge-pop {
    animation: gca-badge-pop 350ms cubic-bezier(.2, .8, .2, 1) both;
}

@keyframes gca-badge-pop {
    0% { transform: scale(.5); }
    45% { transform: scale(1.45); }
    72% { transform: scale(.92); }
    100% { transform: scale(1); }
}

@media (max-width: 480px) {
    .genosys-add-animation .gca-toast { gap: 12px; padding: 12px 16px; font-size: 12px; }
}

@media (prefers-reduced-motion: reduce) {
    .genosys-add-animation .gca-veil,
    .genosys-add-animation .gca-flap,
    .genosys-add-animation .gca-toast { transition: none; }
    body.single-product .nav-count-badge.gca-badge-pop { animation: none; }
}

assets/css/brand.css.content:
/* The brand story shares the site's crimson accents, generous spacing and rounded panels. */
body.genosys-brand-page{position:relative;--admin-bar-height:0px}
body.genosys-brand-page.admin-bar{--admin-bar-height:32px}
.gs-brand{--gs-brand-accent:var(--accent,#c8103b);--gs-brand-deep:var(--deep,#9f1536);--gs-brand-blush:color-mix(in srgb,var(--gs-brand-accent) 5%,#fff);--gs-brand-border:color-mix(in srgb,var(--gs-brand-accent) 15%,#fff);color:var(--ink,#455660);background:#fff;overflow:clip}
.gs-brand-hero{position:relative;isolation:isolate;display:flex;align-items:flex-end;min-height:calc(100vh - var(--admin-bar-height,0px));min-height:calc(100svh - var(--admin-bar-height,0px));padding:160px max(6vw,32px) 85px;background:#3c2530;color:#fff;overflow:hidden}
.gs-brand-hero__poster,.gs-brand-hero__video,.gs-brand-hero__shade{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.gs-brand-hero__poster{z-index:-3;display:block;object-fit:cover;object-position:center}
.gs-brand-hero__video{z-index:-2;overflow:hidden;opacity:0;transition:opacity .5s ease}
.gs-brand-hero.is-video-playing .gs-brand-hero__video{opacity:1}
.gs-brand-hero__hosted{display:block;width:100%;height:100%;object-fit:cover;object-position:center;pointer-events:none}
.gs-brand-hero__video iframe{position:absolute;left:50%;top:50%;display:block;width:max(100%,177.777778vh);width:max(100%,177.777778svh);height:max(100%,56.25vw);border:0;transform:translate(-50%,-50%);pointer-events:none}
@supports(container-type:size){.gs-brand-hero__video{container-type:size}.gs-brand-hero__video iframe{width:max(100%,177.777778cqh);height:max(100%,56.25cqw)}}
.gs-brand-hero__shade{z-index:-1;background:linear-gradient(180deg,#11171cba,transparent 40%),linear-gradient(0deg,#270611ba,transparent 76%)}
.gs-brand-hero__content{width:min(100%,1440px);margin-inline:auto}
.gs-brand-hero__eyebrow{display:inline-flex;align-items:center;gap:12px;margin:0 0 12px;font-size:clamp(16px,1.4vw,22px);font-weight:450;line-height:1.9;color:#fff}
.gs-brand-hero__eyebrow:before{content:"";width:36px;height:3px;border-radius:4px;background:var(--gs-brand-accent);box-shadow:0 0 0 1px #fff1}
.gs-brand-hero h1{color:#fff;margin:0;font-size:clamp(65px,7vw,124px);font-weight:650;letter-spacing:-.055em;line-height:1.5}
.gs-brand-hero__description{color:#fff;margin:7px 0 28px;font-size:clamp(18px,1.65vw,28px);line-height:1.9;font-weight:350}
.gs-brand-hero__link{display:inline-flex;align-items:center;justify-content:center;gap:14px;min-height:56px;padding:12px 26px;border:1px solid #ffffff28;border-radius:999px;background:var(--gs-brand-accent);box-shadow:0 12px 26px #7e092533;text-decoration:none;color:#fff;font-size:16px;font-weight:600;transition:background .2s ease,transform .2s ease}
.gs-brand-hero__link svg{width:23px;height:23px}
.gs-brand-hero__link:hover{background:var(--gs-brand-deep);color:#fff;transform:translateY(-2px)}
.gs-brand-hero__link:focus-visible{outline:2px solid #fff;outline-offset:5px}
.gs-brand-banner{position:relative;isolation:isolate;display:flex;align-items:center;justify-content:flex-start;min-height:clamp(820px,56.25vw,1080px);padding:58px clamp(36px,4.4vw,96px);background:var(--gs-brand-deep);color:#fff}
.gs-brand-banner__image{position:absolute;inset:0;z-index:-2;display:block;width:100%;height:100%;object-fit:cover;object-position:center}
.gs-brand-banner:before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,transparent 30%,#650e2b1a 42%,color-mix(in srgb,var(--gs-brand-deep) 77%,transparent) 65%,color-mix(in srgb,var(--gs-brand-deep) 90%,transparent));pointer-events:none}
.gs-brand-banner__content{width:49%;max-width:760px;text-align:center;text-shadow:0 1px 12px #27251b14}
.gs-brand-treatments{direction:ltr;display:flex;justify-content:center;align-items:center;width:min(100%,660px);margin-inline:auto}
.gs-brand-treatment{display:flex;flex-direction:column;align-items:center;justify-content:center;flex:0 0 calc(50% + 9px);aspect-ratio:1;border:1px solid rgba(255,255,255,.8);border-radius:50%;padding:28px 13px;text-align:center;background:#ffffff05}
.gs-brand-treatment+.gs-brand-treatment{margin-left:-18px}
.gs-brand-treatment h2{font-size:clamp(18px,1.15vw,22px);font-weight:400;line-height:1.75;margin:0 0 25px;color:inherit}
.gs-brand-treatment h2 span{font-size:.94em}
.gs-brand-treatment p{font-size:clamp(14px,.9vw,17px);font-weight:350;line-height:1.9;margin:0;color:inherit}
.gs-brand-next{display:flex;align-items:center;justify-content:center;width:76px;min-height:58px;margin:43px auto 4px;color:#fff9;text-decoration:none;transition:color .2s ease}
.gs-brand-next svg{display:block;width:66px;height:38px}
.gs-brand-next:hover{color:#fff}
.gs-brand-next:focus-visible{outline:2px solid #fff;outline-offset:5px;border-radius:8px}
.gs-brand-banner #gs-brand-title{color:inherit;font-size:clamp(40px,3.3vw,64px);font-weight:500;line-height:1.7;margin:0 0 20px;letter-spacing:-.035em}
.gs-brand-banner__description{max-width:690px;font-size:clamp(15px,.98vw,18px);font-weight:350;line-height:2;margin:0 auto;color:inherit;text-wrap:pretty}
.gs-brand-introduction{position:relative;text-align:center;padding:120px 28px 135px;background:radial-gradient(ellipse at 50% 0%,var(--gs-brand-blush),transparent 68%),#fff;scroll-margin-top:30px}
.gs-brand-eyebrow{display:table;margin:0 auto 26px;padding:7px 18px;border:1px solid var(--gs-brand-border);border-radius:999px;background:#fff;color:var(--gs-brand-accent);font-size:14px;font-weight:550;line-height:1.8}
.gs-brand-introduction h2{color:var(--gs-brand-accent);font-size:clamp(36px,4.1vw,76px);font-weight:550;line-height:1.6;margin:0 0 28px;letter-spacing:-.035em}
.gs-brand-introduction__subtitle{font-size:clamp(21px,1.65vw,30px);font-weight:450;line-height:1.8;margin:0 auto 24px;max-width:900px}
.gs-brand-introduction__description{font-size:clamp(17px,1.3vw,24px);font-weight:300;line-height:1.95;max-width:850px;margin:0 auto;text-wrap:pretty}
@media(min-width:1921px){.gs-brand-banner{min-height:56.25vw}.gs-brand-banner__content{margin-inline-start:3vw}}
@media(min-width:1025px) and (max-width:1300px){.gs-brand-banner{padding-inline:28px}.gs-brand-banner__content{width:51%}.gs-brand-treatment h2{font-size:18px}.gs-brand-treatment p{font-size:14px}.gs-brand-treatment{padding-inline:10px}}
@media(max-width:1024px){
 .gs-brand-banner{display:block;min-height:0;padding:0;background:var(--gs-brand-deep)}
 .gs-brand-banner__image{position:relative;inset:auto;z-index:0;width:100%;height:auto;aspect-ratio:16/9;object-fit:cover;object-position:left center}
 .gs-brand-banner:before{display:none}
 .gs-brand-banner__content{position:relative;width:100%;max-width:none;padding:52px 30px 65px;background:linear-gradient(135deg,var(--gs-brand-accent),var(--gs-brand-deep));text-shadow:none}
 .gs-brand-treatments{max-width:660px}
 .gs-brand-treatment h2{font-size:22px}
 .gs-brand-treatment p{font-size:17px}
 .gs-brand-next{margin-top:34px}
 .gs-brand-banner #gs-brand-title{font-size:52px}
 .gs-brand-banner__description{font-size:17px;max-width:690px}
 .gs-brand-introduction{padding:100px 35px 115px}
 .gs-brand-introduction h2{font-size:52px;margin-bottom:27px}
 .gs-brand-introduction__subtitle{font-size:25px}
 .gs-brand-introduction__description{font-size:21px;max-width:750px}
}
@media(max-width:600px){
 .gs-brand-hero{padding:140px 25px 72px}
 .gs-brand-hero__poster{object-position:55% center}
 .gs-brand-hero__shade{background:linear-gradient(180deg,#11171cc7,transparent 45%),linear-gradient(0deg,#270611db,transparent 80%)}
 .gs-brand-hero h1{font-size:72px;line-height:1.5}
 .gs-brand-hero__description{font-size:18px;max-width:330px;margin-bottom:25px}
 .gs-brand-hero__link{font-size:14px;min-height:52px;padding-inline:23px}
 .gs-brand-banner__image{aspect-ratio:1.35;object-position:left center}
 .gs-brand-banner__content{padding:34px 16px 44px}
 .gs-brand-treatment{flex-basis:calc(50% + 6px);padding:15px 6px}
 .gs-brand-treatment+.gs-brand-treatment{margin-left:-12px}
 .gs-brand-treatment h2{font-size:14px;line-height:1.8;margin-bottom:13px}
 .gs-brand-treatment h2 span{font-size:12px;white-space:nowrap}
 .gs-brand-treatment p{font-size:11px;line-height:1.95}
 .gs-brand-next{width:58px;min-height:44px;margin-top:26px;margin-bottom:5px}
 .gs-brand-next svg{width:48px;height:28px}
 .gs-brand-banner #gs-brand-title{font-size:34px;margin-bottom:17px}
 .gs-brand-banner__description{font-size:14px;line-height:2.05;max-width:480px}
 .gs-brand-introduction{padding:70px 24px 80px;scroll-margin-top:20px}
 .gs-brand-introduction h2{font-size:35px;line-height:1.7;margin-bottom:22px}
 .gs-brand-introduction__subtitle{font-size:20px;line-height:1.9;margin-bottom:22px}
 .gs-brand-introduction__description{font-size:17px;line-height:2.05}
}
@media(max-width:360px){.gs-brand-hero{padding-inline:22px}.gs-brand-hero h1{font-size:64px}.gs-brand-hero__description{font-size:16px}.gs-brand-banner__content{padding-inline:12px}.gs-brand-treatment h2{font-size:13px}.gs-brand-treatment h2 span{font-size:10.5px}.gs-brand-treatment p{font-size:10px}.gs-brand-banner #gs-brand-title{font-size:30px}.gs-brand-introduction h2{font-size:32px}}

/* Original brand film, the two complementary treatment stories and source figures. */
.gs-brand-shell{width:min(1440px,calc(100% - 80px));margin-inline:auto}
.gs-brand-media{min-width:0}
.gs-brand-video{position:relative;display:block;aspect-ratio:16/9;overflow:hidden;background:var(--gs-brand-blush);border:1px solid var(--gs-brand-border);border-radius:28px;isolation:isolate;box-shadow:0 13px 35px #7e09250a}
.gs-brand-video__button{position:relative;display:block;border:0;border-radius:inherit;padding:0;margin:0;width:100%;height:100%;background:#e9e9e6;color:#fff;cursor:pointer;font:inherit;overflow:hidden;text-align:center}
.gs-brand-video__button:disabled{cursor:default;opacity:1}
.gs-brand-video__button:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#14232a40,transparent 55%);pointer-events:none}
.gs-brand-video__button img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .35s ease}
.gs-brand-video__button:not(:disabled):hover img{transform:scale(1.025)}
.gs-brand-video__button:focus-visible{outline:3px solid var(--accent,#c8103b);outline-offset:-5px}
.gs-brand-video__play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:1;display:grid;place-items:center;width:76px;height:76px;border:1px solid #ffffff85;border-radius:50%;background:var(--gs-brand-accent);color:#fff;box-shadow:0 8px 28px #7e09253b}
.gs-brand-video__play svg{width:31px;height:31px;transform:translateX(-1px)}
.gs-brand-video__label{position:absolute;bottom:26px;left:50%;transform:translateX(-50%);z-index:1;color:#fff;font-size:16px;font-weight:500;text-shadow:0 1px 4px #19202870}
.gs-brand-video iframe{display:block;border:0;width:100%;height:100%;aspect-ratio:16/9}
.gs-brand-video__fallback{display:table;margin:12px 2px 0 auto;font-size:14px;color:var(--muted,#78848c);line-height:1.8;text-underline-offset:4px;text-decoration-thickness:1px}
.gs-brand-video__fallback:hover{color:var(--accent,#c8103b)}
.gs-brand-video__status{margin:8px 2px 0;color:var(--muted,#78848c);font-size:13px;line-height:1.8}
.gs-brand-video__status:empty{display:none}
.gs-brand-features{display:grid;gap:30px;padding-bottom:115px}
.gs-brand-treatment-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.06fr);gap:55px;align-items:center;padding:42px;border:1px solid var(--gs-brand-border);border-radius:36px;background:linear-gradient(120deg,#fff 46%,var(--gs-brand-blush));box-shadow:0 16px 45px #7e092505}
.gs-brand-treatment-row--reverse{background:linear-gradient(240deg,#fff 46%,var(--gs-brand-blush))}
.gs-brand-treatment-row--reverse .gs-brand-treatment-copy{grid-column:2;grid-row:1}
.gs-brand-treatment-row--reverse .gs-brand-media{grid-column:1;grid-row:1}
.gs-brand-treatment-copy h2{position:relative;color:var(--gs-brand-accent);font-size:clamp(25px,2.1vw,34px);font-weight:650;line-height:1.8;margin:0 0 25px;padding-top:20px;letter-spacing:-.02em}
.gs-brand-treatment-copy h2:before{content:"";position:absolute;inset-inline-start:0;top:0;width:46px;height:4px;border-radius:4px;background:var(--gs-brand-accent)}
.gs-brand-treatment-copy h2 span{display:block;color:var(--ink,#455660);font-weight:400;font-size:.7em;white-space:normal}
.gs-brand-treatment-copy ul{display:grid;gap:22px;list-style:none;margin:0;padding:0;max-width:580px;font-size:clamp(17px,1.23vw,21px);font-weight:350;line-height:1.95}
.gs-brand-treatment-copy li{position:relative;padding-inline-start:31px}
.gs-brand-treatment-copy li:before{content:"";position:absolute;inset-inline-start:1px;top:.59em;width:14px;height:8px;border:solid var(--accent,#c8103b);border-width:0 0 1.8px 1.8px;transform:rotate(-45deg)}
.gs-brand-comparisons{padding-top:16px}
.gs-brand-comparisons__header{text-align:center;margin-bottom:48px}
.gs-brand-comparisons__header h2{color:var(--gs-brand-accent);font-size:clamp(26px,2.1vw,36px);font-weight:650;line-height:1.8;margin:0 0 10px}
.gs-brand-comparisons__header p{font-size:16px;font-weight:350;color:var(--muted,#78848c);margin:0}
.gs-brand-comparison-panels{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:30px;align-items:stretch}
.gs-brand-comparison{min-width:0;padding:40px 38px 36px;border:1px solid var(--gs-brand-border);border-radius:32px;background:linear-gradient(180deg,var(--gs-brand-blush),#fff 38%);box-shadow:0 15px 40px #7e092508;text-align:center}
.gs-brand-comparison>h3{color:var(--gs-brand-accent);font-size:clamp(23px,1.7vw,29px);font-weight:600;line-height:1.8;margin:0 0 35px}
.gs-brand-comparison figure{margin:0 auto;max-width:100%}
.gs-brand-comparison figcaption{font-size:13px;line-height:1.9;font-weight:350;color:#657079;margin-top:13px}
.gs-brand-histology{width:388px}
.gs-brand-histology__crop{direction:ltr;width:100%;aspect-ratio:388/104;overflow:hidden}
.gs-brand-histology__crop img{display:block;width:100%;height:auto;max-width:none}
.gs-brand-histology__labels{direction:ltr;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;margin-top:7px;font-size:13px;font-weight:450}
.gs-brand-histology__labels span{direction:rtl;min-width:0}
.gs-brand-bar-figure{width:388px;padding-top:38px}
.gs-brand-bars{position:relative;isolation:isolate;direction:ltr;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));height:204px;gap:14px;padding:0 15px 40px;border-bottom:1px solid #77838a}
.gs-brand-bars:before{content:"";position:absolute;inset:0 0 40px;z-index:-1;background:repeating-linear-gradient(to top,#a5adb126 0 1px,transparent 1px 32.8px);border-bottom:1px solid #8c979d}
.gs-brand-bar{position:relative;display:flex;align-items:flex-end;justify-content:center;min-width:0;height:164px}
.gs-brand-bar__column{display:block;width:min(50px,65%);height:28%;background:#d1e8d8}
.gs-brand-bars--collagen .gs-brand-bar:nth-child(2) .gs-brand-bar__column{height:64.8%;background:#dedfe1}
.gs-brand-bars--collagen .gs-brand-bar:nth-child(3) .gs-brand-bar__column{height:100%;background:var(--gs-brand-accent)}
.gs-brand-bar__label{position:absolute;left:0;right:0;top:calc(100% + 10px);direction:rtl;font-size:13px;font-weight:400;line-height:1.6;overflow-wrap:anywhere}
.gs-brand-bars--collagen .gs-brand-bar:last-child .gs-brand-bar__label,.gs-brand-bars--absorption .gs-brand-bar:last-child .gs-brand-bar__label{font-weight:650}
.gs-brand-delivery{width:388px}
.gs-brand-delivery__legend{direction:ltr;display:flex;justify-content:center;flex-wrap:wrap;gap:24px;margin:0 0 12px;font-size:13px;line-height:1.6}
.gs-brand-delivery__legend>span{direction:rtl;display:inline-flex;align-items:center;gap:7px}
.gs-brand-key{display:inline-block;width:9px;height:9px;flex:none}
.gs-brand-key--red{background:var(--gs-brand-accent)}
.gs-brand-chart-genosys{color:var(--gs-brand-accent)}
.gs-brand-key--blue{background:#00aeef;border-radius:50%}
.gs-brand-delivery__chart{display:block;direction:ltr;width:100%;height:auto;overflow:visible;font-family:Vazirmatn,Tahoma,Arial,sans-serif}
.gs-brand-chart-grid{stroke:#a5adb1;stroke-width:.55}
.gs-brand-chart-axis{stroke:#7b8991;stroke-width:.8}
.gs-brand-chart-ticks{font-size:10px;fill:#52616a}
.gs-brand-chart-labels{font-size:10px;fill:#455660;font-weight:450}
.gs-brand-bar-figure--absorption{width:388px;padding-top:25px}
.gs-brand-bars--absorption{grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;height:174px;padding:0 8px 40px}
.gs-brand-bars--absorption:before{background:repeating-linear-gradient(to top,#a5adb126 0 1px,transparent 1px 26.8px)}
.gs-brand-bars--absorption .gs-brand-bar{height:134px}
.gs-brand-bars--absorption .gs-brand-bar__column{width:min(40px,66%);height:5.185185%;background:#d1e8d8}
.gs-brand-bars--absorption .gs-brand-bar:nth-child(2) .gs-brand-bar__column{height:11.111111%;background:#dedfe1}
.gs-brand-bars--absorption .gs-brand-bar:nth-child(3) .gs-brand-bar__column{height:20%;background:#c7eafb}
.gs-brand-bars--absorption .gs-brand-bar:nth-child(4) .gs-brand-bar__column{height:100%;background:var(--gs-brand-accent)}
.gs-brand-bars--absorption .gs-brand-bar__label{font-size:11px}
.gs-brand-closing{width:100%;margin-top:110px;padding:105px max(30px,calc((100% - 1300px)/2)) 110px;background:radial-gradient(ellipse at 50% 100%,color-mix(in srgb,var(--gs-brand-accent) 12%,#fff),var(--gs-brand-blush) 75%);border-top:1px solid var(--gs-brand-border);text-align:center}
.gs-brand-closing h2{color:var(--gs-brand-accent);font-size:clamp(38px,4.5vw,76px);font-weight:550;line-height:1.7;letter-spacing:-.03em;margin:0 0 28px}
.gs-brand-closing>p{font-size:clamp(19px,1.7vw,28px);font-weight:300;line-height:2;max-width:980px;margin:0 auto}
.gs-brand-source{display:inline-block;margin-top:40px;font-size:13px;color:var(--gs-brand-deep);text-underline-offset:5px}
.gs-brand-source:hover{color:var(--accent,#c8103b)}
@media(max-width:1100px){.gs-brand-shell{width:calc(100% - 64px)}.gs-brand-treatment-row{gap:38px;padding:32px}.gs-brand-treatment-copy h2{font-size:25px}.gs-brand-treatment-copy ul{font-size:17px;gap:18px}.gs-brand-comparison{padding-inline:25px}.gs-brand-comparison-panels{gap:22px}.gs-brand-comparison>h3{font-size:23px}.gs-brand-features{padding-bottom:100px}}
@media(max-width:820px){.gs-brand-shell{width:calc(100% - 48px)}.gs-brand-treatment-row{grid-template-columns:1fr;gap:28px}.gs-brand-treatment-row--reverse .gs-brand-treatment-copy,.gs-brand-treatment-row--reverse .gs-brand-media{grid-column:auto;grid-row:auto}.gs-brand-treatment-copy h2{font-size:28px;margin-bottom:18px}.gs-brand-treatment-copy ul{font-size:18px;max-width:none}.gs-brand-features{gap:26px;padding-bottom:80px}.gs-brand-comparison-panels{grid-template-columns:1fr;gap:24px}.gs-brand-comparison{padding:35px 30px}.gs-brand-comparison>h3{font-size:27px}.gs-brand-comparison figcaption{font-size:14px}.gs-brand-bar-figure{padding-top:35px}.gs-brand-bar-figure--absorption{padding-top:25px}.gs-brand-closing{margin-top:80px;padding-block:90px 100px}.gs-brand-closing h2{font-size:48px}.gs-brand-closing>p{font-size:23px}}
@media(max-width:782px){body.genosys-brand-page.admin-bar{--admin-bar-height:46px}}
@media(max-height:600px){.gs-brand-hero{padding-top:120px;padding-bottom:28px}.gs-brand-hero h1{font-size:clamp(48px,6vw,76px);line-height:1.3}.gs-brand-hero__eyebrow{font-size:14px;margin-bottom:6px}.gs-brand-hero__description{font-size:16px;line-height:1.6;margin:6px 0 16px}.gs-brand-hero__link{min-height:44px;padding:8px 20px;font-size:14px}}
@media(max-width:500px){.gs-brand-shell{width:calc(100% - 32px)}.gs-brand-video{border-radius:20px}.gs-brand-video__play{width:58px;height:58px}.gs-brand-video__play svg{width:27px;height:27px}.gs-brand-video__label{font-size:13px;bottom:14px}.gs-brand-video__fallback{font-size:12px;margin-top:10px}.gs-brand-treatment-row{gap:22px;padding:25px 21px;border-radius:28px}.gs-brand-treatment-copy h2{font-size:24px;line-height:1.8}.gs-brand-treatment-copy h2 span{font-size:.72em}.gs-brand-treatment-copy ul{font-size:16px;gap:15px}.gs-brand-treatment-copy li{padding-inline-start:27px}.gs-brand-features{gap:22px;padding-bottom:62px}.gs-brand-comparisons__header{margin-bottom:28px}.gs-brand-comparisons__header h2{font-size:23px}.gs-brand-comparisons__header p{font-size:14px}.gs-brand-comparison{padding:28px 16px 27px;border-radius:26px}.gs-brand-comparison>h3{font-size:22px;margin-bottom:27px}.gs-brand-comparison figcaption{font-size:12px}.gs-brand-histology__labels{font-size:12px}.gs-brand-bars{gap:10px;padding-inline:10px}.gs-brand-bar__label{font-size:12px}.gs-brand-bars--absorption{gap:7px;padding-inline:0}.gs-brand-bars--absorption .gs-brand-bar__label{font-size:10px}.gs-brand-closing{margin-top:60px;padding-block:65px 75px}.gs-brand-closing h2{font-size:34px;margin-bottom:20px}.gs-brand-closing>p{font-size:19px}.gs-brand-source{margin-top:35px;font-size:12px}}
@media(prefers-reduced-motion:reduce){.gs-brand-video__button img,.gs-brand-hero__link,.gs-brand-hero__video{transition:none}.gs-brand-video__button:not(:disabled):hover img,.gs-brand-hero__link:hover{transform:none}}

assets/css/cart.css.content:
/* The WooCommerce cart has its own layout and leaves all other pages untouched. */
.genosys-cart-page {
    direction: rtl;
    color: #1d1d24;
    background: #fff;
}

.genosys-cart-page *,
.genosys-cart-page *::before,
.genosys-cart-page *::after {
    box-sizing: border-box;
}

.genosys-cart-page .genosys-cart-container {
    width: min(100%, 1512px);
    margin-inline: auto;
    padding: 22px clamp(20px, 4.5vw, 48px) 90px;
}

.genosys-cart-page .genosys-cart-breadcrumb {
    margin: 0 0 26px;
    color: #8d8582;
    font-size: 14px;
    text-align: right;
}

.genosys-cart-page .genosys-cart-breadcrumb a {
    color: inherit;
    text-decoration: none;
}

.genosys-cart-page .genosys-cart-breadcrumb a:hover {
    color: #c8103b;
}

.genosys-cart-page .genosys-cart-heading {
    display: flex;
    align-items: baseline;
    gap: 20px;
    margin: 0 0 39px;
    color: #1d1d24;
    font-size: clamp(36px, 3.3vw, 52px);
    font-weight: 800;
    line-height: 1.45;
}

.genosys-cart-page .genosys-cart-heading h1 {
    margin: 0;
    color: inherit;
    font-size: inherit;
    font-weight: inherit;
    line-height: inherit;
}

.genosys-cart-page .genosys-cart-count {
    color: #9c837b;
    font-size: 16px;
    font-weight: 400;
    white-space: nowrap;
}

.genosys-cart-page .woocommerce-message,
.genosys-cart-page .woocommerce-info,
.genosys-cart-page .woocommerce-error {
    position: relative;
    margin: 0 0 25px;
    padding: 18px 68px 18px 24px;
    border: 1px solid #f1d5dc;
    border-radius: 20px;
    background: linear-gradient(115deg, #fff 16%, #fff6f8 100%);
    box-shadow: 0 10px 26px rgba(145, 28, 56, .06);
    color: #26242a;
    font-size: 16px;
    line-height: 1.8;
    list-style: none;
    text-align: right;
}

.genosys-cart-page .woocommerce-error {
    border-color: #ecc6d0;
    background: linear-gradient(115deg, #fff 16%, #fff0f3 100%);
}

.genosys-cart-page .woocommerce-message::before,
.genosys-cart-page .woocommerce-info::before,
.genosys-cart-page .woocommerce-error::before {
    content: "✓";
    position: absolute;
    top: 20px;
    right: 22px;
    left: auto;
    display: grid;
    place-items: center;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: #c8103b;
    color: #fff;
    font-family: Arial, sans-serif;
    font-size: 17px;
    font-weight: 700;
    line-height: 1;
}

.genosys-cart-page .woocommerce-info::before {
    content: "i";
    font-size: 18px;
}

.genosys-cart-page .woocommerce-error::before {
    content: "!";
    background: #a80c32;
    font-size: 19px;
}

.genosys-cart-page .woocommerce-error li {
    margin: 0;
    padding: 0;
    list-style: none;
}

.genosys-cart-page .woocommerce-error li + li {
    margin-block-start: 6px;
}

.genosys-cart-page .woocommerce-message a,
.genosys-cart-page .woocommerce-info a,
.genosys-cart-page .woocommerce-error a {
    color: #bd0a32;
    font-weight: 700;
    text-decoration-color: rgba(189, 10, 50, .4);
    text-underline-offset: 4px;
}

.genosys-cart-page .woocommerce-message a:hover,
.genosys-cart-page .woocommerce-info a:hover,
.genosys-cart-page .woocommerce-error a:hover {
    color: #9f072c;
    text-decoration-color: currentColor;
}

.genosys-cart-page .woocommerce-message a:focus-visible,
.genosys-cart-page .woocommerce-info a:focus-visible,
.genosys-cart-page .woocommerce-error a:focus-visible {
    border-radius: 4px;
    outline: 2px solid #c8103b;
    outline-offset: 3px;
}

.genosys-cart-page .woocommerce-message a.restore-item,
.genosys-cart-page .woocommerce-message a.button,
.genosys-cart-page .woocommerce-info a.button,
.genosys-cart-page .woocommerce-error a.button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    float: none;
    min-height: 34px;
    margin: 2px 8px 2px 0;
    padding: 3px 14px;
    border: 1px solid #eebac8;
    border-radius: 999px;
    background: #fff;
    box-shadow: none;
    color: #bd0a32;
    font: inherit;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.5;
    text-decoration: none;
    vertical-align: middle;
}

.genosys-cart-page .woocommerce-message a.restore-item:hover,
.genosys-cart-page .woocommerce-message a.button:hover,
.genosys-cart-page .woocommerce-info a.button:hover,
.genosys-cart-page .woocommerce-error a.button:hover {
    border-color: #c8103b;
    background: #c8103b;
    color: #fff;
}

.genosys-cart-page .genosys-cart-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(330px, 1fr);
    align-items: start;
    gap: 34px;
}

.genosys-cart-page .genosys-cart-items {
    display: grid;
    align-content: start;
    gap: 16px;
    min-width: 0;
}

.genosys-cart-page .genosys-cart-items__form {
    display: grid;
    gap: 16px;
    min-width: 0;
    margin: 0;
}

.genosys-cart-page .genosys-cart-item {
    display: grid;
    grid-template-columns: 138px minmax(0, 1fr) 130px;
    align-items: center;
    gap: 24px;
    min-height: 188px;
    padding: 21px 23px;
    border: 1px solid #eeeeef;
    border-radius: 34px;
    background: #fff;
    box-shadow: 0 0 0 5px #f7f7f7, 0 10px 25px rgba(30, 32, 36, .05);
    transition: box-shadow 220ms ease, border-color 220ms ease;
}

.genosys-cart-page .genosys-cart-item:hover,
.genosys-cart-page .genosys-cart-item:focus-within {
    border-color: #f4d6dc;
    box-shadow: 0 0 0 5px #f9edf0, 0 12px 26px rgba(157, 33, 65, .09);
}

.genosys-cart-page .genosys-cart-item__thumb {
    display: grid;
    place-items: center;
    width: 138px;
    height: 138px;
    overflow: hidden;
    border-radius: 25px;
    background: linear-gradient(150deg, #f9f9f9, #e3e1df);
}

.genosys-cart-page .genosys-cart-item__thumb img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.genosys-cart-page .genosys-cart-item__thumb a {
    display: block;
    width: 100%;
    height: 100%;
}

.genosys-cart-page .genosys-cart-item__details {
    min-width: 0;
    text-align: right;
}

.genosys-cart-page .genosys-cart-item__category {
    display: block;
    margin-bottom: 5px;
    color: #8b8582;
    font-size: 14px;
    line-height: 1.65;
}

.genosys-cart-page .genosys-cart-item__title {
    display: block;
    margin: 0 0 12px;
    color: #1d1d24;
    font-size: 19px;
    font-weight: 700;
    line-height: 1.65;
    text-decoration: none;
}

.genosys-cart-page .genosys-cart-item__title:hover {
    color: #c8103b;
}

.genosys-cart-page .genosys-cart-item__title a {
    color: inherit;
    text-decoration: none;
}

.genosys-cart-page .genosys-cart-item__price {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 7px;
    color: #cd0935;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.6;
}

.genosys-cart-page .genosys-cart-item__old-price {
    color: #9e9b9a;
    font-size: 14px;
    font-weight: 400;
    text-decoration: line-through;
}

.genosys-cart-page .genosys-cart-item__discount {
    display: inline-block;
    padding: 2px 11px;
    border-radius: 999px;
    background: #c60836;
    color: #fff;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.5;
    white-space: nowrap;
}

.genosys-cart-page .genosys-cart-item__actions {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    justify-content: space-between;
    align-self: stretch;
    min-width: 0;
}

.genosys-cart-page .genosys-cart-item__subtotal {
    color: #cb0731;
    font-size: 18px;
    font-weight: 750;
    line-height: 1.7;
    white-space: nowrap;
}

.genosys-cart-page .genosys-cart-item__subtotal .woocommerce-Price-currencySymbol {
    font-size: 12px;
    font-weight: 500;
}

.genosys-cart-page .genosys-cart-item__quantity,
.genosys-cart-page .genosys-cart-item__quantity .quantity {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 130px;
    height: 52px;
    border: 1px solid #e3e3e5;
    border-radius: 999px;
    background: #fff;
}

.genosys-cart-page .genosys-cart-item__quantity {
    direction: ltr;
    overflow: hidden;
}

.genosys-cart-page .genosys-cart-item__quantity .quantity {
    flex: 1 1 auto;
    width: auto;
    min-width: 0;
    height: 100%;
    border: 0;
}

.genosys-cart-page .genosys-cart-item__step {
    position: relative;
    flex: 0 0 34px;
    align-self: stretch;
    width: 34px;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    color: #ed4359;
    font-size: 0;
    line-height: 1;
    appearance: none;
    cursor: pointer;
}

.genosys-cart-page .genosys-cart-item__step::before,
.genosys-cart-page .genosys-cart-item__step--plus::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    background: currentColor;
    transform: translate(-50%, -50%);
}

.genosys-cart-page .genosys-cart-item__step::before {
    width: 18px;
    height: 1px;
}

.genosys-cart-page .genosys-cart-item__step--plus::after {
    width: 1px;
    height: 18px;
}

.genosys-cart-page .genosys-cart-item__step:hover {
    background: #fff1f4;
    color: #c8103b;
}

.genosys-cart-page .genosys-cart-item__step:focus-visible {
    outline: 2px solid #c8103b;
    outline-offset: -4px;
}

.genosys-cart-page .genosys-cart-item__step:disabled {
    opacity: .4;
    cursor: not-allowed;
}

.genosys-cart-page .genosys-cart-item__quantity input.qty {
    width: 100%;
    height: 100%;
    padding: 0 8px;
    border: 0;
    border-radius: inherit;
    background: transparent;
    color: #11131b;
    font-size: 20px;
    font-weight: 600;
    text-align: center;
    outline: none;
    appearance: textfield;
    -moz-appearance: textfield;
}

.genosys-cart-page .genosys-cart-item__quantity input.qty::-webkit-inner-spin-button,
.genosys-cart-page .genosys-cart-item__quantity input.qty::-webkit-outer-spin-button {
    margin: 0;
    -webkit-appearance: none;
}

.genosys-cart-page .genosys-cart-item__quantity:focus-within {
    border-color: #c8103b;
}

.genosys-cart-page .genosys-cart-item__remove {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #89817b;
    font-size: 14px;
    line-height: 1.5;
    text-decoration: none;
}

.genosys-cart-page .genosys-cart-item__remove:hover {
    color: #c8103b;
}

.genosys-cart-page .genosys-cart-item__remove svg {
    width: 16px;
    height: 16px;
}

.genosys-cart-page .genosys-cart-summary {
    position: sticky;
    top: 24px;
    min-width: 0;
    padding: 30px 32px 32px;
    border: 1px solid #f3c0ca;
    border-radius: 34px;
    background: radial-gradient(ellipse 95% 58% at 0% 100%, rgba(212, 27, 51, .29), transparent 88%), linear-gradient(160deg, #fff 27%, #fffafb 65%, #fbe9ed 100%);
    box-shadow: 0 18px 30px rgba(141, 28, 48, .08);
}

.genosys-cart-page .genosys-cart-summary__title {
    margin: 0 0 26px;
    color: #1d1d24;
    font-size: 25px;
    font-weight: 750;
    line-height: 1.5;
}

.genosys-cart-page .genosys-cart-summary__row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 20px;
    color: #8a8583;
    font-size: 16px;
    line-height: 1.6;
}

.genosys-cart-page .genosys-cart-summary__row > :last-child {
    color: #1d1d24;
    white-space: nowrap;
}

.genosys-cart-page .genosys-cart-summary__row--discount > :last-child {
    color: #cf0734;
    font-weight: 700;
}

.genosys-cart-page .genosys-cart-summary__coupon {
    display: flex;
    align-items: stretch;
    gap: 10px;
    margin: 26px 0 38px;
}

.genosys-cart-page .genosys-cart-summary__coupon input {
    flex: 1;
    min-width: 0;
    height: 58px;
    padding: 0 20px;
    border: 1px solid #e4e3e3;
    border-radius: 999px;
    background: #fff;
    color: #1d1d24;
    font: inherit;
    font-size: 15px;
    text-align: right;
}

.genosys-cart-page .genosys-cart-summary__coupon input:focus {
    border-color: #c8103b;
    outline: none;
}

.genosys-cart-page .genosys-cart-summary__coupon button {
    flex: 0 0 auto;
    min-width: 90px;
    height: 58px;
    padding: 0 22px;
    border: 1px solid #d20b39;
    border-radius: 999px;
    background: #fff;
    color: #cb0731;
    font: inherit;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
}

.genosys-cart-page .genosys-cart-summary__coupon button:hover {
    background: #c8103b;
    color: #fff;
}

.genosys-cart-page .genosys-cart-summary__applied-coupon {
    margin: -24px 0 28px;
    color: #8a8583;
    font-size: 13px;
}

.genosys-cart-page .genosys-cart-summary__applied-coupon a {
    margin-inline-start: 8px;
    color: #c8103b;
    text-decoration: none;
}

.genosys-cart-page .genosys-cart-summary__total {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
    padding: 28px 0 26px;
    border-top: 1px solid rgba(115, 99, 104, .19);
    color: #1d1d24;
    font-size: 19px;
    font-weight: 650;
}

.genosys-cart-page .genosys-cart-summary__total strong {
    color: #c8103b;
    font-size: clamp(25px, 2vw, 32px);
    font-weight: 800;
    white-space: nowrap;
}

.genosys-cart-page .genosys-cart-summary__total small {
    color: #1d1d24;
    font-size: 14px;
    font-weight: 400;
}

.genosys-cart-page .genosys-cart-summary__total .woocommerce-Price-currencySymbol {
    color: #1d1d24;
    font-size: 14px;
    font-weight: 400;
}

.genosys-cart-page .genosys-cart-summary__checkout {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-height: 65px;
    padding: 14px 26px;
    border: 0;
    border-radius: 999px;
    background: linear-gradient(105deg, #ce0734, #a7062b);
    box-shadow: 0 12px 19px rgba(188, 6, 48, .25);
    color: #fff;
    font: inherit;
    font-size: 18px;
    font-weight: 750;
    line-height: 1.5;
    text-align: center;
    text-decoration: none;
    cursor: pointer;
}

.genosys-cart-page .genosys-cart-summary__checkout:hover {
    color: #fff;
    background: linear-gradient(105deg, #db0d3d, #b50831);
    box-shadow: 0 15px 23px rgba(188, 6, 48, .32);
}

.genosys-cart-page .genosys-cart-summary__trust {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 7px 10px;
    margin-top: 22px;
    color: #8d8483;
    font-size: 12px;
    line-height: 1.65;
}

.genosys-cart-page .genosys-cart-continue {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    justify-self: start;
    margin-top: 4px;
    color: #8d847f;
    font-size: 15px;
    text-decoration: none;
}

.genosys-cart-page .genosys-cart-continue:hover {
    color: #c8103b;
}

.genosys-cart-page .genosys-cart-empty {
    padding: 60px 28px;
    border: 1px solid #f2d4d9;
    border-radius: 34px;
    background: #fffafb;
    text-align: center;
}

.genosys-cart-page .genosys-cart-empty h2 {
    margin: 0 0 12px;
    font-size: 27px;
}

.genosys-cart-page .genosys-cart-empty p {
    margin: 0 0 26px;
    font-size: 20px;
}

.genosys-cart-page .genosys-cart-empty a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 50px;
    padding: 10px 28px;
    border-radius: 999px;
    background: #c8103b;
    color: #fff;
    text-decoration: none;
}

.genosys-cart-page .genosys-cart-update {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
}

.genosys-cart-page .genosys-cart-update:focus-visible {
    position: static;
    width: auto;
    height: auto;
    padding: 7px 14px;
    margin: 0;
    overflow: visible;
    clip-path: none;
    border: 1px solid #c8103b;
    border-radius: 999px;
    background: #fff;
    color: #c8103b;
}

@media (max-width: 1180px) {
    .genosys-cart-page .genosys-cart-layout {
        grid-template-columns: minmax(0, 1.5fr) minmax(300px, 1fr);
        gap: 25px;
    }

    .genosys-cart-page .genosys-cart-item {
        grid-template-columns: 116px minmax(0, 1fr) 116px;
        gap: 17px;
        padding-inline: 19px;
    }

    .genosys-cart-page .genosys-cart-item__thumb {
        width: 116px;
        height: 116px;
    }

    .genosys-cart-page .genosys-cart-item__quantity,
    .genosys-cart-page .genosys-cart-item__quantity .quantity {
        width: 116px;
    }

    .genosys-cart-page .genosys-cart-summary {
        padding-inline: 25px;
    }
}

@media (max-width: 960px) {
    .genosys-cart-page .genosys-cart-layout {
        grid-template-columns: minmax(0, 1fr);
    }

    .genosys-cart-page .genosys-cart-summary {
        position: static;
        grid-row: 2;
    }
}

@media (max-width: 640px) {
    .genosys-cart-page .genosys-cart-container {
        padding: 20px 18px 65px;
    }

    .genosys-cart-page .woocommerce-message,
    .genosys-cart-page .woocommerce-info,
    .genosys-cart-page .woocommerce-error {
        padding: 15px 57px 15px 16px;
        border-radius: 17px;
        font-size: 14px;
    }

    .genosys-cart-page .woocommerce-message::before,
    .genosys-cart-page .woocommerce-info::before,
    .genosys-cart-page .woocommerce-error::before {
        top: 16px;
        right: 16px;
        width: 28px;
        height: 28px;
    }

    .genosys-cart-page .genosys-cart-heading {
        gap: 11px;
        margin-bottom: 28px;
        font-size: 35px;
    }

    .genosys-cart-page .genosys-cart-count {
        font-size: 13px;
    }

    .genosys-cart-page .genosys-cart-item {
        grid-template-columns: 98px minmax(0, 1fr);
        gap: 12px 15px;
        min-height: 0;
        padding: 15px;
        border-radius: 25px;
    }

    .genosys-cart-page .genosys-cart-item__thumb {
        width: 98px;
        height: 98px;
        border-radius: 17px;
    }

    .genosys-cart-page .genosys-cart-item__details {
        align-self: start;
    }

    .genosys-cart-page .genosys-cart-item__category {
        font-size: 12px;
    }

    .genosys-cart-page .genosys-cart-item__title {
        margin-bottom: 6px;
        font-size: 15px;
    }

    .genosys-cart-page .genosys-cart-item__price {
        font-size: 13px;
    }

    .genosys-cart-page .genosys-cart-item__old-price {
        font-size: 12px;
    }

    .genosys-cart-page .genosys-cart-item__discount {
        font-size: 10px;
    }

    .genosys-cart-page .genosys-cart-item__actions {
        grid-column: 1 / -1;
        display: flex;
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
        gap: 10px;
        padding-top: 12px;
        border-top: 1px solid #f1eeee;
    }

    .genosys-cart-page .genosys-cart-item__subtotal {
        font-size: 14px;
    }

    .genosys-cart-page .genosys-cart-item__quantity,
    .genosys-cart-page .genosys-cart-item__quantity .quantity {
        width: 88px;
        height: 42px;
    }

    .genosys-cart-page .genosys-cart-item__quantity input.qty {
        font-size: 17px;
    }

    .genosys-cart-page .genosys-cart-item__step {
        flex-basis: 26px;
        width: 26px;
    }

    .genosys-cart-page .genosys-cart-item__step::before {
        width: 15px;
    }

    .genosys-cart-page .genosys-cart-item__step--plus::after {
        height: 15px;
    }

    .genosys-cart-page .genosys-cart-summary {
        padding: 25px 22px;
        border-radius: 25px;
    }

    .genosys-cart-page .genosys-cart-summary__title {
        font-size: 22px;
    }

    .genosys-cart-page .genosys-cart-summary__row {
        font-size: 14px;
    }

    .genosys-cart-page .genosys-cart-summary__row > :last-child {
        max-width: 58%;
        white-space: normal;
        text-align: left;
    }

    .genosys-cart-page .genosys-cart-summary__total {
        flex-wrap: wrap;
        font-size: 16px;
    }

    .genosys-cart-page .genosys-cart-summary__total strong {
        font-size: 24px;
    }

    .genosys-cart-page .genosys-cart-summary__checkout {
        min-height: 58px;
        font-size: 16px;
    }
}

@media (max-width: 390px) {
    .genosys-cart-page .genosys-cart-item {
        grid-template-columns: 82px minmax(0, 1fr);
        gap: 10px;
        padding: 12px;
    }

    .genosys-cart-page .genosys-cart-item__thumb {
        width: 82px;
        height: 82px;
    }

    .genosys-cart-page .genosys-cart-item__remove {
        font-size: 12px;
    }

    .genosys-cart-page .genosys-cart-summary__coupon input,
    .genosys-cart-page .genosys-cart-summary__coupon button {
        height: 50px;
    }

    .genosys-cart-page .genosys-cart-summary__coupon button {
        min-width: 70px;
        padding-inline: 12px;
        font-size: 14px;
    }
}

@media (prefers-reduced-motion: reduce) {
    .genosys-cart-page .genosys-cart-item {
        transition: none;
    }
}

assets/css/checkout.css.content:
/* Checkout is intentionally self-contained; existing cart and product pages are untouched. */
.genosys-checkout {
    --gco-crimson: #c80936;
    --gco-deep-red: #a8062e;
    --gco-ink: #202027;
    --gco-muted: #8c8584;
    direction: rtl;
    color: var(--gco-ink);
    background: #fff;
    min-height: 70vh;
    font-family: Vazirmatn, Tahoma, Arial, sans-serif;
}

.genosys-checkout *,
.genosys-checkout *::before,
.genosys-checkout *::after { box-sizing: border-box; }

.genosys-checkout .gco-container {
    width: min(100%, 1500px);
    margin-inline: auto;
    padding: 22px clamp(20px, 4.3vw, 56px) 100px;
}

.genosys-checkout .gco-steps {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    min-height: 74px;
    margin: 0 0 38px;
    padding: 0;
    list-style: none;
}

.genosys-checkout .gco-step {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    color: #807d7c;
    font-size: 15px;
    font-weight: 700;
    white-space: nowrap;
}

.genosys-checkout .gco-step--current { color: #15161e; }
.genosys-checkout .gco-step--complete { color: #878385; }

.genosys-checkout .gco-step__number {
    display: grid;
    place-items: center;
    flex: 0 0 38px;
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: #f7f7f7;
    color: #968d8d;
    font-weight: 800;
}

.genosys-checkout .gco-step--current .gco-step__number {
    background: linear-gradient(145deg, #d3093b, #a5052d);
    box-shadow: 0 9px 18px rgba(200, 9, 54, .22);
    color: #fff;
}

.genosys-checkout .gco-step--complete .gco-step__number {
    background: #fae7ec;
    color: var(--gco-crimson);
}

.genosys-checkout .gco-steps__line,
.genosys-checkout .gco-step__line {
    flex: 0 0 56px;
    width: 56px;
    height: 1px;
    background: #e0dede;
}

.genosys-checkout .gco-steps__line--complete { background: var(--gco-crimson); }

.genosys-checkout form.checkout.gco-layout,
.genosys-checkout .gco-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.6fr) minmax(360px, 1fr);
    align-items: start;
    gap: 36px;
    margin: 0;
}

/* Woo prepends validation notices to the form. They must span both grid columns
   instead of becoming a new narrow column beside the customer details. */
.genosys-checkout form.checkout.gco-layout > .woocommerce-NoticeGroup,
.genosys-checkout form.checkout.gco-layout > .woocommerce-error,
.genosys-checkout form.checkout.gco-layout > .woocommerce-message,
.genosys-checkout form.checkout.gco-layout > .woocommerce-info,
.genosys-checkout form.checkout.gco-layout > .wc-block-components-notice-banner {
    grid-column: 1 / -1;
    min-width: 0;
    width: 100%;
    margin: 0;
}

.genosys-checkout form.checkout.gco-layout > .woocommerce-NoticeGroup:empty { display: none; }
.genosys-checkout .woocommerce-NoticeGroup a { color: var(--gco-crimson); }

.genosys-checkout .gco-main {
    position: relative;
    display: grid;
    align-content: start;
    gap: 26px;
    min-width: 0;
}

.genosys-checkout .gco-panel {
    min-width: 0;
    padding: 31px 36px 39px;
    border: 1px solid #ededee;
    border-radius: 35px;
    background: #fff;
    box-shadow: 0 0 0 5px #f7f7f7, 0 13px 28px rgba(35, 28, 31, .04);
}

.genosys-checkout .gco-panel__heading {
    display: flex;
    align-items: center;
    gap: 16px;
    margin: 0 0 24px;
    color: #14151d;
    font-size: 23px;
    font-weight: 800;
    line-height: 1.5;
}

.genosys-checkout .gco-panel__number {
    display: grid;
    place-items: center;
    flex: 0 0 43px;
    width: 43px;
    height: 43px;
    border-radius: 50%;
    background: linear-gradient(135deg, #d00936, #ab072e);
    color: #fff;
    font-size: 17px;
    font-weight: 800;
    line-height: 1;
}

.genosys-checkout .gco-panel__intro {
    margin: 0 0 24px;
    color: var(--gco-muted);
    font-size: 15px;
    line-height: 1.9;
}

.genosys-checkout .gco-fields {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 20px;
    row-gap: 24px;
}

.genosys-checkout .gco-fields--address { row-gap: 26px; }
.genosys-checkout .gco-fields .gco-field--wide,
.genosys-checkout .gco-fields .form-row-wide { grid-column: 1 / -1; }
.genosys-checkout .gco-fields .gco-field--postal { grid-column: 1; }

.genosys-checkout .gco-fields p.form-row,
.genosys-checkout .gco-field,
.genosys-checkout .woocommerce-billing-fields__field-wrapper .form-row,
.genosys-checkout .woocommerce-shipping-fields__field-wrapper .form-row {
    float: none;
    width: auto;
    min-width: 0;
    margin: 0;
    padding: 0;
}

.genosys-checkout .gco-fields label,
.genosys-checkout .gco-field label,
.genosys-checkout .form-row > label {
    display: block;
    margin: 0 0 11px;
    color: #191922;
    font-size: 15px;
    font-weight: 650;
    line-height: 1.6;
    text-align: right;
}

.genosys-checkout .required { color: var(--gco-crimson); text-decoration: none; }
.genosys-checkout .optional { color: var(--gco-muted); font-weight: 400; }

.genosys-checkout .gco-fields input:not([type="checkbox"]):not([type="radio"]),
.genosys-checkout .gco-fields textarea,
.genosys-checkout .gco-fields select,
.genosys-checkout .gco-field input:not([type="checkbox"]):not([type="radio"]),
.genosys-checkout .gco-field textarea,
.genosys-checkout .gco-field select,
.genosys-checkout .form-row input.input-text,
.genosys-checkout .form-row select,
.genosys-checkout .form-row textarea,
.genosys-checkout .select2-container .select2-selection--single {
    display: block;
    width: 100%;
    min-width: 0;
    min-height: 62px;
    margin: 0;
    padding: 14px 18px;
    border: 1px solid #e0e0e1;
    border-radius: 19px;
    background: #fff;
    box-shadow: none;
    color: #181922;
    font: inherit;
    font-size: 16px;
    text-align: right;
    line-height: 1.6;
    outline: none;
}

.genosys-checkout .form-row textarea,
.genosys-checkout .gco-fields textarea,
.genosys-checkout .gco-field textarea {
    width: 100%;
    min-height: 112px;
    padding: 17px 18px;
    border: 1px solid #e0e0e1;
    border-radius: 19px;
    background: #fff;
    box-shadow: none;
    color: #181922;
    font: inherit;
    font-size: 16px;
    line-height: 1.7;
    text-align: right;
    resize: vertical;
}

.genosys-checkout .gco-fields input::placeholder,
.genosys-checkout .gco-fields textarea::placeholder,
.genosys-checkout .gco-field input::placeholder,
.genosys-checkout .gco-field textarea::placeholder { color: #868184; opacity: 1; }

.genosys-checkout .gco-fields input:focus,
.genosys-checkout .gco-fields textarea:focus,
.genosys-checkout .gco-fields select:focus,
.genosys-checkout .gco-field input:focus,
.genosys-checkout .gco-field textarea:focus,
.genosys-checkout .gco-field select:focus,
.genosys-checkout .form-row input.input-text:focus,
.genosys-checkout .form-row select:focus,
.genosys-checkout .form-row textarea:focus,
.genosys-checkout .select2-container--focus .select2-selection--single {
    border-color: var(--gco-crimson);
    box-shadow: 0 0 0 4px rgba(200, 9, 54, .08);
}

.genosys-checkout .woocommerce-invalid input.input-text,
.genosys-checkout .woocommerce-invalid select,
.genosys-checkout .woocommerce-invalid textarea,
.genosys-checkout .woocommerce-invalid .select2-selection--single { border-color: #d20a39 !important; }
.genosys-checkout .gco-fields .checkout-inline-error-message,
.genosys-checkout .gco-field .checkout-inline-error-message {
    display: block;
    margin: 7px 0 0;
    padding: 0;
    color: #d20a39;
    font-size: 13px;
    font-weight: 500;
    line-height: 1.65;
    text-align: right;
}
.genosys-checkout .gco-account-fields { margin-top: 22px; padding-top: 18px; border-top: 1px solid #f0e7e9; }
.genosys-checkout .gco-account-fields .create-account { margin: 0; padding: 0; }
.genosys-checkout .gco-account-fields .woocommerce-form__label-for-checkbox,
.genosys-checkout .gco-account-fields .create-account > label { display: inline-flex; align-items: center; gap: 9px; margin: 0; color: #4e484b; font-size: 14px; font-weight: 500; cursor: pointer; }
.genosys-checkout .gco-account-fields input[type="checkbox"] { width: 18px; height: 18px; margin: 0; accent-color: var(--gco-crimson); }
.genosys-checkout .gco-account-fields .create-account .form-row { margin-top: 16px; }
.genosys-checkout .woocommerce-error,
.genosys-checkout .woocommerce-message,
.genosys-checkout .woocommerce-info {
    margin: 0 0 22px;
    padding: 16px 22px;
    border: 1px solid #efd4db;
    border-radius: 18px;
    background: #fff8fa;
    color: #25232a;
    list-style: none;
    text-align: right;
}
.genosys-checkout .woocommerce-error li { margin: 0; list-style: none; }

.genosys-checkout .select2-container .select2-selection--single { position: relative; padding-top: 12px; }
.genosys-checkout .select2-container .select2-selection__rendered { padding: 0 0 0 22px; color: inherit; line-height: 36px; }
.genosys-checkout .select2-container .select2-selection__arrow { left: 12px; right: auto; height: 100%; }
.genosys-checkout select { cursor: pointer; }

.genosys-checkout .gco-shipping-options { display: grid; gap: 14px; }
.genosys-checkout .gco-shipping-option {
    position: relative;
    display: flex;
    align-items: center;
    gap: 16px;
    min-height: 105px;
    padding: 16px 22px;
    border: 1px solid #f2beca;
    border-radius: 27px;
    background: #fff;
    cursor: pointer;
    transition: border-color 200ms ease, background 200ms ease, box-shadow 200ms ease;
}
.genosys-checkout .gco-shipping-option:has(input:checked) {
    border-color: #cf0b3a;
    background: radial-gradient(ellipse at 6% 80%, rgba(218, 13, 55, .09), transparent 64%), #fffafa;
    box-shadow: 0 8px 17px rgba(185, 22, 55, .1);
}
.genosys-checkout .gco-shipping-option input[type="radio"] {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: 0;
    opacity: 0;
}
.genosys-checkout .gco-shipping-option__radio {
    display: grid;
    place-items: center;
    flex: 0 0 28px;
    width: 28px;
    height: 28px;
    border: 2px solid #dddfe0;
    border-radius: 50%;
    background: #fff;
}
.genosys-checkout .gco-shipping-option input:checked + .gco-shipping-option__radio { border-color: var(--gco-crimson); }
.genosys-checkout .gco-shipping-option input:checked + .gco-shipping-option__radio::after { content: ""; width: 13px; height: 13px; border-radius: 50%; background: var(--gco-crimson); }
.genosys-checkout .gco-shipping-option input:focus-visible + .gco-shipping-option__radio { outline: 2px solid var(--gco-crimson); outline-offset: 3px; }
.genosys-checkout .gco-shipping-option__text { flex: 1 1 auto; min-width: 0; }
.genosys-checkout .gco-shipping-option__title,
.genosys-checkout .gco-shipping-option__name { display: block; color: #171720; font-weight: 700; }
.genosys-checkout .gco-shipping-option__description { display: block; margin-top: 2px; color: var(--gco-muted); font-size: 14px; }
.genosys-checkout .gco-shipping-option__price { margin-inline-start: auto; color: var(--gco-crimson); font-size: 15px; font-weight: 700; white-space: nowrap; }

/* WooCommerce may refresh this markup through update_order_review. */
.genosys-checkout #order_review,
.genosys-checkout .woocommerce-checkout-review-order { min-width: 0; }
.genosys-checkout #shipping_method,
.genosys-checkout .woocommerce-shipping-methods { display: grid; gap: 14px; margin: 0; padding: 0; list-style: none; }
.genosys-checkout #shipping_method li,
.genosys-checkout .woocommerce-shipping-methods li { display: flex; align-items: center; gap: 12px; margin: 0; padding: 16px 20px; border: 1px solid #f2beca; border-radius: 24px; background: #fff; list-style: none; }
.genosys-checkout #shipping_method li:has(input:checked),
.genosys-checkout .woocommerce-shipping-methods li:has(input:checked) { border-color: var(--gco-crimson); background: #fff7f9; box-shadow: 0 8px 17px rgba(185, 22, 55, .08); }
.genosys-checkout #shipping_method input[type="radio"],
.genosys-checkout .woocommerce-shipping-methods input[type="radio"] { flex: 0 0 22px; width: 22px; height: 22px; margin: 0; accent-color: var(--gco-crimson); }
.genosys-checkout #shipping_method label,
.genosys-checkout .woocommerce-shipping-methods label { display: block; flex: 1 1 auto; margin: 0; color: #202027; cursor: pointer; }

.genosys-checkout .gco-payment { text-align: right; }
.genosys-checkout #payment.gco-payment-processing {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: 0;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
}
.genosys-checkout #payment.gco-payment-processing--unavailable {
    position: static;
    width: auto;
    height: auto;
    overflow: visible;
    clip-path: none;
    white-space: normal;
}
.genosys-checkout .gco-payment-unavailable { margin: 0; }
.genosys-checkout .gco-payment__intro { margin: 0 0 26px; color: var(--gco-muted); font-size: 15px; text-align: center; }
.genosys-checkout #payment,
.genosys-checkout .woocommerce-checkout-payment { border: 0; border-radius: 0; background: transparent; }
.genosys-checkout #payment ul.payment_methods,
.genosys-checkout .wc_payment_methods { margin: 0 0 22px; padding: 0; border: 0; list-style: none; }
.genosys-checkout #payment li.wc_payment_method,
.genosys-checkout .wc_payment_methods li.wc_payment_method { margin: 0 0 12px; padding: 17px 20px; border: 1px solid #f2beca; border-radius: 22px; background: #fff; list-style: none; }
.genosys-checkout #payment li.wc_payment_method:has(input:checked),
.genosys-checkout .wc_payment_methods li.wc_payment_method:has(input:checked) { border-color: var(--gco-crimson); background: #fff7f9; }
.genosys-checkout #payment li.wc_payment_method > input[type="radio"],
.genosys-checkout .wc_payment_methods li.wc_payment_method > input[type="radio"] { width: 21px; height: 21px; margin: 0 0 0 10px; accent-color: var(--gco-crimson); vertical-align: middle; }
.genosys-checkout #payment li.wc_payment_method > label,
.genosys-checkout .wc_payment_methods li.wc_payment_method > label { color: #1b1b23; font-size: 16px; font-weight: 700; cursor: pointer; }
.genosys-checkout #payment .payment_box,
.genosys-checkout .wc_payment_methods .payment_box { margin: 15px 0 0; padding: 14px 16px; border: 0; border-radius: 14px; background: #fff; color: var(--gco-muted); font-size: 14px; }
.genosys-checkout #payment .payment_box::before,
.genosys-checkout .wc_payment_methods .payment_box::before { display: none; }
.genosys-checkout #payment .place-order { float: none; margin: 0; padding: 0; background: transparent; }
.genosys-checkout #payment li.payment_method_genosys_card_to_card { margin: 0; padding: 0; border: 0; background: transparent; }
