    font-size: clamp(21px, 2vw, 26px);
    font-weight: 800;
    line-height: 1.6;
    text-align: right;
}
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details {
    width: 100%;
    margin: 0;
    border: 1px solid #ebe7e8;
    border-collapse: separate;
    border-spacing: 0;
    border-radius: 19px;
    background: #fff;
    overflow: hidden;
    font-size: 15px;
    line-height: 1.8;
    text-align: right;
}
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details th,
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details td {
    width: auto;
    padding: 15px 20px;
    border: 0;
    border-bottom: 1px solid #f0ebec;
    background: transparent;
    color: var(--gco-ink);
    text-align: right;
    vertical-align: top;
    overflow-wrap: anywhere;
}
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details thead { background: #f8f7f7; }
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details thead th {
    color: #6f696b;
    font-size: 13px;
    font-weight: 700;
}
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details thead th:first-child { width: 70%; }
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details tbody td a {
    color: var(--gco-ink);
    font-weight: 750;
    text-decoration: none;
}
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details tbody td a:hover { color: var(--gco-crimson); }
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details tbody .product-quantity { color: var(--gco-muted); }
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details tfoot th {
    color: #777173;
    font-size: 14px;
    font-weight: 600;
}
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details tfoot td { font-weight: 700; }
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details tfoot td .woocommerce-Price-amount { color: var(--gco-crimson); font-weight: 800; }
.genosys-checkout .woocommerce-order table.woocommerce-table--order-details tfoot tr:last-child > * { border-bottom: 0; }

.genosys-checkout .woocommerce-order .woocommerce-customer-details .woocommerce-columns--addresses {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: stretch;
    gap: 24px;
    margin: 0;
}
.genosys-checkout .woocommerce-order .woocommerce-customer-details .woocommerce-columns--addresses::before,
.genosys-checkout .woocommerce-order .woocommerce-customer-details .woocommerce-columns--addresses::after {
    content: none;
    display: none;
}
.genosys-checkout .woocommerce-order .woocommerce-customer-details .woocommerce-column:only-child { grid-column: 1 / -1; }
.genosys-checkout .woocommerce-order .woocommerce-customer-details .woocommerce-column {
    float: none;
    clear: none;
    min-width: 0;
    width: auto;
    margin: 0;
    padding: 24px 26px;
    border: 1px solid #eee5e7;
    border-radius: 23px;
    background: linear-gradient(155deg, #fff 70%, #fffbfc);
    box-shadow: 0 8px 20px rgba(44, 29, 35, .035);
    text-align: right;
}
.genosys-checkout .woocommerce-order .woocommerce-customer-details .woocommerce-column__title {
    margin: 0 0 15px;
    color: var(--gco-ink);
    font-size: 19px;
    font-weight: 800;
    line-height: 1.6;
}
.genosys-checkout .woocommerce-order .woocommerce-customer-details address {
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: #4f4b50;
    font-size: 15px;
    font-style: normal;
    line-height: 2;
    text-align: right;
    overflow-wrap: anywhere;
}
.genosys-checkout .woocommerce-order .woocommerce-customer-details address p {
    margin: 14px 0 0;
    padding-top: 12px;
    border-top: 1px solid #f0e9eb;
    line-height: 1.8;
}
.genosys-checkout .woocommerce-order .woocommerce-customer-details > address {
    padding: 24px 26px;
    border: 1px solid #eee5e7;
    border-radius: 23px;
    background: linear-gradient(155deg, #fff 70%, #fffbfc);
    box-shadow: 0 8px 20px rgba(44, 29, 35, .035);
}
.genosys-checkout .woocommerce-order .woocommerce-customer-details address p a { color: var(--gco-ink); text-decoration: none; }
.genosys-checkout .woocommerce-order .woocommerce-customer-details address p a:hover { color: var(--gco-crimson); }

@media (max-width: 900px) {
    .genosys-checkout .woocommerce-order ul.woocommerce-order-overview { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1px; background: #eee8e9; }
    .genosys-checkout .woocommerce-order ul.woocommerce-order-overview > li { border: 0; background: #fff; }
    .genosys-checkout .woocommerce-order ul.woocommerce-order-overview > li.woocommerce-order-overview__email { grid-column: 1 / -1; }
    .genosys-checkout .woocommerce-order ul.woocommerce-order-overview > li.woocommerce-order-overview__total:last-child { grid-column: 1 / -1; }
    .genosys-checkout .woocommerce-order .woocommerce-customer-details .woocommerce-columns--addresses { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 620px) {
    .genosys-checkout .woocommerce-order { padding-block: 12px 22px; }
    .genosys-checkout .woocommerce-order .woocommerce-thankyou-order-received { min-height: 0; padding: 18px; border-radius: 21px; font-size: 17px; }
    .genosys-checkout .woocommerce-order .woocommerce-thankyou-order-received::before { flex-basis: 40px; width: 40px; height: 40px; font-size: 20px; }
    .genosys-checkout .woocommerce-order ul.woocommerce-order-overview { border-radius: 21px; }
    .genosys-checkout .woocommerce-order ul.woocommerce-order-overview > li { padding: 15px 17px; }
    .genosys-checkout .woocommerce-order ul.woocommerce-order-overview > li strong { font-size: 15px; }
    .genosys-checkout .woocommerce-order .woocommerce-order-details { margin-top: 30px; padding: 20px 16px; border-radius: 24px; }
    .genosys-checkout .woocommerce-order .woocommerce-customer-details { margin-top: 30px; }
    .genosys-checkout .woocommerce-order table.woocommerce-table--order-details th,
    .genosys-checkout .woocommerce-order table.woocommerce-table--order-details td { padding: 12px 11px; font-size: 13px; }
    .genosys-checkout .woocommerce-order table.woocommerce-table--order-details thead th:first-child { width: 62%; }
    .genosys-checkout .woocommerce-order .woocommerce-customer-details .woocommerce-column,
    .genosys-checkout .woocommerce-order .woocommerce-customer-details > address { padding: 19px; border-radius: 19px; }
}

@media (max-width: 360px) {
    .genosys-checkout .woocommerce-order ul.woocommerce-order-overview { grid-template-columns: minmax(0, 1fr); }
}

assets/css/club-admin.css.content:
@font-face{font-family:VazirmatnClub;src:url('../fonts/Vazirmatn-Variable.woff2') format('woff2');font-weight:100 900;font-style:normal;font-display:swap}
.genosys-club-adminpage{background:#f0f0f1}
.genosys-club-adminpage #wpcontent{padding-left:0;padding-right:0}
/* The theme sets an RTL admin direction even when WordPress runs in English. */
@media(min-width:783px){.genosys-club-adminpage #wpcontent{margin-right:160px;margin-left:0}.genosys-club-adminpage.folded #wpcontent{margin-right:36px}}
@media(min-width:783px) and (max-width:960px){.genosys-club-adminpage.auto-fold #wpcontent{margin-right:36px}}
@media(max-width:782px){.genosys-club-adminpage #wpcontent{margin-right:0;margin-left:0}.genosys-club-adminpage #wpadminbar #wp-admin-bar-menu-toggle .ab-item{margin-left:0}}
.genosys-club-adminpage #wpbody-content>.notice,.genosys-club-adminpage #wpbody-content>.updated,.genosys-club-adminpage #wpbody-content>.error,.genosys-club-adminpage #wpbody-content>.update-nag{display:none}
.genosys-club-adminpage #wpfooter{display:none}
.genosys-club-adminpage .a11y-speak-region{left:1px;right:auto}
.gca,.gca *{box-sizing:border-box}
.gca{--gca-red:#ce0638;--gca-deep:#ae002b;--gca-ink:#24252a;--gca-muted:#7b7875;--gca-border:#f9dce0;--gca-grey:#f0f0f1;--gca-shadow:0 12px 18px -8px #bd003e55;font-family:VazirmatnClub,Vazirmatn,Tahoma,sans-serif;color:var(--gca-ink);font-size:16px;line-height:1.8;max-width:1734px;margin:0 auto;padding:36px 32px 80px;direction:rtl}
.gca button,.gca input,.gca select,.gca textarea{font:inherit;color:inherit}
.gca button,.gca a,.gca input,.gca select,.gca textarea{outline-offset:4px}
.gca button:focus-visible,.gca a:focus-visible,.gca [tabindex]:focus-visible{outline:2px solid var(--gca-red)}
.gca [hidden]{display:none!important}
.gca svg{width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}
.gca .gca__sprite{position:absolute;width:0;height:0;overflow:hidden}
.gca__sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.gca__header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin:0 0 30px}
.gca__header h1{margin:0;font-size:36px;line-height:1.6;font-weight:850;color:var(--gca-ink)}
.gca__header p{margin:8px 0 0;color:var(--gca-muted);font-size:16px}
.gca__header-actions{display:flex;align-items:center;gap:13px;padding-top:17px;flex:none}
.gca__button{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:57px;padding:11px 29px;border:1px solid transparent;border-radius:999px;background:linear-gradient(105deg,#d4073d,#ac0029);box-shadow:var(--gca-shadow);color:#fff!important;font-weight:750;font-size:17px;line-height:1.6;text-decoration:none;cursor:pointer;transition:background .15s,opacity .15s,box-shadow .15s;white-space:nowrap}
.gca__button:hover{background:linear-gradient(105deg,#bc0032,#980022);color:#fff}
.gca__button--outline{background:#fff;border-color:var(--gca-red);color:var(--gca-red)!important;box-shadow:none}
.gca__button--outline:hover{background:#fff4f6;color:var(--gca-red)}
.gca__button:disabled,.gca__button[aria-disabled=true]{opacity:.45;cursor:not-allowed;box-shadow:none}
.gca__stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin-bottom:25px}
.gca__stat{min-height:115px;padding:20px 25px;display:flex;align-items:center;gap:18px;background:#fff;border:1px solid var(--gca-border);border-radius:28px}
.gca__stat-icon{width:60px;height:60px;border-radius:50%;background:#be0032;color:white;display:flex;align-items:center;justify-content:center;flex:none}
.gca__stat-icon svg{width:27px;height:27px}
.gca__stat-icon[data-color=green]{background:#207e3c}.gca__stat-icon[data-color=amber]{background:#bb7b18}.gca__stat-icon[data-color=charcoal]{background:#424b58}
.gca__stat-copy{display:flex;flex-direction:column;gap:2px;min-width:0}
.gca__stat-copy strong{font-size:29px;line-height:1.4;font-weight:800;unicode-bidi:plaintext}
.gca__stat-copy span{font-size:16px;color:var(--gca-muted)}
.gca__panel{background:#fff;border:1px solid var(--gca-border);border-radius:33px;overflow:hidden;box-shadow:0 2px 2px #00000002}
.gca__tabs{display:flex;gap:25px;align-items:stretch;padding:0 34px;border-bottom:1px solid #ddd;height:77px}
.gca__tab{position:relative;display:flex;align-items:center;gap:9px;flex:none;background:none;border:0;padding:20px 9px;font-size:17px!important;font-weight:700!important;color:var(--gca-muted)!important;cursor:pointer}
.gca__tab span{display:inline-flex;min-width:31px;height:25px;padding:0 8px;border-radius:20px;align-items:center;justify-content:center;background:#f1f1f2;font-size:13px;line-height:1}
.gca__tab.is-active{color:var(--gca-red)!important}.gca__tab.is-active span{background:#fbe8ed;color:var(--gca-red)}
.gca__tab.is-active:after{content:'';position:absolute;height:3px;bottom:0;left:0;right:0;background:var(--gca-red);border-radius:4px 4px 0 0}
.gca__filters{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:20px 22px;min-height:98px;border-bottom:1px solid #ddd}
.gca__search{display:flex;align-items:center;gap:12px;min-width:210px;flex:1 1 240px;max-width:310px;height:57px;border:1px solid #dedde0;border-radius:999px;padding:0 19px;color:var(--gca-muted)}
.gca__search svg{width:23px;height:23px}.gca .gca__search input{height:100%;width:100%;min-width:0;padding:0;background:none;border:0;box-shadow:none;font-size:16px}
.gca__search:focus-within{border-color:var(--gca-red);box-shadow:0 0 0 4px #ce063810}
.gca .gca__search input:focus{box-shadow:none;outline:0}
.gca__select{position:relative;flex:0 1 auto;min-width:125px;max-width:210px;height:57px}
.gca__select:after{content:'';pointer-events:none;position:absolute;width:10px;height:10px;border-bottom:2px solid var(--gca-red);border-right:2px solid var(--gca-red);transform:rotate(45deg);left:20px;top:20px}
.gca .gca__select select{appearance:none;-webkit-appearance:none;display:block;width:100%;max-width:none;height:57px;min-height:57px;border:1px solid #dedde0;border-radius:999px;padding:0 22px 0 43px;background:#fff;box-shadow:none;cursor:pointer;font-size:15px;line-height:1.7}
.gca .gca__select select:focus{border-color:var(--gca-red);outline:0;box-shadow:0 0 0 4px #ce063810}
.gca__result{margin:0 auto 0 0;color:var(--gca-muted);font-size:14px;white-space:nowrap}
.gca__list-message{padding:14px 24px;color:var(--gca-red);background:#fff2f5;border-bottom:1px solid var(--gca-border)}
.gca__table-scroll{position:relative;width:100%;max-width:100%;min-width:0;overflow:auto;scrollbar-width:thin;scrollbar-color:#e96e8d #f6f6f7}
.gca__table{border-collapse:collapse;width:100%;min-width:1360px;table-layout:fixed}
.gca__table th{height:57px;padding:10px 20px;background:#faf8f8;border-bottom:1px solid #dedada;color:var(--gca-muted);font-size:14px;font-weight:700;text-align:right}
.gca__table th:nth-child(1){width:22%}.gca__table th:nth-child(2){width:11%}.gca__table th:nth-child(3){width:6%}.gca__table th:nth-child(4){width:18%}.gca__table th:nth-child(5){width:13%}.gca__table th:nth-child(6){width:11%}.gca__table th:nth-child(7){width:11%}.gca__table th:nth-child(8){width:8%}
.gca__table td{height:107px;padding:17px 20px;vertical-align:middle;border-bottom:1px solid #dedde0;text-align:right}
.gca__row{cursor:pointer;transition:background .15s}.gca__row:hover{background:#fffafb}.gca__row:focus-visible{outline-offset:-3px}
.gca__row:last-child td{border-bottom:0}
.gca__member{display:flex;gap:17px;align-items:center;min-width:0}
.gca__avatar{display:flex;align-items:center;justify-content:center;width:60px;height:60px;border-radius:50%;color:#fff;background:linear-gradient(140deg,#a489df,#7655bc);box-shadow:0 8px 12px -5px #44444455;flex:none;overflow:hidden;font-size:28px;font-weight:750;line-height:1}
.gca__avatar[data-color=gold]{background:linear-gradient(140deg,#eac164,#c48a17)}.gca__avatar[data-color=mint]{background:linear-gradient(140deg,#80cfa8,#3a9d73)}.gca__avatar[data-color=coral]{background:linear-gradient(140deg,#f5b49b,#d78a66)}.gca__avatar[data-color=blue]{background:linear-gradient(140deg,#79c0df,#368bac)}.gca__avatar[data-color=slate]{background:linear-gradient(140deg,#737e8c,#3c4654)}
.gca__avatar img{display:block;width:100%;height:100%;object-fit:cover}
.gca__member-copy{min-width:0;display:flex;flex-direction:column}
.gca__member-copy strong{font-size:18px;font-weight:800;overflow-wrap:anywhere;line-height:1.7}
.gca__member-copy bdi{font-size:13px;color:var(--gca-muted);direction:ltr;text-align:right}
.gca__type{display:inline-flex;align-items:center;justify-content:center;max-width:100%;padding:4px 11px;line-height:1.6;font-size:12px;font-weight:650;border-radius:20px;background:#fbe9ee;color:#b30737;text-align:center}
.gca__type[data-audience=clinic]{background:#eaf4f0;color:#1f7956}
.gca__city{color:var(--gca-muted);font-size:14px}
.gca__chips{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:13px;color:var(--gca-muted)}
.gca__chip{display:inline-block;background:#f0f0f1;color:#33363c;border-radius:999px;font-size:13px;padding:2px 13px;line-height:1.8;max-width:100%;overflow-wrap:anywhere}
.gca__chip--primary{color:#bd0639;background:#fbecef}
.gca__rating-cell small,.gca__orders-cell small,.gca__date-cell small{display:block;color:var(--gca-muted);font-size:12px;line-height:1.9;margin-top:7px}
.gca__stars{display:inline-flex;gap:1px;direction:ltr;font-family:Arial,sans-serif;color:#dedbd6;font-size:20px;line-height:1.5;white-space:nowrap}
.gca__stars .is-filled{color:var(--gca-red)}
.gca__orders-cell strong{font-size:17px;font-weight:750}.gca__orders-cell small{white-space:normal}
.gca__date-cell time{font-size:14px;color:var(--gca-muted)}
.gca__action-cell{text-align:center!important}.gca__action-cell .gca__button{min-height:45px;padding:8px 20px;font-size:14px;box-shadow:none}
.gca__pagination{display:flex;justify-content:center;align-items:center;gap:10px;min-height:111px;padding:25px;border-top:1px solid #dedde0;direction:rtl}
.gca__page{height:54px;min-width:54px;padding:10px 20px;border:1px solid #dddce0;border-radius:30px;background:#fff;font-size:17px;cursor:pointer;line-height:1.6}
.gca__page.is-active{background:linear-gradient(105deg,#cf0639,#ac0029);border-color:transparent;color:#fff;box-shadow:var(--gca-shadow)}
.gca__page:hover:not(:disabled):not(.is-active){background:#fff5f7;border-color:#f3bdca}.gca__page:disabled{opacity:.4;cursor:default}
.gca__page-gap{padding:0 5px;color:var(--gca-muted)}
.gca__empty{text-align:center!important;height:220px!important;padding:45px!important}.gca__empty strong{font-size:20px}.gca__empty p{color:var(--gca-muted);margin:10px 0 0}
.gca__panel[aria-busy=true] .gca__table-scroll{opacity:.55;pointer-events:none}
.gca__drawer,.gca__sms-dialog{font-family:inherit;direction:rtl;color:var(--gca-ink);border:0;background:#fff;box-shadow:none}
.gca__drawer{position:fixed;inset:0 auto 0 0;margin:0;padding:0;width:720px;max-width:100vw;height:100dvh;max-height:100dvh;border-radius:0 36px 36px 0;overflow:hidden}
.gca__drawer::backdrop,.gca__sms-dialog::backdrop{background:#0007;backdrop-filter:blur(4px)}
.gca__drawer[open]{display:flex;flex-direction:column}
.gca__drawer-header{display:flex;align-items:center;justify-content:space-between;height:91px;min-height:91px;padding:18px 26px;border-bottom:1px solid #dcdcdf;background:#fff;gap:16px}
.gca__drawer-header h2{font-size:21px;line-height:1.5;font-weight:800;margin:0}
.gca__drawer-navigation{display:flex;gap:12px}
.gca__round{display:inline-flex;align-items:center;justify-content:center;width:50px;height:50px;padding:12px;border:1px solid #dedde0;border-radius:50%;background:#fff;cursor:pointer;line-height:1;flex:none}
.gca__round svg{width:22px;height:22px}.gca__round:disabled{opacity:.35;cursor:default}.gca__round:hover:not(:disabled){background:#fff6f8;border-color:#eebdca}
.gca__drawer-body{padding:26px 36px 34px;overflow:auto;flex:1;scrollbar-width:thin;scrollbar-color:#e96e8d #fff;overscroll-behavior:contain}
.gca__member-hero{display:flex;align-items:center;gap:20px;min-height:160px;border:1px solid #f4afbd;border-radius:29px;background:radial-gradient(ellipse at bottom left,#f6cbcf 0%,#fffafa 70%,#fff 100%);padding:26px}
.gca__avatar--large{width:90px;height:90px;font-size:42px}
.gca__member-hero-copy{min-width:0;flex:1}
.gca__member-hero h3{margin:0;font-size:26px;font-weight:850;line-height:1.6;overflow-wrap:anywhere}
.gca__member-hero p{margin:0 0 9px;color:var(--gca-muted);font-size:14px}
.gca__club-badge{display:inline-flex;align-items:center;gap:7px;vertical-align:middle;background:linear-gradient(110deg,#d2083b,#ac0029);color:#fff;border-radius:25px;padding:6px 15px;font-size:13px;font-weight:800;line-height:1.7;box-shadow:0 7px 12px -7px #af003955;max-width:100%}
.gca__club-badge svg{width:14px;height:14px}.gca__member-hero .gca__type{margin:6px 6px 0 0;vertical-align:middle}
.gca__detail-actions{display:flex;gap:10px;align-items:center;margin-top:16px;margin-bottom:26px}
.gca__detail-actions .gca__button{min-height:49px;padding:9px 23px;font-size:15px}
.gca__detail-title{position:relative;font-size:18px;line-height:1.6;font-weight:800;margin:29px 0 20px;padding-right:17px}
.gca__detail-title:before{content:'';position:absolute;right:0;top:3px;width:5px;height:20px;background:var(--gca-red);border-radius:5px}
.gca__detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.gca__detail-field{background:#f0f0f1;border-radius:22px;padding:14px 18px;min-height:88px;min-width:0;display:flex;flex-direction:column;justify-content:center;gap:4px}
.gca__detail-field--full{grid-column:1/-1}
.gca__detail-label{display:block;font-size:14px;color:var(--gca-muted)}
.gca__detail-field strong{font-size:16px;font-weight:650;overflow-wrap:anywhere;white-space:pre-wrap}
.gca__detail-field .gca__chips{justify-content:flex-start;color:var(--gca-ink)}
.gca__detail-field .gca__chip{background:#fff;border:1px solid #dedcdf;padding:2px 13px}
.gca__comment-label{font-size:14px;color:var(--gca-muted);margin:20px 0 4px}
.gca__comment{position:relative;padding:20px 24px;border:1px solid #f4c2cc;border-radius:24px;margin:0;background:#fdf9fa;font-size:16px;white-space:pre-wrap;overflow-wrap:anywhere}
.gca__comment:before{content:'“';position:absolute;color:var(--gca-red);right:20px;top:-15px;font-size:42px;font-weight:800;line-height:1}
.gca__nps{padding-top:20px}.gca__nps-track{display:flex;gap:4px;direction:rtl;margin:10px 16px 17px}
.gca__nps-track span{height:12px;flex:1;border-radius:8px;background:#e1ded9}.gca__nps-track .is-filled{background:#23833e}
.gca__nps[data-level=neutral] .is-filled{background:#bb7b18}.gca__nps[data-level=low] .is-filled{background:#ce0638}
.gca__nps-labels{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 13px;color:var(--gca-muted);font-size:13px}
.gca__nps-labels strong{color:#23833e;font-size:14px}.gca__nps[data-level=neutral] strong{color:#a76d15}.gca__nps[data-level=low] strong{color:#ce0638}
.gca__purchase-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.gca__purchase-stats>div{border:1px solid #f7cbd3;border-radius:23px;min-height:138px;padding:16px 10px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:9px}
.gca__purchase-stats strong{font-size:24px;line-height:1.6;font-weight:800;overflow-wrap:anywhere}.gca__purchase-stats span{font-size:13px;color:var(--gca-muted)}
.gca__timeline{list-style:none;margin:25px 0 39px;padding:0 10px 0 0}
.gca__timeline li{position:relative;min-height:74px;padding:0 28px 13px 0;font-size:16px}
.gca__timeline li:before{content:'';position:absolute;right:0;top:6px;width:17px;height:17px;background:var(--gca-red);border:3px solid #fff;outline:1px solid var(--gca-red);border-radius:50%;z-index:1}
.gca__timeline li:not(:last-child):after{content:'';position:absolute;right:8px;top:26px;bottom:0;width:2px;background:#dedde0}
.gca__timeline small{display:block;color:var(--gca-muted);font-size:13px;margin-top:2px}
.gca .gca__note{display:block;width:100%;border:1px solid #dedde0;border-radius:20px;background:#fff;padding:18px 20px;min-height:115px;resize:vertical;box-shadow:none;font-size:15px}
.gca .gca__note:focus,.gca .gca__sms-dialog textarea:focus,.gca .gca__sms-dialog input:focus{border-color:var(--gca-red);box-shadow:0 0 0 4px #ce063810;outline:0}
.gca__note-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:20px 0 31px}
.gca__note-actions span{font-size:14px;color:var(--gca-muted)}.gca__note-actions .gca__button{min-height:47px;padding:8px 22px;font-size:14px}
.gca__cancel-box{display:flex;align-items:center;justify-content:space-between;gap:20px;border:1px dashed #f38da6;border-radius:25px;padding:22px}
.gca__cancel-box strong{font-size:16px;font-weight:750}.gca__cancel-box p{margin:3px 0 0;color:var(--gca-muted);font-size:14px}
.gca__cancel-box .gca__button{min-height:47px;padding:8px 19px;font-size:14px;flex:none}
.gca__delete-box{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:18px;margin-top:22px;padding:22px;border:1px solid #f0b7c5;border-radius:25px;background:#fff8fa}
.gca__delete-box>div:first-child{flex:1 1 300px;min-width:0}.gca__delete-box strong{font-size:16px;color:var(--gca-deep)}
.gca__delete-box p{margin:5px 0 0;color:var(--gca-muted);font-size:13px;line-height:1.9}
.gca .gca__button--danger{min-height:47px;padding:8px 19px;font-size:14px;color:var(--gca-deep)!important;background:#fff;border:1px solid #de7b96;box-shadow:none}
.gca .gca__button--danger:hover:not(:disabled){background:#fce6ed;border-color:var(--gca-deep)}
.gca__delete-confirm{flex:1 0 100%;padding:20px;border:1px solid #e5a7b9;border-radius:20px;background:#fff}
.gca__delete-confirm h4{margin:0;color:var(--gca-deep);font-size:16px;line-height:1.7}.gca__delete-confirm p{margin-top:10px}
.gca__delete-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}.gca__delete-actions .gca__button{min-height:45px;padding:8px 20px;font-size:13px}
.gca__drawer[aria-busy=true] button{cursor:progress}.gca__drawer[aria-busy=true] .gca__delete-confirm{opacity:.75}
@media(max-width:480px){.gca__delete-box{padding:18px;gap:14px}.gca__delete-confirm{padding:16px}.gca__delete-actions{gap:8px}.gca__delete-actions .gca__button{padding-inline:16px}}
.gca__detail-message{font-size:14px;color:#1e7a43;margin:12px 0 0;white-space:pre-wrap}
.gca__unlinked{padding:18px;border:1px solid #f0d7de;border-radius:20px;color:var(--gca-muted);font-size:15px}
.gca__loading{padding:35px 5px;text-align:center;color:var(--gca-muted)}.gca__error{color:var(--gca-red)}
.gca__sms-dialog{width:650px;max-width:calc(100vw - 32px);padding:30px 32px;border-radius:30px;margin:auto;max-height:calc(100dvh - 40px);overflow:auto}
.gca__sms-dialog>header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:13px}
.gca__sms-dialog h2{margin:0;font-size:25px;font-weight:800}
.gca__sms-dialog>p{margin:10px 0 16px;font-size:15px}
.gca__sms-dialog>label{display:block;margin:18px 0 8px;font-weight:700}
.gca .gca__sms-dialog textarea{display:block;width:100%;padding:16px 18px;border:1px solid #dedde0;box-shadow:none;border-radius:20px;resize:vertical;min-height:145px;font-size:16px}
.gca__sms-meta{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px;color:var(--gca-muted);margin:8px 0 18px}
.gca__sms-meta>span:first-child{direction:ltr}
.gca__sms-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:22px}
.gca__sms-actions .gca__button{min-height:49px;font-size:15px;padding:10px 23px}
.gca__sms-hint{padding:12px 15px;background:#fff6e8;color:#88601c;border-radius:15px}
.gca__sms-error{color:var(--gca-red);font-size:14px}
.gca__sms-settings{border-top:1px solid #eee;margin-top:18px;padding-top:15px;font-size:14px}.gca__sms-settings summary{cursor:pointer;color:var(--gca-muted)}
.gca__sender-fields{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:12px}
.gca .gca__sender-fields input{min-height:44px;flex:1;min-width:150px;border:1px solid #dedde0;border-radius:12px;padding:8px 12px;box-shadow:none;direction:ltr;text-align:left}
.gca__sender-fields .gca__button{min-height:44px;font-size:13px;padding:8px 17px}
.gca__toast{position:fixed;left:50%;bottom:28px;transform:translateX(-50%);background:#25252a;color:#fff;border-radius:24px;padding:12px 24px;box-shadow:0 8px 25px #0003;z-index:100003;font-size:14px;max-width:calc(100vw - 40px);margin:0}
.gca__no-script{padding:20px;background:#fff;border:1px solid #e9bfcb;border-radius:20px}
@media(min-width:1650px){.gca__filters{gap:10px}.gca__select{min-width:115px;max-width:180px}.gca__select:nth-child(2){max-width:190px}.gca .gca__select select{padding-right:17px;padding-left:37px;font-size:14px}.gca__select:after{left:16px}.gca__search{max-width:275px;min-width:215px;flex-basis:245px}.gca__result{font-size:13px}}
@media(max-width:1450px){.gca{padding:30px 24px 60px}.gca__header h1{font-size:31px}.gca__header p{max-width:660px;font-size:14px}.gca__header-actions .gca__button{font-size:15px;padding:10px 23px}.gca__stat{padding:18px;gap:13px}.gca__stat-copy strong{font-size:26px}.gca__stat-copy span{font-size:13px}.gca__stat-icon{width:53px;height:53px}.gca__result{flex-basis:100%;text-align:left}.gca__filters{padding:18px 22px}}
@media(max-width:1050px){.gca__header{flex-direction:column;gap:12px}.gca__header-actions{padding-top:0}.gca__stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.gca__stat{min-height:100px}.gca__header h1{font-size:29px}.gca__stat-copy span{font-size:14px}.gca__search{max-width:none;flex:1 1 250px}.gca__select{flex:1 1 145px;max-width:none}}
@media(max-width:782px){.genosys-club-adminpage #wpcontent{padding-left:0}.gca{padding:24px 16px 45px}.gca__header h1{font-size:27px}.gca__header p{line-height:1.9}.gca__header-actions{gap:9px;flex-wrap:wrap}.gca__header-actions .gca__button{min-height:49px;font-size:14px;padding:10px 20px}.gca__stats{gap:10px;margin-bottom:18px}.gca__stat{gap:11px;padding:15px;border-radius:22px;min-height:99px}.gca__stat-icon{width:45px;height:45px}.gca__stat-icon svg{width:23px;height:23px}.gca__stat-copy strong{font-size:23px}.gca__stat-copy span{font-size:12px;line-height:1.7}.gca__panel{border-radius:27px}.gca__tabs{padding:0 17px;gap:15px;height:68px}.gca__tab{font-size:15px!important;padding:16px 5px}.gca__filters{gap:9px;padding:16px}.gca__search{min-width:0;flex-basis:100%;height:52px}.gca__select{min-width:0;flex:1 1 calc(50% - 9px);height:50px}.gca .gca__select select{min-height:50px;height:50px;font-size:13px;padding-right:16px}.gca__select:after{top:18px;left:17px}.gca__result{font-size:13px;text-align:right}.gca__table{min-width:1260px}.gca__table th,.gca__table td{padding-left:15px;padding-right:15px}.gca__pagination{padding:21px 13px;gap:7px;min-height:95px}.gca__page{min-width:44px;height:46px;padding:8px 16px;font-size:14px}.gca__drawer{border-radius:0 24px 24px 0;width:min(720px,100vw)}.gca__drawer-header{height:80px;min-height:80px;padding:15px 20px}.gca__drawer-header h2{font-size:19px}.gca__drawer-navigation{gap:8px}.gca__round{width:44px;height:44px;padding:10px}.gca__drawer-body{padding:22px 24px 30px}}
@media(max-width:480px){.gca{padding:21px 12px 40px}.gca__header{margin-bottom:22px}.gca__header h1{font-size:25px}.gca__header p{font-size:13px}.gca__header-actions{width:100%}.gca__header-actions .gca__button{flex:1;padding:10px 12px;font-size:13px}.gca__stats{gap:8px}.gca__stat{padding:13px 11px;gap:9px;align-items:flex-start;min-height:105px}.gca__stat-icon{width:36px;height:36px;margin-top:4px}.gca__stat-icon svg{width:20px;height:20px}.gca__stat-copy strong{font-size:23px;line-height:1.6}.gca__stat-copy span{font-size:11px}.gca__tabs{gap:12px;padding:0 14px}.gca__tab{font-size:14px!important}.gca__tab span{font-size:12px;min-width:25px;height:23px;padding:0 6px}.gca__drawer{border-radius:0}.gca__drawer-header{padding:14px 16px}.gca__drawer-header h2{font-size:18px}.gca__drawer-navigation{gap:6px}.gca__round{width:39px;height:39px;padding:9px}.gca__drawer-body{padding:20px 18px 28px}.gca__member-hero{padding:20px 17px;border-radius:25px;gap:13px;min-height:155px}.gca__avatar--large{width:72px;height:72px;font-size:35px}.gca__member-hero h3{font-size:23px}.gca__member-hero p{font-size:12px}.gca__club-badge{font-size:11px;padding:5px 10px;gap:4px}.gca__member-hero .gca__type{font-size:11px;margin-right:0}.gca__detail-grid{gap:10px}.gca__detail-field{padding:13px 14px;border-radius:20px;min-height:84px}.gca__detail-label{font-size:12px}.gca__detail-field strong{font-size:14px}.gca__detail-title{font-size:17px;margin-top:27px;margin-bottom:17px}.gca__detail-actions{margin-bottom:22px}.gca__detail-actions .gca__button{min-height:46px;padding:8px 19px;font-size:13px}.gca__purchase-stats{gap:8px}.gca__purchase-stats>div{padding:14px 8px;min-height:100px;border-radius:20px}.gca__purchase-stats strong{font-size:16px}.gca__purchase-stats span{font-size:11px}.gca__nps-track{gap:3px;margin:9px 0 15px}.gca__nps-labels{padding:0;gap:6px;font-size:11px}.gca__nps-labels strong{font-size:12px}.gca__note-actions{gap:10px;align-items:flex-start}.gca__note-actions span{font-size:12px}.gca__note-actions .gca__button{font-size:12px;padding:9px 17px}.gca__cancel-box{padding:18px;gap:14px;align-items:flex-start;flex-direction:column}.gca__cancel-box p{font-size:13px}.gca__cancel-box .gca__button{font-size:13px}.gca__sms-dialog{padding:24px 22px;border-radius:25px;max-width:calc(100vw - 24px)}.gca__sms-dialog h2{font-size:22px}.gca__sms-meta{align-items:flex-start;font-size:11px}.gca__sms-dialog>p{font-size:14px}.gca__sms-actions{gap:9px}.gca__sms-actions .gca__button{padding:10px 18px;font-size:13px;min-height:46px}}
@media(prefers-reduced-motion:reduce){.gca *{transition:none!important;scroll-behavior:auto!important}}

assets/css/company.css.content:
/* Company story, using the homepage's crimson palette and rounded surfaces. */
.gs-company{--company-accent:var(--accent,#c8103b);--company-deep:var(--deep,#9f1536);--company-blush:color-mix(in srgb,var(--company-accent) 5%,#fff);--company-border:color-mix(in srgb,var(--company-accent) 16%,#fff);--company-ink:#1c1d22;color:var(--ink,#455660);background:#fff;overflow:clip}
.gs-company-shell{width:min(1440px,calc(100% - 100px));margin-inline:auto}
.gs-company-intro{position:relative;text-align:center;padding-block:100px 112px;background:radial-gradient(ellipse at 50% 0%,var(--company-blush),transparent 72%),#fff}
.gs-company-intro .gs-company-intro__eyebrow{display:inline-flex;align-items:center;gap:12px;margin:0 0 24px;color:var(--company-accent);font-size:16px;font-weight:550;line-height:1.8}
.gs-company-intro__eyebrow:before{content:"";width:32px;height:3px;border-radius:4px;background:currentColor}
.gs-company-intro h1{max-width:1100px;margin:0 auto;font-size:clamp(42px,4.3vw,76px);font-weight:700;line-height:1.65;letter-spacing:-.035em;color:var(--company-ink);text-wrap:balance}
.gs-company-intro h1 span{color:var(--company-accent)}
.gs-company-intro p{margin:30px 0 0;font-size:21px;font-weight:350;line-height:1.95;color:var(--muted,#78848c)}
.gs-company-history{position:relative;padding:90px 0 86px;background:#f6f5f3;border-bottom:12px solid var(--company-accent)}
.gs-company-history__top{display:flex;align-items:center;justify-content:space-between;gap:30px}
.gs-company-history h2,.gs-company-section-heading h2{color:var(--company-ink);margin:0;font-size:clamp(32px,3.1vw,52px);font-weight:650;line-height:1.65;letter-spacing:-.025em}
.gs-company-history h2:before,.gs-company-section-heading h2:before{content:"";display:inline-block;width:5px;height:.7em;margin-inline-end:16px;border-radius:5px;background:var(--company-accent);vertical-align:middle}
.gs-company-history__top p{margin:16px 0 0;font-size:19px;line-height:1.8;font-weight:350;color:var(--muted,#78848c)}
.gs-company-history__controls{display:flex;gap:10px;flex-shrink:0}
.gs-company-history__controls[hidden]{display:none}
.gs-company-history__controls button{display:grid;place-items:center;width:56px;height:56px;padding:0;border:1px solid var(--company-border);border-radius:50%;background:#fff;color:var(--company-accent);cursor:pointer;transition:background .2s,color .2s,box-shadow .2s}
.gs-company-history__controls svg{width:20px;height:26px}
.gs-company-history__controls button:hover:not(:disabled){background:var(--company-accent);color:#fff;box-shadow:0 8px 18px color-mix(in srgb,var(--company-accent) 20%,transparent)}
.gs-company-history__controls button:disabled{opacity:.35;cursor:default}
.gs-company-history__controls button:focus-visible,.gs-company-history__track:focus-visible{outline:2px solid var(--company-accent);outline-offset:5px}
.gs-company-history__track{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 72px)/4);gap:24px;overflow-x:auto;overscroll-behavior-inline:contain;scroll-snap-type:x mandatory;scrollbar-width:thin;scrollbar-color:var(--company-border) transparent;margin-top:45px;padding:4px 0 24px;cursor:grab}
.gs-company-history__track.is-dragging{scroll-snap-type:none;cursor:grabbing;user-select:none}
.gs-company-history__year{min-width:0;scroll-snap-align:start;padding:26px 24px 22px;border:1px solid var(--company-border);border-radius:28px;background:#fff}
.gs-company-history__year h3{position:relative;margin:0 0 24px;padding-bottom:20px;border-bottom:1px solid var(--company-border);font-size:34px;font-weight:650;line-height:1.4;color:var(--company-accent)}
.gs-company-history__year h3:after{content:"";position:absolute;inset-inline-start:0;bottom:-2px;width:42px;height:3px;border-radius:4px;background:var(--company-accent)}
.gs-company-history__year ul{list-style:none;padding:0;margin:0}
.gs-company-history__year li{margin:0}
.gs-company-history__year img{display:block;width:100%;height:auto;aspect-ratio:5/2;object-fit:cover;border-radius:16px;margin:4px 0 24px}
.gs-company-history__year li:last-child img{margin-bottom:0}
.gs-company-history__year p{margin:0;padding-bottom:12px;font-size:16px;font-weight:400;line-height:1.95;color:inherit}
.gs-company-business{padding-block:108px}
.gs-company-section-heading{padding-bottom:44px}
.gs-company-section-heading p{max-width:1080px;margin:22px 0 0;font-size:20px;font-weight:350;line-height:1.95;color:var(--muted,#78848c)}
.gs-company-business__content{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.8fr);gap:40px;align-items:start}
.gs-company-business__map{position:relative;grid-column:2;grid-row:1;direction:ltr;overflow:hidden;border:1px solid var(--company-border);border-radius:32px;background:var(--company-blush)}
/* Shift the source map's cyan pins to crimson; neutral details remain neutral. */
.gs-company-business__map>img{display:block;width:100%;height:auto;filter:hue-rotate(149deg) saturate(1.2);mix-blend-mode:multiply}
.gs-company-business__count{position:absolute;left:40%;top:18%;text-align:center;color:var(--company-accent);direction:rtl}
.gs-company-business__count strong{display:block;font-size:clamp(42px,3.5vw,60px);font-weight:700;line-height:1.3;font-variant-numeric:tabular-nums}
.gs-company-business__count span{display:block;font-size:clamp(22px,1.8vw,30px);font-weight:450;line-height:1.5}
.gs-company-regions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));column-gap:18px;row-gap:32px;grid-column:1;grid-row:1}
.gs-company-region{min-width:0}
.gs-company-region h3{margin:0 0 12px;font-size:17px;font-weight:650;line-height:1.8;color:var(--company-accent)}
.gs-company-region ul{list-style:none;padding:0;margin:0}
.gs-company-region li{font-size:14px;font-weight:400;line-height:1.8;margin-bottom:5px}
.gs-company-region--asia{grid-column:span 2}
.gs-company-region--europe{grid-column:span 3}
.gs-company-region--europe ul{columns:3;column-gap:20px}
.gs-company-region--oceania{grid-column:1/-1}
.gs-company-facility{padding-bottom:108px}
.gs-company-facility figure{margin:0;overflow:hidden;border:1px solid var(--company-border);border-radius:32px;box-shadow:0 18px 45px #7e09250c}
/* Clip the source image's baked English caption; the translated caption is live text. */
.gs-company-facility__image{aspect-ratio:1656/848;overflow:hidden}
.gs-company-facility__image img{display:block;width:100%;height:auto}
.gs-company-facility figcaption{padding:25px 32px;background:linear-gradient(110deg,var(--company-accent),var(--company-deep));color:#fff;text-align:center;font-size:18px;font-weight:400;line-height:1.9}
@media(max-width:1280px){
 .gs-company-shell{width:calc(100% - 80px)}
 .gs-company-business__content{display:flex;flex-direction:column;gap:40px}
 .gs-company-business__map{width:100%}
 .gs-company-regions{width:100%;grid-template-columns:2fr 1fr 1fr 3fr 1.5fr;gap:25px}
 .gs-company-region--asia,.gs-company-region--europe{grid-column:auto}
 .gs-company-region--oceania{grid-column:1/-1}
 .gs-company-history__track{grid-auto-columns:calc((100% - 40px)/3);gap:20px}
}
@media(max-width:768px){
 .gs-company-shell{width:calc(100% - 48px)}
 .gs-company-intro{padding-block:72px 80px}
 .gs-company-intro h1{font-size:48px}
 .gs-company-intro p{font-size:19px;margin-top:26px}
 .gs-company-history{padding-block:68px 60px;border-bottom-width:8px}
 .gs-company-history__track{grid-auto-columns:calc((100% - 20px)/2);margin-top:34px}
 .gs-company-history__top p{font-size:17px}
 .gs-company-history__controls button{width:48px;height:48px}
 .gs-company-history__year{padding:23px 20px;border-radius:24px}
 .gs-company-history__year h3{font-size:30px}
 .gs-company-business{padding-block:76px}
 .gs-company-section-heading{padding-bottom:32px}
 .gs-company-section-heading p{font-size:18px}
 .gs-company-section-heading p br{display:none}
 .gs-company-business__count strong{font-size:40px}
 .gs-company-business__count span{font-size:23px}
 .gs-company-regions{grid-template-columns:repeat(4,minmax(0,1fr));gap:30px 20px}
 .gs-company-region--asia{grid-column:span 2}
 .gs-company-region--europe{grid-column:span 3}
 .gs-company-region--oceania{grid-column:1/-1}
 .gs-company-facility{padding-bottom:76px}
 .gs-company-facility figure,.gs-company-business__map{border-radius:24px}
 .gs-company-facility figcaption{font-size:16px;padding:20px 22px}
}
@media(max-width:500px){
 .gs-company-intro{padding-block:55px 64px}
 .gs-company-intro .gs-company-intro__eyebrow{font-size:14px;margin-bottom:20px}
 .gs-company-intro h1{font-size:38px;line-height:1.7}
 .gs-company-intro p{font-size:16px;margin-top:22px}
 .gs-company-history{padding-block:52px 46px}
 .gs-company-history h2,.gs-company-section-heading h2{font-size:30px}
 .gs-company-history h2:before,.gs-company-section-heading h2:before{margin-inline-end:10px;width:4px}
 .gs-company-history__top{align-items:flex-start;gap:14px}
 .gs-company-history__top p{font-size:15px;margin-top:12px}
 .gs-company-history__controls{padding-top:7px;gap:7px}
 .gs-company-history__controls button{width:40px;height:40px}
 .gs-company-history__controls svg{width:16px;height:22px}
 .gs-company-history__track{grid-auto-columns:100%;gap:20px;margin-top:28px}
 .gs-company-history__year{padding:24px}
 .gs-company-history__year h3{font-size:32px}
 .gs-company-business{padding-block:60px}
 .gs-company-section-heading p{font-size:16px;line-height:1.95;margin-top:17px}
 .gs-company-business__content{gap:30px}
 .gs-company-business__count{top:14%}
 .gs-company-business__count strong{font-size:29px}
 .gs-company-business__count span{font-size:17px}
 .gs-company-regions{grid-template-columns:repeat(3,minmax(0,1fr));column-gap:16px;row-gap:25px}
 .gs-company-region--asia{grid-column:auto}
 .gs-company-region--europe{grid-column:span 2}
 .gs-company-region--europe ul{columns:2;column-gap:12px}
 .gs-company-region li{font-size:13px}
 .gs-company-region h3{font-size:16px}
 .gs-company-facility{padding-bottom:60px}
 .gs-company-facility figcaption{font-size:14px;padding:17px}
}
@media(prefers-reduced-motion:reduce){.gs-company-history__controls button{transition:none}.gs-company-history__track{scroll-behavior:auto}}

assets/css/contact.css.content:
/* Contact page: local styles, shared theme header and footer remain intact. */
.gs-contact{--contact-red:var(--accent,#cc0d36);--contact-deep:var(--deep,#a5072b);--contact-ink:#202025;--contact-muted:#85817e;--contact-border:#e4e2e1;color:var(--contact-ink);background:#fff;overflow:hidden;font-size:16px}
.gs-contact button,.gs-contact input,.gs-contact textarea{font:inherit}
.gs-contact a{color:inherit;text-decoration:none}
.gs-contact-shell{width:min(1590px,calc(100% - 64px));margin-inline:auto}
.gs-contact-hero{position:relative;padding:60px 0 46px;background:radial-gradient(ellipse at 92% -6%,#e8d9da 0,transparent 44%),radial-gradient(ellipse at 2% 0,#e8e8e7 0,transparent 42%),#f6f5f3;text-align:center;isolation:isolate}
.gs-contact-hero>.gs-contact-shell{position:relative;z-index:1}
.gs-contact-status{display:inline-flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:10px;padding:10px 16px;border:1px solid #e8e6e4;border-radius:99px;background:#fff;box-shadow:0 10px 20px #17151c14;font-size:15px;color:#555259}
.gs-contact-status strong{font-weight:700;color:var(--contact-ink)}
.gs-contact-status__dot{display:block;position:relative;width:13px;height:13px;flex:none;border-radius:50%;background:#88817d;margin-inline:4px}
.gs-contact-status__dot:after{content:"";position:absolute;inset:-6px;border:2px solid currentColor;border-radius:50%;color:#a7a19b}
.gs-contact-status.is-open .gs-contact-status__dot{background:#207f3d}
.gs-contact-status.is-open .gs-contact-status__dot:after{color:#8cba9a}
.gs-contact-status__detail{color:var(--contact-muted)}
.gs-contact-status__detail:before{content:"·";margin-inline-end:10px}
.gs-contact h1{margin:24px auto 25px;font-size:clamp(48px,5.8vw,104px);font-weight:900;line-height:1.4;letter-spacing:-2.5px}
.gs-contact-highlight{position:relative;display:inline-block;color:var(--contact-red)}
.gs-contact-highlight>svg{position:absolute;left:-2%;bottom:-9px;width:104%;height:26px;overflow:visible}
.gs-contact-intro{color:var(--contact-muted);font-size:22px;line-height:1.95;max-width:880px;margin:0 auto 60px}
.gs-contact-wave{position:absolute;left:3.5%;top:82px;width:270px;height:120px;z-index:0;filter:drop-shadow(12px 16px 20px #2321240c);transform:rotate(-2deg)}
.gs-contact-disc{position:absolute;right:5.2%;top:34px;width:156px;height:156px;border-radius:50%;background:var(--contact-red);transform:rotate(.5deg);z-index:0}
.gs-contact-disc:after{content:"";position:absolute;inset:50% 9px 8px;border-radius:0 0 100px 100px;background:#202025}
.gs-contact-channels{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;max-width:1495px;margin:auto}
.gs-contact-channel{padding:29px 28px 24px;text-align:right;border:1px solid var(--contact-border);border-radius:36px;background:#ffffffd9;box-shadow:0 26px 32px -30px #21212780;min-width:0}
.gs-contact-channel--featured{border-color:#efb4c0;background:radial-gradient(ellipse at 100% 10%,#edcbd2 0,transparent 55%),#ffffffd9;box-shadow:inset -2px -2px 0 #fff,inset -3px -3px 0 var(--contact-red),0 28px 40px -32px #a90b36a0}
.gs-contact-channel__icon{display:flex;align-items:center;justify-content:center;width:66px;height:66px;margin:0 0 16px;background:linear-gradient(125deg,var(--contact-red),var(--contact-deep));color:#fff;border-radius:24px;box-shadow:0 15px 22px -10px #c8103b70}
.gs-contact-channel--featured .gs-contact-channel__icon{transform:rotate(-7deg)}
.gs-contact-channel__icon svg{width:30px;height:30px}
.gs-contact-channel h2{font-size:15px;line-height:1.8;font-weight:400;margin:0;color:var(--contact-muted)}
.gs-contact-channel__value{font-size:21px;font-weight:750;margin:12px 0 26px;line-height:1.8;white-space:normal;overflow-wrap:anywhere;text-align:right;min-height:38px}
.gs-contact-channel__value.is-empty{font-size:17px;font-weight:500;color:var(--contact-muted)}
.gs-contact-channel__actions{display:flex;align-items:center;gap:10px}
.gs-contact-button{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:46px;padding:9px 22px;background:linear-gradient(120deg,var(--contact-red),var(--contact-deep));border:1px solid transparent;border-radius:99px;color:#fff!important;font-weight:750;line-height:1.5;cursor:pointer;text-align:center;transition:box-shadow .18s,background-color .18s,transform .18s}
.gs-contact-button:hover{box-shadow:0 8px 15px -8px #bb07365e;transform:translateY(-1px)}
.gs-contact-button:disabled{cursor:default;opacity:.5;transform:none;box-shadow:none}
.gs-contact-submit:disabled{cursor:wait}
.gs-contact-channel__actions .gs-contact-button{flex:1;min-width:0;padding:10px 12px;font-size:15px}
.gs-contact-button--outline{border-color:#e0dedd;background:#fff;color:var(--contact-ink)!important;font-weight:600}
.gs-contact-button--outline:hover{border-color:var(--contact-red);color:var(--contact-red)!important}
.gs-contact-main{display:grid;grid-template-columns:minmax(0,1.13fr) minmax(0,.87fr);gap:30px;align-items:start;padding-top:62px;padding-bottom:60px}
.gs-contact-form-card,.gs-contact-address{border:1px solid #e8e6e4;background:#fff;border-radius:42px;box-shadow:0 30px 42px -40px #212127b0}
.gs-contact-form-card{padding:43px 46px 44px}
.gs-contact-form-card header h2{font-size:34px;font-weight:850;line-height:1.6;margin:0 0 15px}
.gs-contact-form-card header p{font-size:18px;color:var(--contact-muted);line-height:1.9;margin:0 0 34px}
.gs-contact-form{display:grid;gap:22px;position:relative}
.gs-contact-topics{border:0;padding:0;margin:0 0 8px;min-width:0}
.gs-contact-topics legend{padding:0;margin:0 0 16px;font-weight:700}
.gs-contact-topic-list{display:flex;flex-wrap:wrap;gap:10px;max-width:670px}
.gs-contact-topic{position:relative;cursor:pointer}
.gs-contact-topic input{position:absolute;opacity:0;width:1px;height:1px;inset:50% auto auto 50%}
.gs-contact-topic>span{display:flex;align-items:center;justify-content:center;gap:9px;min-height:55px;padding:10px 23px;border:1px solid var(--contact-border);border-radius:99px;font-weight:500;line-height:1.6;transition:background-color .18s,color .18s,box-shadow .18s}
.gs-contact-topic>span svg{display:none;width:18px;height:18px}
.gs-contact-topic input:checked+span{border-color:transparent;background:linear-gradient(120deg,var(--contact-red),var(--contact-deep));color:#fff;font-weight:700;box-shadow:0 13px 18px -13px #aa0928a0}
.gs-contact-topic input:checked+span svg{display:block}
.gs-contact-topic input:focus-visible+span{outline:2px solid var(--contact-red);outline-offset:4px}
.gs-contact-field-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.gs-contact-field{min-width:0}
.gs-contact-field input,.gs-contact-field textarea{display:block;width:100%;min-width:0;border:1px solid #dedcda;border-radius:24px;padding:20px 22px;background:#fff;color:var(--contact-ink);outline:0;font-size:18px;line-height:1.75;text-align:right;transition:border-color .18s,box-shadow .18s;box-shadow:none}
.gs-contact-field input{height:76px}
.gs-contact-field input::placeholder,.gs-contact-field textarea::placeholder{color:var(--contact-muted);opacity:1}
.gs-contact-field input:focus,.gs-contact-field textarea:focus{border-color:var(--contact-red);box-shadow:0 0 0 5px #c8103b12}
.gs-contact-field [aria-invalid="true"]{border-color:var(--contact-red)}
.gs-contact-message-wrap{position:relative}
.gs-contact-field textarea{height:226px;min-height:190px;resize:vertical;padding-bottom:45px}
.gs-contact-counter{position:absolute;left:20px;bottom:12px;font-size:13px;color:var(--contact-muted);direction:ltr;pointer-events:none}
.gs-contact-field-error{color:var(--contact-red);font-size:13px;line-height:1.8;margin:7px 4px 0}
.gs-contact-attachment-wrap{position:relative}
.gs-contact-attachment{position:relative;display:flex;align-items:center;gap:14px;min-height:65px;padding:15px 22px;border:1px dashed #ef8da4;border-radius:24px;background:#fbf8f8;cursor:pointer;color:var(--contact-muted);line-height:1.8;font-size:15px;overflow:hidden}
.gs-contact-attachment>svg{width:27px;height:27px;flex:none;color:var(--contact-red)}
.gs-contact-attachment strong{font-weight:650;color:var(--contact-ink)}
.gs-contact-attachment>span{min-width:0;overflow-wrap:anywhere}
.gs-contact-attachment input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}
.gs-contact-attachment:focus-within{outline:2px solid var(--contact-red);outline-offset:4px}
.gs-contact-attachment-wrap.has-file .gs-contact-attachment{padding-left:58px}
.gs-contact-file-remove{position:absolute;top:14px;left:14px;width:36px;height:36px;border:0;border-radius:50%;background:#fff;color:var(--contact-red);display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:1}
.gs-contact-file-remove svg{width:17px;height:17px}
.gs-contact-form-actions{display:flex;align-items:center;justify-content:space-between;gap:22px;margin-top:4px}
.gs-contact-consent{flex:1;min-width:0;font-size:14px;color:var(--contact-muted)}
.gs-contact-consent>label{display:flex;align-items:flex-start;gap:13px;cursor:pointer;line-height:2.1}
.gs-contact-consent input{width:20px;height:20px;accent-color:var(--contact-red);flex:none;margin:5px 0 0}
.gs-contact-consent a,.gs-contact-privacy-label{color:var(--contact-red)}
.gs-contact-consent a:hover{text-decoration:underline}
.gs-contact-submit{min-height:70px;min-width:240px;font-size:21px;padding:15px 30px;flex:none;box-shadow:0 20px 28px -20px #b10a3aa0}
.gs-contact-submit svg{width:25px;height:25px}
.gs-contact-form-status{font-size:15px;margin:0;padding:14px 18px;border-radius:18px;background:#faf0f3;color:var(--contact-red);border:1px solid #efd2da;line-height:1.9;outline:0}
.gs-contact-form-status.is-success{background:#edf7ef;color:#267c41;border-color:#c3e0cb}
.gs-contact-form-status:focus-visible{outline:2px solid currentColor;outline-offset:3px}
.gs-contact-sidebar{min-width:0;display:grid;gap:22px}
.gs-contact-hours{position:relative;isolation:isolate;overflow:hidden;border-radius:42px;padding:33px 35px 30px;background:linear-gradient(130deg,var(--contact-red),var(--contact-deep));color:#fff;box-shadow:0 33px 46px -25px #ad0b3d65}
.gs-contact-hours:before{content:"";position:absolute;left:-170px;bottom:-180px;width:400px;height:400px;border-radius:50%;background:repeating-radial-gradient(circle at center,transparent 0 19px,#fff3 20px 20.7px);pointer-events:none;z-index:-1}
.gs-contact-hours:after{content:"";position:absolute;inset:20% 0 0;background:radial-gradient(ellipse at 14% 100%,#ffffff30,transparent 70%);z-index:-1;pointer-events:none}
.gs-contact-hours h2{display:flex;align-items:center;gap:13px;font-size:23px;font-weight:800;margin:0 0 22px}
.gs-contact-hours h2 svg{width:25px;height:25px;flex:none}
.gs-contact-hours ul{list-style:none;margin:0;padding:0;display:grid;gap:0}
.gs-contact-hours li{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:11px 14px;min-height:51px;border:1px solid transparent;border-radius:15px;color:#f4c7d0;font-weight:550;line-height:1.7}
.gs-contact-hours li.is-today{background:#ffffff30;border-color:#ffffff55;color:#fff;font-weight:800}
.gs-contact-address{padding:28px 30px 30px}
.gs-contact-address-row{display:flex;align-items:flex-start;gap:18px;padding:17px 0 21px;border-bottom:1px dashed #e2dedb}
.gs-contact-address-icon{display:flex;align-items:center;justify-content:center;width:54px;height:54px;border-radius:19px;background:#faedf0;color:var(--contact-red);flex:none}
.gs-contact-address-icon svg{width:25px;height:25px}
.gs-contact-address h2{font-size:15px;font-weight:400;color:var(--contact-muted);margin:0 0 8px}
.gs-contact-address p{font-size:17px;font-weight:600;line-height:1.95;margin:0;overflow-wrap:anywhere}
.gs-contact-postal{text-align:right}
.gs-contact-socials{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:17px}
.gs-contact-socials a{height:59px;display:flex;align-items:center;justify-content:center;border:1px solid #232329;background:#fff;transition:border-color .18s,color .18s,background-color .18s}
.gs-contact-socials a:hover{border-color:var(--contact-red);color:var(--contact-red);background:#fff9fa}
.gs-contact-socials svg{width:25px;height:25px}
.gs-contact-faq{padding-top:22px;padding-bottom:90px;text-align:center}
.gs-contact-faq header h2{font-size:52px;font-weight:900;line-height:1.7;margin:0 0 14px;letter-spacing:-.7px}
.gs-contact-faq header h2>span{color:var(--contact-red)}
.gs-contact-faq header>p{font-size:20px;color:var(--contact-muted);margin:0 0 44px}
.gs-contact-faq-list{max-width:1080px;margin:auto;display:grid;gap:13px;text-align:right}
.gs-contact-faq-item{border:1px solid #e6e4e2;border-radius:32px;background:#fff;box-shadow:0 14px 20px -22px #22222a;overflow:hidden;transition:border-color .18s,box-shadow .18s}
.gs-contact-faq-item summary{list-style:none;display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:88px;padding:20px 30px;cursor:pointer;font-size:19px;line-height:1.8;font-weight:800}
.gs-contact-faq-item summary::-webkit-details-marker{display:none}
.gs-contact-faq-item summary:focus-visible{outline:2px solid var(--contact-red);outline-offset:-6px;border-radius:30px}
.gs-contact-faq-toggle{display:flex;align-items:center;justify-content:center;flex:none;width:43px;height:43px;border-radius:50%;background:#f4f3f1;color:var(--contact-red);font-size:25px;font-weight:700;line-height:1;transition:transform .2s,background .2s,color .2s}
.gs-contact-faq-item[open]{border-color:#ec6c88;box-shadow:0 25px 32px -27px #a80636b0}
.gs-contact-faq-item[open] .gs-contact-faq-toggle{background:var(--contact-red);color:#fff;transform:rotate(45deg)}
.gs-contact-faq-answer{padding:0 30px 25px;color:var(--contact-muted);font-size:18px;line-height:2}
.gs-contact-faq-answer p{margin:8px 0 0;overflow-wrap:anywhere}
.gs-contact-sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
.gs-contact-honeypot{position:absolute!important;left:-10000px!important;top:auto;width:1px;height:1px;overflow:hidden}
@media(min-width:1650px){.gs-contact-main{width:min(1540px,calc(100% - 100px))}.gs-contact-form-card{padding-inline:46px}.gs-contact-form-actions{gap:25px}}
@media(max-width:1250px){.gs-contact-shell{width:calc(100% - 48px)}.gs-contact-wave{width:180px;top:85px;left:2%}.gs-contact-disc{width:112px;height:112px;top:36px;right:3%}.gs-contact h1{font-size:clamp(48px,6.3vw,88px)}.gs-contact-intro{font-size:20px}.gs-contact-channel{padding:25px 20px 22px;border-radius:30px}.gs-contact-channel__value{font-size:18px}.gs-contact-main{gap:22px;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr)}.gs-contact-form-card{padding:32px 28px}.gs-contact-form-card header h2{font-size:29px}.gs-contact-form-card header p{font-size:16px}.gs-contact-topic>span{padding:10px 17px;font-size:14px;min-height:49px}.gs-contact-form-actions{flex-wrap:wrap}.gs-contact-submit{min-width:220px;min-height:62px;font-size:19px}.gs-contact-consent{flex-basis:100%}.gs-contact-form-actions .gs-contact-submit{margin-inline-start:auto}.gs-contact-hours{padding:27px 23px}.gs-contact-hours h2{font-size:21px}.gs-contact-address{padding:24px}.gs-contact-address p{font-size:15px}.gs-contact-socials{gap:9px}.gs-contact-faq header h2{font-size:44px}}
@media(max-width:900px){.gs-contact-hero{padding-top:42px}.gs-contact h1{font-size:clamp(45px,7.3vw,64px);margin-top:23px;letter-spacing:-1.7px}.gs-contact-intro{max-width:680px;font-size:18px;margin-bottom:35px}.gs-contact-wave{width:120px;top:110px;left:-20px;opacity:.65}.gs-contact-disc{width:85px;height:85px;top:25px;right:17px;opacity:.85}.gs-contact-channels{grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;max-width:740px}.gs-contact-channel{padding:25px}.gs-contact-channel__value{font-size:21px;margin-bottom:20px}.gs-contact-main{grid-template-columns:minmax(0,1fr);padding-top:40px;max-width:740px}.gs-contact-sidebar{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.gs-contact-hours{border-radius:32px;padding:25px 18px}.gs-contact-hours h2{font-size:18px;gap:8px}.gs-contact-hours li{font-size:14px;min-height:43px;padding:8px 9px;gap:8px}.gs-contact-address{border-radius:32px;padding:22px 17px}.gs-contact-address-row{gap:10px;padding:8px 0 17px}.gs-contact-address-icon{width:43px;height:43px;border-radius:15px}.gs-contact-address h2{font-size:13px}.gs-contact-address p{font-size:14px}.gs-contact-socials{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.gs-contact-socials a{height:48px}.gs-contact-faq{padding-top:10px;padding-bottom:65px}.gs-contact-faq header h2{font-size:38px}.gs-contact-faq header>p{font-size:17px;margin-bottom:30px}.gs-contact-faq-item summary{font-size:17px;padding:18px 24px}.gs-contact-faq-answer{font-size:16px;padding-inline:24px}}
