    .genosys-receipts__stat-label { font-size: 14px; }
    .genosys-receipts__stat-icon { width: 48px; height: 48px; }
    .genosys-receipts__stat-icon svg { width: 38px; height: 38px; }
    .genosys-receipts__toolbar { flex-direction: column; align-items: stretch; gap: 13px; }
    .genosys-receipts__toolbar .genosys-receipts__search { width: 100%; }
    .genosys-receipts__toolbar .genosys-receipts__search-field { flex: 1; }
    .genosys-receipts__pagination { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "size range" "pages pages"; gap: 14px; }
}
@media (max-width: 782px) {
    .genosys-receipts { margin: 14px 10px 32px 0; }
    .genosys-receipts__topbar { padding: 18px; }
    .genosys-receipts__hero { min-height: 205px; }
    .genosys-receipts__hero-copy { width: 100%; padding-inline: 4px; }
    .genosys-receipts .genosys-receipts__hero h1 { font-size: 29px; letter-spacing: -.5px; }
    .genosys-receipts__hero-art { width: 85%; opacity: .25; }
    .genosys-receipts__intro { max-width: 560px; font-size: 14px; }
    .genosys-receipts__stats { gap: 12px; margin-bottom: 18px; }
    .genosys-receipts__toolbar { padding: 18px; margin-bottom: 18px; }
    .genosys-receipts__table th,
    .genosys-receipts__table td { padding-inline: 12px; }
    .genosys-receipts__pagination { padding-inline: 16px; }
}
@media (max-width: 520px) {
    .genosys-receipts__topbar { grid-template-columns: minmax(0, 1fr); grid-template-areas: "brand" "identity" "search"; gap: 15px; }
    .genosys-receipts__brand { align-items: center; text-align: center; }
    .genosys-receipts__brand img { width: 205px; }
    .genosys-receipts__identity { justify-content: center; }
    .genosys-receipts__topbar .genosys-receipts__search { flex-wrap: wrap; gap: 8px; }
    .genosys-receipts__topbar .genosys-receipts__search-field { flex: 1 0 100%; min-width: 0; }
    .genosys-receipts__topbar .genosys-receipts__search-button { width: 100%; min-height: 42px; }
    .genosys-receipts__hero { min-height: 245px; }
    .genosys-receipts .genosys-receipts__hero h1 { font-size: 27px; line-height: 1.65; }
    .genosys-receipts__intro { margin-bottom: 15px; font-size: 13px; }
    .genosys-receipts__help:not(details),
    .genosys-receipts__help > summary { min-height: 42px; font-size: 12px; }
    .genosys-receipts__stats { grid-template-columns: minmax(0, 1fr); gap: 12px; }
    .genosys-receipts__stat { min-height: 108px; padding: 10px; }
    .genosys-receipts__stat-inner { min-height: 86px; padding-block: 14px; }
    .genosys-receipts__stat-value { font-size: 27px; }
    .genosys-receipts__toolbar { padding: 16px; }
    .genosys-receipts__toolbar-heading p { font-size: 11px; }
    .genosys-receipts__toolbar .genosys-receipts__search { display: grid; grid-template-columns: minmax(0, 1fr); }
    .genosys-receipts__search-field { width: 100%; min-width: 0; }
    .genosys-receipts__search-button,
    .genosys-receipts__reset { width: 100%; }
    .genosys-receipts__pagination { grid-template-columns: minmax(0, 1fr); grid-template-areas: "pages" "range" "size"; gap: 13px; padding-block: 16px; }
    .genosys-receipts__range { text-align: center; }
    .genosys-receipts__page-size { justify-content: center; }
}
@media (prefers-reduced-motion: reduce) {
    .genosys-receipts *,
    .genosys-receipts *::before,
    .genosys-receipts *::after { scroll-behavior: auto; transition: none; }
}

assets/css/receipt-uploader.css.content:
/* Receipt UI only: no payment, checkout, or order selectors are changed here. */
.gco-receipt-upload {
    --gcr-crimson: #c80936;
    --gcr-ink: #161720;
    --gcr-muted: #8c8584;
    --gcr-border: #f58ca1;
    direction: rtl;
    margin-top: 30px;
    color: var(--gcr-ink);
    font-family: inherit;
}

.gco-receipt-upload *,
.gco-receipt-upload *::before,
.gco-receipt-upload *::after { box-sizing: border-box; }

.gco-receipt-upload [hidden] { display: none !important; }

.gco-receipt-upload .gco-receipt-upload__label {
    margin: 0 0 12px;
    color: var(--gcr-ink);
    font-size: 16px;
    font-weight: 600;
    line-height: 1.65;
    text-align: right;
}

.gco-receipt-upload .gco-receipt-upload__required {
    padding-inline-start: 3px;
    color: var(--gcr-crimson);
}

.gco-receipt-upload .gco-receipt-box {
    position: relative;
    display: grid;
    align-items: center;
    grid-template-columns: minmax(0, 1fr);
    width: 100%;
    min-height: 364px;
    margin: 0;
    padding: 28px;
    overflow: hidden;
    border: 2px dashed var(--gcr-border);
    border-radius: 36px;
    background: radial-gradient(ellipse at 11% 114%, #f5d9df 0, #fbe9ed 27%, #fdf8f9 63%);
    box-shadow: none;
    cursor: pointer;
    outline: none;
    transition: border-color .22s ease, box-shadow .22s ease, transform .22s ease;
}

.gco-receipt-upload .gco-receipt-box[data-state="idle"]:hover {
    border-color: var(--gcr-crimson);
}

.gco-receipt-upload .gco-receipt-box:focus-visible {
    border-color: var(--gcr-crimson);
    box-shadow: 0 0 0 4px rgba(200, 9, 54, .12);
}

.gco-receipt-upload .gco-receipt-box[data-state="idle"].is-dragover {
    border-style: solid;
    border-color: var(--gcr-crimson);
    box-shadow: 0 0 0 6px rgba(200, 9, 54, .09), 0 13px 28px rgba(200, 9, 54, .12);
    transform: scale(1.012);
}

.gco-receipt-upload .gco-receipt-box[data-state="busy"] {
    border-style: solid;
    border-color: var(--gcr-crimson);
    background: radial-gradient(ellipse at 11% 114%, #f5d9df 0, #fbedf0 27%, #fff 63%);
    cursor: wait;
}

.gco-receipt-upload .gco-receipt-box[data-state="done"] {
    border-style: solid;
    cursor: default;
}

.gco-receipt-upload .gco-receipt-box.is-invalid,
.gco-receipt-upload .gco-receipt-box.is-error {
    border-color: var(--gcr-crimson);
}

.gco-receipt-upload .gco-receipt-box.is-shaking {
    animation: gco-receipt-error-shake .44s ease-in-out;
}

.gco-receipt-upload .gco-receipt-idle {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    text-align: center;
}

.gco-receipt-upload .gco-receipt-idle__icon {
    display: grid;
    place-items: center;
    flex: 0 0 104px;
    width: 104px;
    height: 104px;
    margin: 0 0 23px;
    border-radius: 50%;
    background: linear-gradient(145deg, #ca0835, #a6072a);
    box-shadow: 0 18px 23px rgba(181, 5, 45, .24);
    color: #fff;
    transform: translateY(0);
    animation: gco-receipt-icon-float 3s ease-in-out infinite;
    transition: transform .25s cubic-bezier(.2, .7, .3, 1), box-shadow .25s ease;
}

.gco-receipt-upload .gco-receipt-idle__icon svg {
    display: block;
    width: 40px;
    height: 40px;
}

.gco-receipt-upload .gco-receipt-box.is-dragover .gco-receipt-idle__icon {
    animation: none;
    transform: translateY(-9px) scale(1.08);
    box-shadow: 0 24px 29px rgba(181, 5, 45, .28);
}

.gco-receipt-upload .gco-receipt-idle__title {
    margin: 0 0 8px;
    color: var(--gcr-ink);
    font-size: 19px;
    font-weight: 800;
    line-height: 1.6;
}

.gco-receipt-upload .gco-receipt-idle__hint {
    margin: 0 0 21px;
    color: var(--gcr-muted);
    font-size: 16px;
    line-height: 1.6;
}

.gco-receipt-upload .gco-receipt-idle__formats {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    column-gap: 5px;
    max-width: 100%;
    padding: 6px 20px;
    border: 1px solid #e3e0e1;
    border-radius: 999px;
    background: #fff;
    color: var(--gcr-muted);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.65;
}

.gco-receipt-upload .gco-receipt-busy {
    display: flex;
    align-items: center;
    justify-content: center;
    align-self: stretch;
    min-width: 0;
    min-height: 304px;
    pointer-events: none;
}

.gco-receipt-upload .gco-receipt-envelope {
    position: relative;
    top: 60px;
    flex: 0 0 288px;
    width: 288px;
    height: 200px;
    opacity: 0;
    transform-origin: 50% 100%;
    isolation: isolate;
    filter: drop-shadow(0 20px 16px rgba(106, 7, 32, .25));
}

.gco-receipt-upload .gco-receipt-envelope__back {
    position: absolute;
    z-index: 1;
    inset: 0;
    border-radius: 17px;
    background: #7c0b25;
}

.gco-receipt-upload .gco-receipt-envelope__paper-track {
    position: absolute;
    z-index: 2;
    inset: -400px 0 0;
    overflow: hidden;
}

.gco-receipt-upload .gco-receipt-envelope__paper {
    position: absolute;
    top: 282px;
    left: 67px;
    width: 154px;
    height: 192px;
    padding: 8px;
    border: 1px solid #eee;
    border-radius: 8px;
    background: #fff;
    box-shadow: 0 6px 18px rgba(30, 20, 24, .18);
    transform: translateY(-230px) rotate(-9deg);
    transform-origin: 50% 80%;
}

.gco-receipt-upload .gco-receipt-envelope__preview {
    display: grid;
    place-items: center;
    width: 100%;
    height: 100%;
    overflow: hidden;
    border: 1px solid #e7e2e4;
    border-radius: 3px;
    background: #f7f3f4;
}

.gco-receipt-upload .gco-receipt-envelope__front {
    position: absolute;
    z-index: 3;
    inset: 0;
    display: block;
    width: 100%;
    height: 100%;
}

.gco-receipt-upload .gco-receipt-envelope__flap {
    position: absolute;
    z-index: 4;
    top: 0;
    left: 0;
    display: block;
    width: 100%;
    height: 124px;
    transform: scaleY(-1);
    transform-origin: 50% 0;
}

.gco-receipt-upload .gco-receipt-envelope__seal {
    position: absolute;
    z-index: 5;
    top: 65px;
    left: 116px;
    display: grid;
    place-items: center;
    width: 56px;
    height: 56px;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 4px 10px rgba(68, 1, 17, .16);
    color: var(--gcr-crimson);
    opacity: 0;
    transform: scale(0);
}

.gco-receipt-upload .gco-receipt-envelope__seal > svg {
    position: relative;
    display: block;
    width: 31px;
    height: 31px;
}

.gco-receipt-upload .gco-receipt-envelope__ripple {
    position: absolute;
    inset: 0;
    border: 2px solid rgba(255, 255, 255, .75);
    border-radius: 50%;
    opacity: 0;
}

.gco-receipt-upload .gco-receipt-result {
    display: grid;
    grid-template-columns: 114px minmax(0, 1fr) 150px;
    align-items: center;
    gap: 26px;
    width: 100%;
    min-width: 0;
}

.gco-receipt-upload .gco-receipt-result__thumb {
    display: grid;
    place-items: center;
    width: 114px;
    height: 114px;
    overflow: hidden;
    border-radius: 27px;
    background: #ebebea;
    box-shadow: 0 12px 17px rgba(29, 21, 24, .11);
    color: var(--gcr-crimson);
    transform-origin: 50% 70%;
}

.gco-receipt-upload .gco-receipt-preview-image {
    display: block;
    width: 100%;
    max-width: none;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    object-fit: cover;
}

.gco-receipt-upload .gco-receipt-fallback {
    display: block;
    width: 46px;
    height: 46px;
    color: var(--gcr-crimson);
}

.gco-receipt-upload .gco-receipt-pdf {
    display: grid;
    place-items: center;
    width: 100%;
    height: 100%;
    background: linear-gradient(145deg, #cd153f, #a7072d);
    color: #fff;
    font-family: inherit;
    font-size: 26px;
    font-weight: 800;
    letter-spacing: 1.5px;
}

.gco-receipt-upload .gco-receipt-result__info { min-width: 0; }

.gco-receipt-upload .gco-receipt-result__success {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    max-width: 100%;
    padding: 7px 15px;
    border-radius: 999px;
    background: #e6ebe4;
    color: #22793f;
    font-size: 15px;
    font-weight: 750;
    line-height: 1.65;
}

.gco-receipt-upload .gco-receipt-result__success svg {
    display: block;
    flex: 0 0 25px;
    width: 25px;
    height: 25px;
}

.gco-receipt-upload .gco-receipt-result__name {
    min-width: 0;
    margin: 10px 0 14px;
    color: var(--gcr-ink);
    font-size: 18px;
    font-weight: 500;
    line-height: 1.55;
    overflow-wrap: anywhere;
    text-align: right;
    unicode-bidi: plaintext;
}

.gco-receipt-upload .gco-receipt-result__meta {
    margin: 0;
    color: var(--gcr-muted);
    font-size: 13px;
    line-height: 1.65;
    text-align: right;
}

.gco-receipt-upload .gco-receipt-result__actions {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
}

.gco-receipt-upload .gco-receipt-result__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 150px;
    min-height: 50px;
    margin: 0;
    padding: 10px 14px;
    border: 1px solid #e2dfe1;
    border-radius: 999px;
    background: #fff;
    box-shadow: none;
    color: var(--gcr-ink);
    font-family: inherit;
    font-size: 16px;
    font-weight: 500;
    line-height: 1.6;
    text-decoration: none;
    cursor: pointer;
    transition: color .2s ease, border-color .2s ease, background .2s ease;
}

.gco-receipt-upload .gco-receipt-result__button:hover {
    border-color: var(--gcr-crimson);
    background: #fff8fa;
    color: var(--gcr-crimson);
}

.gco-receipt-upload .gco-receipt-result__button:focus-visible {
    outline: 3px solid rgba(200, 9, 54, .2);
    outline-offset: 3px;
}

.gco-receipt-upload .gco-receipt-result__button svg {
    display: block;
    flex: 0 0 18px;
    width: 18px;
    height: 18px;
}

.gco-receipt-upload .gco-receipt-upload__error {
    margin: 8px 2px 0;
    color: var(--gcr-crimson);
    font-size: 13px;
    line-height: 1.75;
    text-align: right;
}

.gco-receipt-upload .gco-receipt-upload__status {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    clip-path: inset(50%);
    white-space: nowrap;
}

@keyframes gco-receipt-icon-float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-7px); }
}

@keyframes gco-receipt-error-shake {
    0%, 100% { transform: translateX(0); }
    20%, 60% { transform: translateX(-6px); }
    40%, 80% { transform: translateX(6px); }
}

@media (max-width: 650px) {
    .gco-receipt-upload .gco-receipt-box {
        min-height: 350px;
        padding: 24px 20px;
        border-radius: 28px;
    }

    .gco-receipt-upload .gco-receipt-result {
        grid-template-columns: 92px minmax(0, 1fr);
        column-gap: 16px;
        row-gap: 24px;
    }

    .gco-receipt-upload .gco-receipt-result__thumb {
        width: 92px;
        height: 92px;
        border-radius: 22px;
    }

    .gco-receipt-upload .gco-receipt-result__success {
        gap: 6px;
        padding: 6px 10px;
        font-size: 13px;
    }

    .gco-receipt-upload .gco-receipt-result__success svg {
        flex-basis: 21px;
        width: 21px;
        height: 21px;
    }

    .gco-receipt-upload .gco-receipt-result__name { font-size: 16px; }

    .gco-receipt-upload .gco-receipt-result__actions {
        grid-column: 1 / -1;
        flex-direction: row;
        justify-content: center;
    }

    .gco-receipt-upload .gco-receipt-result__button {
        flex: 1 1 0;
        width: auto;
        max-width: 150px;
        font-size: 14px;
    }
}

@media (max-width: 420px) {
    .gco-receipt-upload .gco-receipt-upload__label { font-size: 15px; }
    .gco-receipt-upload .gco-receipt-idle__icon { margin-bottom: 20px; }
    .gco-receipt-upload .gco-receipt-idle__title { font-size: 16px; }
    .gco-receipt-upload .gco-receipt-idle__hint { font-size: 14px; }
    .gco-receipt-upload .gco-receipt-idle__formats { padding-inline: 13px; font-size: 12px; }

    .gco-receipt-upload .gco-receipt-envelope {
        flex-basis: 240px;
        width: 240px;
        height: 167px;
    }

    .gco-receipt-upload .gco-receipt-envelope__paper {
        top: 288px;
        left: 56px;
        width: 128px;
        height: 160px;
        padding: 7px;
    }

    .gco-receipt-upload .gco-receipt-envelope__flap { height: 103px; }
    .gco-receipt-upload .gco-receipt-envelope__seal { top: 54px; left: 95px; width: 50px; height: 50px; }

    .gco-receipt-upload .gco-receipt-result {
        grid-template-columns: minmax(0, 1fr);
        justify-items: center;
        row-gap: 18px;
    }

    .gco-receipt-upload .gco-receipt-result__info { width: 100%; text-align: center; }
    .gco-receipt-upload .gco-receipt-result__name { margin: 8px 0; text-align: center; }
    .gco-receipt-upload .gco-receipt-result__meta { text-align: center; }
    .gco-receipt-upload .gco-receipt-result__actions { width: 100%; }
}

@media (max-width: 360px) {
    .gco-receipt-upload .gco-receipt-envelope { flex-basis: 192px; width: 192px; height: 134px; }
    .gco-receipt-upload .gco-receipt-envelope__paper { left: 45px; width: 102px; height: 128px; }
    .gco-receipt-upload .gco-receipt-envelope__flap { height: 83px; }
    .gco-receipt-upload .gco-receipt-envelope__seal { top: 44px; left: 76px; width: 40px; height: 40px; }
    .gco-receipt-upload .gco-receipt-envelope__seal > svg { width: 25px; height: 25px; }
}

@media (prefers-reduced-motion: reduce) {
    .gco-receipt-upload .gco-receipt-idle__icon { animation: none; }
    .gco-receipt-upload .gco-receipt-box.is-shaking { animation: none; }
    .gco-receipt-upload .gco-receipt-box,
    .gco-receipt-upload .gco-receipt-idle__icon,
    .gco-receipt-upload .gco-receipt-result__button { transition: none; }
    .gco-receipt-upload .gco-receipt-box.is-dragover { transform: none; }
    .gco-receipt-upload .gco-receipt-box.is-dragover .gco-receipt-idle__icon { transform: none; }
}

assets/css/settings-dashboard.css.content:
@font-face {
  font-family: 'Genosys Settings';
  src: url('../fonts/Vazirmatn-Variable.woff2') format('woff2');
  font-weight: 100 900;
  font-display: swap;
}
.gs-settings {
  --gs-crimson: #c8102e;
  --gs-deep: #9e0b24;
  --gs-ink: #171923;
  --gs-muted: #817e7a;
  --gs-line: #dddddf;
  --gs-pink: #f5dade;
  box-sizing: border-box;
  max-width: 1240px;
  margin: 0 auto;
  padding: 32px 16px 135px;
  direction: rtl;
  color: var(--gs-ink);
  font: 400 15px/1.8 'Genosys Settings', sans-serif;
}
.gs-settings *, .gs-settings *::before, .gs-settings *::after { box-sizing: border-box; }
.gs-settings button, .gs-settings input, .gs-settings select, .gs-settings textarea { font: inherit; }
.gs-settings button { cursor: pointer; }
.gs-settings a { color: var(--gs-crimson); text-decoration: none; }
.gs-settings a:hover { color: var(--gs-deep); }
.gs-settings button:focus-visible, .gs-settings a:focus-visible, .gs-settings input:focus-visible, .gs-settings select:focus-visible, .gs-settings textarea:focus-visible {
  outline: 3px solid rgba(200, 16, 46, .22);
  outline-offset: 4px;
}
.gs-settings__header { padding: 0 0 33px; }
.gs-settings__header h1 { margin: 0 0 13px; padding: 0; color: var(--gs-ink); font-size: 34px; font-weight: 800; line-height: 1.55; }
.gs-settings__header p { margin: 0; color: var(--gs-muted); font-size: 16px; }
.gs-tabs { display: flex; align-items: center; gap: 10px; overflow-x: auto; overscroll-behavior-x: contain; scrollbar-width: thin; padding: 9px 0 17px; margin-bottom: 24px; scroll-padding: 20px; }
.gs-tab { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; gap: 11px; min-height: 58px; padding: 13px 24px; border: 0; border-radius: 999px; background: #fff; color: #24242a; font-weight: 700; white-space: nowrap; box-shadow: 0 3px 8px rgba(23,25,35,.045); transition: background .18s ease, color .18s ease, box-shadow .18s ease; }
.gs-tab svg, .gs-tab .dashicons { width: 23px; height: 23px; flex-shrink: 0; color: var(--gs-crimson); }
.gs-tab:hover { color: var(--gs-crimson); background: #fff9fa; }
