.gs-settings .gs-card__heading h2 { font-size: 24px; font-weight: 800; }
.gs-settings .gs-tab { font-size: 18px; font-weight: 700; }
.gs-settings .gs-field > label, .gs-settings .gs-field > .gs-field__label { font-size: 18px; }
.gs-settings .gs-field input:not([type='checkbox']):not([type='radio']):not([type='color']):not([type='hidden']), .gs-settings .gs-field select, .gs-settings .gs-field textarea { font-size: 18px; }
.gs-settings .gs-card__heading p, .gs-settings .gs-description { font-size: 16px; }
.gs-settings .gs-media [data-media-label] { font-size: 16px; }
.gs-settings .gs-media small, .gs-settings .gs-media__hint { font-size: 14px; }
.gs-settings .gs-button, .gs-settings .gs-outline, .gs-settings [data-media-choose], .gs-settings [data-add-row] { font-size: 16px; }
.gs-settings .gs-section-row__label { font-size: 18px; }
.gs-settings .gs-repeater__row > .gs-field > label { font-size: 14px; }
.gs-settings .gs-repeater__row .gs-field input:not([type='checkbox']):not([type='color']):not([type='hidden']), .gs-settings .gs-repeater__row .gs-field select { font-size: 15px; }
.gs-settings .gs-repeater__row [data-media-label], .gs-settings .gs-repeater__row [data-media-choose] { font-size: 13px; }
.gs-settings .gs-nav-preview > nav { font-size: 17px; }
.gs-settings [data-preview-mode] { font-size: 15px; }
.gs-settings .gs-preview-login { font-size: 16px; }
@media (min-width: 1181px) { .gs-settings { padding-inline: 0; } }
@media (max-width: 782px) {
  .gs-settings { font-size: 16px; }
  .gs-settings .gs-settings__header h1 { font-size: 29px; }
  .gs-settings .gs-card__heading h2 { font-size: 21px; }
  .gs-settings .gs-tab { font-size: 16px; }
  .gs-settings .gs-field > label, .gs-settings .gs-field > .gs-field__label { font-size: 16px; }
  .gs-settings .gs-field input:not([type='checkbox']):not([type='radio']):not([type='color']):not([type='hidden']), .gs-settings .gs-field select, .gs-settings .gs-field textarea { font-size: 16px; }
  .gs-settings .gs-card__heading p, .gs-settings .gs-description { font-size: 14px; }
  .gs-settings .gs-button, .gs-settings .gs-outline, .gs-settings [data-media-choose], .gs-settings [data-add-row] { font-size: 14px; }
}
@media (max-width: 480px) {
  .gs-settings .gs-card__heading h2 { font-size: 19px; }
  .gs-settings .gs-nav-preview > nav { font-size: 12px; }
  .gs-settings .gs-preview-login { font-size: 11px; }
  .gs-settings .gs-section-row__label { font-size: 14px; }
  .gs-settings [data-preview-mode] { font-size: 12px; }
}
/* Slider rows follow the compact single-line editor in the supplied design. */
.gs-settings .gs-slide-row { display: grid; grid-template-columns: minmax(0,1.4fr) minmax(0,1fr) minmax(0,1fr) 46px; align-items: center; gap: 12px; padding: 13px 15px; min-height: 82px; }
.gs-settings .gs-slide-row > .gs-field { min-width: 0; width: 100%; }
.gs-settings .gs-slide-row .gs-media { height: 54px; min-height: 54px; width: 100%; padding: 6px 8px; gap: 8px; border: 1px solid var(--gs-line); border-radius: 18px; background: #fff; }
.gs-settings .gs-slide-row .gs-media [data-media-preview] { flex: 0 0 34px; width: 34px; height: 34px; border: 0; border-radius: 7px; background: transparent; }
.gs-settings .gs-slide-row .gs-media [data-media-preview] img { padding: 0; border-radius: 6px; }
.gs-settings .gs-slide-row .gs-media [data-media-preview] > svg { width: 23px; height: 23px; }
.gs-settings .gs-slide-row .gs-media__copy { flex: 1 1 0; max-width: none; min-width: 0; }
.gs-settings .gs-slide-row [data-media-label] { font-size: 18px; font-weight: 400; direction: ltr; text-align: right; }
.gs-settings .gs-slide-row .gs-media__actions { display: flex; flex-direction: row; flex: 0 0 auto; gap: 4px; margin: 0; }
.gs-settings .gs-slide-row [data-media-choose] { min-height: 40px; height: 40px; padding: 8px 11px; font-size: 16px; }
.gs-settings .gs-slide-row [data-media-remove] { display: inline-flex; align-items: center; justify-content: center; min-height: 26px; height: 26px; width: 24px; padding: 0; font-size: 0; }
.gs-settings .gs-slide-row [data-media-remove]::before { content: '\00d7'; font-size: 20px; line-height: 1; }
.gs-settings .gs-slide-row .gs-field input:not([type='checkbox']):not([type='radio']):not([type='color']):not([type='hidden']) { min-height: 54px; height: 54px; padding: 10px 18px; font-size: 18px; }
.gs-settings .gs-slide-row > [data-remove-row] { width: 46px; height: 46px; margin: 0; }
@media (min-width: 783px) {
  .gs-settings .gs-slide-row > .gs-field > label { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); clip-path: inset(50%); white-space: nowrap; border: 0; }
}
@media (max-width: 782px) {
  .gs-settings .gs-slide-row { grid-template-columns: minmax(0,1fr); min-height: 0; gap: 13px; }
  .gs-settings .gs-slide-row > .gs-field > label { margin-bottom: 6px; font-size: 15px; }
  .gs-settings .gs-slide-row .gs-field input:not([type='checkbox']):not([type='radio']):not([type='color']):not([type='hidden']) { font-size: 16px; }
  .gs-settings .gs-slide-row [data-media-label] { font-size: 16px; }
  .gs-settings .gs-slide-row [data-media-choose] { font-size: 14px; }
  .gs-settings .gs-slide-row > [data-remove-row] { justify-self: end; }
}

assets/css/shop.css.content:
/* Shop archive only. Product cards retain the shared homepage component styles. */
.genosys-shop {
    --shop-crimson: #ce0935;
    --shop-deep: #aa092c;
    --shop-ink: #202027;
    --shop-muted: #88817d;
    --shop-line: #e3e1e1;
    --shop-sticky-top: 24px;
    direction: rtl;
    color: var(--shop-ink);
    background: #fff;
    font-family: Vazirmatn, Tahoma, Arial, sans-serif;
    line-height: 1.75;
    min-height: 65vh;
}
.genosys-shop *, .genosys-shop *::before, .genosys-shop *::after { box-sizing: border-box; }
.genosys-shop button, .genosys-shop input, .genosys-shop select { font-family: inherit; }
.genosys-shop button { cursor: pointer; }
.genosys-shop [hidden] { display: none !important; }
.genosys-shop__container { width: min(1600px, calc(100% - 48px)); margin-inline: auto; padding: 24px clamp(24px, 2vw, 32px) 90px; }
.genosys-shop__breadcrumb { display: flex; align-items: center; gap: 6px; margin: 0 0 22px; padding: 0; color: var(--shop-muted); font-size: 14px; }
.genosys-shop__breadcrumb a { color: inherit; text-decoration: none; }
.genosys-shop__breadcrumb a:hover { color: var(--shop-crimson); }
.genosys-shop__heading { margin-bottom: 40px; }
.genosys-shop__title { margin: 0; color: var(--shop-ink); font-size: clamp(36px, 3.25vw, 52px); line-height: 1.45; font-weight: 800; letter-spacing: -.8px; }
.genosys-shop__title span, .genosys-shop__title em { color: var(--shop-crimson); font-style: normal; }
.genosys-shop__title.genosys-shop__heading { margin-bottom: 40px; }
.genosys-shop__description { max-width: 780px; margin: 12px 0 0; color: var(--shop-muted); font-size: 15px; }
.genosys-shop__layout { display: grid; grid-template-columns: minmax(285px, 360px) minmax(0, 1fr); align-items: start; gap: 40px; }
.genosys-shop__sidebar {
    position: sticky;
    top: var(--shop-sticky-top);
    min-width: 0;
    max-height: calc(100vh - var(--shop-sticky-top) - 24px);
    max-height: calc(100svh - var(--shop-sticky-top) - 24px);
    margin: 0 -6px;
    padding: 6px;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-gutter: stable;
    scrollbar-width: thin;
    scrollbar-color: #efb1bf #f4f3f3;
}
.genosys-shop__sidebar::-webkit-scrollbar { width: 7px; }
.genosys-shop__sidebar::-webkit-scrollbar-track { border-radius: 10px; background: #f4f3f3; }
.genosys-shop__sidebar::-webkit-scrollbar-thumb { border: 1px solid #fff; border-radius: 10px; background: #efb1bf; }
.genosys-shop__filter-form { display: grid; gap: 22px; margin: 0; }
.genosys-shop__panel { min-width: 0; margin: 0; padding: 22px 25px 24px; border: 1px solid #ebe9e9; border-radius: 32px; background: #fff; box-shadow: 0 0 0 5px #f5f5f580, 0 7px 23px #20202709; }
.genosys-shop__panel > summary { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 0; padding: 0; color: var(--shop-ink); font-size: 20px; line-height: 1.7; font-weight: 750; list-style: none; cursor: pointer; }
.genosys-shop__panel > summary::-webkit-details-marker { display: none; }
.genosys-shop__panel > summary::after { content: ""; display: block; flex: 0 0 10px; width: 10px; height: 10px; margin-inline-end: 3px; border-right: 2px solid var(--shop-crimson); border-bottom: 2px solid var(--shop-crimson); transform: rotate(45deg); transition: transform 180ms ease; }
.genosys-shop__panel:not([open]) > summary::after { transform: rotate(-45deg); }
.genosys-shop__panel > summary svg { display: none; }
.genosys-shop__panel[open] > summary { margin-bottom: 18px; }
.genosys-shop__categories { display: grid; gap: 2px; margin: 0; padding: 0; list-style: none; }
.genosys-shop__category-row { display: grid; grid-template-columns: 28px minmax(0, 1fr) 28px; align-items: center; gap: 15px; min-height: 43px; margin: 0; color: var(--shop-ink); font-size: 17px; line-height: 1.6; cursor: pointer; }
.genosys-shop__category-row input { appearance: none; -webkit-appearance: none; display: block; flex-shrink: 0; width: 28px; height: 28px; margin: 0; border: 1px solid #e1dede; border-radius: 10px; background: #fff; cursor: pointer; transition: border-color 150ms ease, background 150ms ease, box-shadow 150ms ease; }
.genosys-shop__category-row input:checked { border-color: var(--shop-crimson); background: var(--shop-crimson); }
.genosys-shop__category-row input:checked::after { content: ""; display: block; width: 11px; height: 6px; margin: 8px 7px; border-left: 2px solid #fff; border-bottom: 2px solid #fff; transform: rotate(-45deg); }
.genosys-shop__category-row:hover input { border-color: #d66e87; }
.genosys-shop__category-name { min-width: 0; padding-inline-start: calc(var(--category-depth, 0) * 12px); overflow-wrap: anywhere; }
.genosys-shop__category-count { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: #f5f4f2; color: #938c87; font-size: 13px; line-height: 1; }
.genosys-shop__category-row--child .genosys-shop__category-name { padding-inline-start: 13px; font-size: 15px; }
.genosys-shop__filter-empty { margin: 0; color: var(--shop-muted); font-size: 14px; }
.genosys-shop__price-range { position: relative; direction: ltr; height: 43px; margin: 20px 5px 16px; }
.genosys-shop__price-track, .genosys-shop__range-track { position: absolute; top: 19px; right: 0; left: 0; height: 6px; border-radius: 6px; background: linear-gradient(to right, #eee9eb var(--price-min, 0%), #a40a2c var(--price-min, 0%), #d70838 var(--price-max, 100%), #eee9eb var(--price-max, 100%)); pointer-events: none; }
.genosys-shop__price-fill { position: absolute; top: 0; bottom: 0; left: var(--price-min, 0%); right: calc(100% - var(--price-max, 100%)); border-radius: inherit; background: linear-gradient(90deg, #a40a2c, #d70838); }
.genosys-shop__price-range input[type="range"] { appearance: none; -webkit-appearance: none; position: absolute; inset: 0; z-index: 2; width: 100%; height: 43px; margin: 0; padding: 0; border: 0; outline: 0; background: transparent; direction: ltr; pointer-events: none; }
.genosys-shop__price-range input[type="range"]::-webkit-slider-runnable-track { height: 6px; border: 0; background: transparent; }
.genosys-shop__price-range input[type="range"]::-moz-range-track { height: 6px; border: 0; background: transparent; }
.genosys-shop__price-range input[type="range"]::-webkit-slider-thumb { appearance: none; -webkit-appearance: none; width: 28px; height: 28px; margin-top: -11px; border: 3px solid #db0b3b; border-radius: 50%; background: #fff; box-shadow: 0 4px 10px #a30a2c3d; cursor: grab; pointer-events: auto; }
.genosys-shop__price-range input[type="range"]::-moz-range-thumb { width: 22px; height: 22px; border: 3px solid #db0b3b; border-radius: 50%; background: #fff; box-shadow: 0 4px 10px #a30a2c3d; cursor: grab; pointer-events: auto; }
.genosys-shop__price-range input[type="range"]:active::-webkit-slider-thumb { cursor: grabbing; }
.genosys-shop__price-range input[type="range"]:active::-moz-range-thumb { cursor: grabbing; }
.genosys-shop__price-range input[type="range"]:focus-visible::-webkit-slider-thumb { outline: 2px solid var(--shop-crimson); outline-offset: 4px; }
.genosys-shop__price-range input[type="range"]:focus-visible::-moz-range-thumb { outline: 2px solid var(--shop-crimson); outline-offset: 4px; }
.genosys-shop__price-values { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.genosys-shop__price-value, .genosys-shop__price-box { display: grid; gap: 3px; min-width: 0; margin: 0; padding: 9px 8px 10px; border: 1px solid transparent; border-radius: 20px; background: #f5f4f2; text-align: center; }
.genosys-shop__price-value > span, .genosys-shop__price-box > span { color: var(--shop-muted); font-size: 12px; line-height: 1.6; }
.genosys-shop__price-value input, .genosys-shop__price-box input { display: block; width: 100%; min-width: 0; min-height: 25px; padding: 0; border: 0; outline: 0; border-radius: 0; background: transparent; color: var(--shop-ink); direction: ltr; text-align: center; font-size: 15px; line-height: 1.7; font-weight: 750; }
.genosys-shop__price-value input::placeholder, .genosys-shop__price-box input::placeholder { opacity: 1; color: var(--shop-ink); }
.genosys-shop__price-value input::-webkit-inner-spin-button, .genosys-shop__price-value input::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
.genosys-shop__price-value input[type="number"] { -moz-appearance: textfield; }
.genosys-shop__price-value:focus-within, .genosys-shop__price-box:focus-within { border-color: #e57f99; box-shadow: 0 0 0 3px #e10a3c0c; }
.genosys-shop__price-currency { margin: 15px 0 0; color: var(--shop-muted); font-size: 15px; text-align: center; }
.genosys-shop__status { display: grid; gap: 14px; }
.genosys-shop__status-row { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 15px; min-height: 32px; margin: 0; color: var(--shop-ink); font-size: 16px; line-height: 1.6; cursor: pointer; }
.genosys-shop__status-row input { position: absolute; inset-inline-end: 0; width: 55px; height: 32px; margin: 0; opacity: 0; cursor: pointer; }
.genosys-shop__switch { position: relative; display: block; flex: 0 0 55px; width: 55px; height: 32px; border-radius: 999px; background: #d6d6d8; transition: background 180ms ease; pointer-events: none; }
.genosys-shop__switch::after { content: ""; position: absolute; top: 4px; right: 4px; width: 24px; height: 24px; border-radius: 50%; background: #fff; box-shadow: 0 2px 4px #2223; transition: transform 180ms ease; }
.genosys-shop__status-row input:checked ~ .genosys-shop__switch { background: var(--shop-crimson); }
.genosys-shop__status-row input:checked ~ .genosys-shop__switch::after { transform: translateX(-23px); }
.genosys-shop__status-row input:focus-visible ~ .genosys-shop__switch { outline: 2px solid var(--shop-crimson); outline-offset: 4px; }
.genosys-shop__reset, .genosys-shop__apply, .genosys-shop__open-filters { display: flex; align-items: center; justify-content: center; gap: 9px; width: 100%; min-height: 58px; margin: 0; padding: 11px 20px; border: 1px solid #df0a3a; border-radius: 999px; background: #fff; color: #db0837; font-size: 16px; line-height: 1.6; font-weight: 600; text-decoration: none; transition: background 180ms ease, box-shadow 180ms ease; }
.genosys-shop__reset:hover { background: #fff5f7; color: #a5082b; }
.genosys-shop__apply { border-color: transparent; background: linear-gradient(120deg, #d10a39, #a9092d); color: #fff; box-shadow: 0 10px 19px -11px #a8073299; }
.genosys-shop__apply:hover { background: #a9092d; color: #fff; }
.genosys-shop.is-enhanced .genosys-shop__apply { display: none; }
.genosys-shop__main { min-width: 0; }
.genosys-shop__toolbar { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 46px; margin: 0 0 22px; }
.genosys-shop__count { margin: 0; color: var(--shop-muted); font-size: 16px; line-height: 1.7; }
.genosys-shop__count strong { color: #243344; font-weight: 700; }
.genosys-shop__toolbar-actions { display: flex; flex: 0 0 auto; align-items: center; gap: 12px; }
.genosys-shop__sort { position: relative; flex: 0 0 190px; width: 190px; height: 46px; }
.genosys-shop__sort::after { content: ""; position: absolute; top: 16px; left: 23px; width: 10px; height: 10px; border-right: 2px solid var(--shop-crimson); border-bottom: 2px solid var(--shop-crimson); transform: rotate(45deg); pointer-events: none; }
.genosys-shop__sort select { appearance: none; -webkit-appearance: none; display: block; width: 100%; height: 46px; padding: 7px 24px 7px 51px; border: 1px solid var(--shop-line); border-radius: 999px; background: #fff; color: var(--shop-ink); font-size: 16px; line-height: 1.6; font-weight: 500; cursor: pointer; }
.genosys-shop__sort > svg { display: none; }
.genosys-shop__grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 26px 24px; margin: 0; padding: 5px; list-style: none; }
.genosys-shop__grid > .product-card { min-width: 0; width: 100%; box-shadow: 0 0 0 5px #f2f1f180, 0 8px 25px #25232a13; }
/* Keep WooCommerce's automatic image height from exposing the card background. */
.genosys-shop__grid .product-card__image { width: 100%; height: 100%; }
.genosys-shop__grid > .product-card:hover { box-shadow: 0 0 0 5px #f7e8edb3, 0 15px 28px -7px #a5113224; }
.genosys-shop__pagination { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 10px; margin: 46px 0 0; padding: 0; text-align: center; }
.genosys-shop__pagination ul.page-numbers { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 10px; margin: 0; padding: 0; border: 0; list-style: none; }
.genosys-shop__pagination ul.page-numbers > li { display: block; margin: 0; padding: 0; border: 0; }
.genosys-shop__pagination a.page-numbers, .genosys-shop__pagination span.page-numbers { display: inline-flex; align-items: center; justify-content: center; gap: 9px; min-width: 57px; height: 57px; padding: 9px 14px; border: 1px solid var(--shop-line); border-radius: 999px; background: #fff; color: #223043; font-size: 17px; line-height: 1; font-weight: 600; text-decoration: none; transition: border-color 160ms ease, box-shadow 160ms ease, color 160ms ease; }
.genosys-shop__pagination a.page-numbers:hover { border-color: #e191a5; color: var(--shop-crimson); }
.genosys-shop__pagination span.page-numbers.current { border-color: transparent; background: linear-gradient(135deg, #d10b39, #a8072a); color: #fff; box-shadow: 0 15px 22px -11px #a50b3a8a; }
.genosys-shop__pagination .page-numbers.prev, .genosys-shop__pagination .page-numbers.next { min-width: 116px; padding-inline: 22px; }
.genosys-shop__pagination .page-numbers.prev::before, .genosys-shop__pagination .page-numbers.next::after { content: ""; width: 8px; height: 8px; border-right: 1.8px solid currentColor; border-bottom: 1.8px solid currentColor; flex: 0 0 8px; }
.genosys-shop__pagination .page-numbers.prev::before { transform: rotate(-45deg); }
.genosys-shop__pagination .page-numbers.next::after { transform: rotate(135deg); }
.genosys-shop__pagination .page-numbers.dots { min-width: 28px; padding-inline: 0; border-color: transparent; color: var(--shop-muted); }
.genosys-shop__pagination svg { display: block; width: 17px; height: 17px; }
.genosys-shop__pagination .page-numbers[aria-disabled="true"] { border-color: #f1eeee; color: #aaa5a3; }
.genosys-shop__empty { display: grid; justify-items: center; gap: 15px; min-height: 330px; padding: 54px 28px; border: 1px solid #ebe7e8; border-radius: 32px; background: #fcfafb; text-align: center; }
.genosys-shop__empty > svg { width: 52px; height: 52px; color: var(--shop-crimson); }
.genosys-shop__empty h2 { margin: 0; font-size: 23px; font-weight: 750; }
.genosys-shop__empty p { max-width: 460px; margin: 0; color: var(--shop-muted); font-size: 15px; }
.genosys-shop__empty .genosys-shop__reset { width: auto; min-height: 48px; margin-top: 6px; padding-inline: 26px; }
.genosys-shop__drawer-heading, .genosys-shop__drawer-header, .genosys-shop__close-filters, .genosys-shop__open-filters, .genosys-shop__filter-toggle, .genosys-shop__backdrop { display: none; }
.genosys-shop__filter-notice { margin: 0; color: var(--shop-muted); font-size: 13px; }
.genosys-shop a:focus-visible, .genosys-shop button:focus-visible, .genosys-shop select:focus-visible, .genosys-shop summary:focus-visible, .genosys-shop input[type="checkbox"]:focus-visible { outline: 2px solid var(--shop-crimson); outline-offset: 4px; }
.genosys-shop__price-value input:focus-visible, .genosys-shop__price-box input:focus-visible, .genosys-shop__status-row input:focus-visible { outline: 0; }
@media (max-width: 1250px) {
    .genosys-shop__layout { grid-template-columns: 295px minmax(0, 1fr); gap: 28px; }
    .genosys-shop__panel { padding-inline: 20px; }
    .genosys-shop__panel > summary { font-size: 18px; }
    .genosys-shop__category-row { gap: 10px; font-size: 16px; }
    .genosys-shop__status-row { font-size: 15px; }
    .genosys-shop__grid { gap: 24px 20px; }
}
@media (max-width: 1100px) {
    .genosys-shop__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .genosys-shop__toolbar { gap: 12px; }
    .genosys-shop__count { font-size: 14px; }
    .genosys-shop__sort { flex-basis: 168px; width: 168px; }
    .genosys-shop__sort select { padding-inline-start: 18px; font-size: 14px; }
}
@media (max-width: 820px) {
    .genosys-shop__container { padding: 22px 0 60px; }
    .genosys-shop__breadcrumb { margin-bottom: 14px; font-size: 12px; }
    .genosys-shop__heading { margin-bottom: 26px; }
    .genosys-shop__title.genosys-shop__heading { margin-bottom: 26px; }
    .genosys-shop__title { font-size: clamp(32px, 6vw, 44px); letter-spacing: -.5px; }
    .genosys-shop__layout { grid-template-columns: minmax(0, 1fr); gap: 26px; }
    .genosys-shop__sidebar { position: static; max-height: none; overflow: visible; margin: 0; padding: 0; }
    .genosys-shop__toolbar { flex-wrap: wrap; gap: 12px; margin-bottom: 18px; }
    .genosys-shop__count { flex: 1 0 100%; font-size: 14px; }
    .genosys-shop__toolbar-actions { flex: 1 0 100%; width: 100%; }
    .genosys-shop__sort { flex: 1 1 160px; width: auto; }
    .genosys-shop__sort select { font-size: 15px; }
    .genosys-shop__grid { gap: 23px 18px; padding: 4px; }
    .genosys-shop__pagination { margin-top: 34px; }
    .genosys-shop__pagination a.page-numbers, .genosys-shop__pagination span.page-numbers { min-width: 46px; height: 46px; padding: 9px 11px; font-size: 15px; }
    .genosys-shop__pagination .page-numbers.prev, .genosys-shop__pagination .page-numbers.next { min-width: 89px; padding-inline: 14px; }
    .genosys-shop.is-enhanced [data-shop-open] { display: inline-flex; align-items: center; justify-content: center; gap: 9px; flex: 1 1 150px; width: auto; min-height: 46px; margin: 0; padding: 8px 17px; border: 1px solid #df0a3a; border-radius: 999px; background: #fff; color: #db0837; font-size: 15px; line-height: 1.6; font-weight: 600; }
    .genosys-shop [data-shop-open] svg { width: 18px; height: 18px; }
    .genosys-shop.is-enhanced .genosys-shop__sidebar {
        position: fixed;
        z-index: 100002;
        inset: 0 0 0 auto;
        width: min(385px, calc(100% - 28px));
        height: 100vh;
        height: 100svh;
        max-height: none;
        margin: 0;
        padding: max(22px, env(safe-area-inset-top)) 22px max(24px, env(safe-area-inset-bottom));
        border-radius: 26px 0 0 26px;
        background: #fff;
        overflow-y: auto;
        visibility: hidden;
        transform: translateX(105%);
        transition: transform 260ms cubic-bezier(.2, .75, .25, 1), visibility 260ms;
        scrollbar-gutter: auto;
    }
    .genosys-shop.is-enhanced .genosys-shop__backdrop { display: block; position: fixed; z-index: 100001; inset: 0; margin: 0; border: 0; padding: 0; background: #20202755; backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px); opacity: 0; visibility: hidden; transition: opacity 230ms ease, visibility 230ms; }
    .genosys-shop.is-filter-open .genosys-shop__sidebar { transform: translateX(0); visibility: visible; }
    .genosys-shop.is-filter-open .genosys-shop__backdrop { opacity: 1; visibility: visible; }
    .genosys-shop.is-enhanced .genosys-shop__drawer-heading, .genosys-shop.is-enhanced .genosys-shop__drawer-header { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 25px; padding-bottom: 15px; border-bottom: 1px solid var(--shop-line); }
    .genosys-shop__drawer-heading h2, .genosys-shop__drawer-heading strong, .genosys-shop__drawer-header h2 { margin: 0; font-size: 21px; font-weight: 750; }
    .genosys-shop.is-enhanced [data-shop-close] { display: grid; place-items: center; flex: 0 0 39px; width: 39px; height: 39px; margin: 0; padding: 8px; border: 1px solid var(--shop-line); border-radius: 50%; background: #f7f6f5; color: var(--shop-ink); }
    .genosys-shop [data-shop-close] svg { width: 19px; height: 19px; }
    .genosys-shop.is-enhanced .genosys-shop__apply { display: flex; position: sticky; bottom: 0; margin-top: 0; box-shadow: 0 0 0 8px #fff, 0 10px 20px -12px #a8073299; }
    .genosys-shop__filter-form { gap: 22px; }
    .genosys-shop__panel { border-radius: 28px; }
    .genosys-shop__panel > summary { font-size: 18px; }
    .genosys-shop__empty { min-height: 280px; padding-inline: 20px; }
}
@media (max-width: 600px) and (min-width: 420px) {
    .genosys-shop__grid { gap: 22px 16px; }
}
@media (max-width: 419px) {
    .genosys-shop__grid { grid-template-columns: minmax(0, 1fr); gap: 24px; }
    .genosys-shop__pagination ul.page-numbers { gap: 7px; }
    .genosys-shop__pagination { gap: 7px; }
    .genosys-shop__pagination a.page-numbers, .genosys-shop__pagination span.page-numbers { min-width: 43px; height: 43px; }
    .genosys-shop__pagination .page-numbers.prev, .genosys-shop__pagination .page-numbers.next { min-width: 78px; padding-inline: 12px; }
}
@media (prefers-reduced-motion: reduce) {
    .genosys-shop *, .genosys-shop *::before, .genosys-shop *::after { scroll-behavior: auto !important; transition: none !important; }
}

assets/css/single-product.css.content:
/* The single-product layout is scoped here so the homepage stays untouched. */
body.single-product .genosys-product-page {
    width: min(100%, 1500px);
    margin-inline: auto;
    padding: 24px clamp(20px, 4vw, 72px) 90px;
    color: #252a30;
}

body.single-product .genosys-product-page .woocommerce-breadcrumb {
    margin: 0 0 26px;
    color: #85858a;
    font-size: 13px;
    line-height: 1.8;
    text-align: right;
}

body.single-product .genosys-product-page .woocommerce-breadcrumb a {
    color: inherit;
    text-decoration: none;
}

body.single-product .genosys-product-page .woocommerce-breadcrumb a:hover {
    color: #c8103b;
}

.genosys-product-page .genosys-product {
    display: block;
    width: 100%;
    min-width: 0;
}

.genosys-product-page .genosys-product__hero {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    align-items: stretch;
    gap: clamp(22px, 2.5vw, 38px);
    min-width: 0;
}

.genosys-product-page .genosys-product__gallery {
    position: relative;
    grid-column: 2;
    grid-row: 1;
    display: block;
    min-width: 0;
    min-height: 630px;
    padding: 0;
    overflow: hidden;
    border: 5px solid #f4f4f5;
    border-radius: 42px;
    background: #fff;
    box-shadow: 0 8px 28px rgba(37, 42, 48, .045);
}

.genosys-product-page .genosys-product__info.summary {
    grid-column: 1;
    grid-row: 1;
    float: none !important;
    display: flex;
    flex-direction: column;
    width: auto !important;
    min-width: 0;
    min-height: 630px;
    margin: 0 !important;
    padding: clamp(28px, 3vw, 42px);
    border: 1px solid #f6c6ce;
    border-radius: 42px;
    background: radial-gradient(ellipse at 5% 105%, rgba(216, 32, 57, .30), transparent 66%), linear-gradient(155deg, #fff 37%, #fffafb 67%, #fceef0 100%);
    box-shadow: 0 8px 26px rgba(152, 40, 59, .055), inset 0 1px 0 rgba(255, 255, 255, .9);
    text-align: right;
}

/* WooCommerce's default floated gallery must participate in the grid. */
body.single-product .genosys-product .genosys-product__gallery div.images.woocommerce-product-gallery {
    float: none;
    position: absolute;
    inset: 0;
    display: block;
    width: 100%;
    height: 100%;
    min-width: 0;
    margin: 0;
    opacity: 1;
    background: #fff;
}

.genosys-product__gallery .woocommerce-product-gallery__wrapper,
.genosys-product__gallery .flex-viewport {
    width: 100%;
    height: 100% !important;
    min-width: 0;
    margin: 0;
    background: #fff;
}

.genosys-product__gallery .woocommerce-product-gallery__image {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    min-width: 0;
    background: #fff;
}

.genosys-product__gallery .woocommerce-product-gallery__image > a {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    min-width: 0;
    text-decoration: none;
}

body.single-product .genosys-product__gallery .woocommerce-product-gallery__image img {
    display: block;
    width: 100%;
    height: 100%;
    min-height: 0;
    max-height: none;
    margin: 0;
    object-fit: cover;
    object-position: center;
    background: #fff;
}

.genosys-product__gallery .flex-control-thumbs {
    position: absolute;
    right: 0;
    bottom: 18px;
    left: 0;
    z-index: 5;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 12px;
    width: 100%;
    margin: 0;
    padding: 0;
    list-style: none;
}

body.single-product .genosys-product__gallery .flex-control-thumbs li {
    float: none;
    width: 68px;
    margin: 0;
}

body.single-product .genosys-product__gallery .flex-control-thumbs li img {
    display: block;
    width: 68px;
    height: 68px;
    padding: 5px;
    border: 1px solid #e7e7e8;
    border-radius: 17px;
    object-fit: contain;
    background: #f9f9f9;
    opacity: 1;
    cursor: pointer;
    transition: border-color 180ms ease, box-shadow 180ms ease;
}

.genosys-product__gallery .flex-control-thumbs li img.flex-active,
.genosys-product__gallery .flex-control-thumbs li img:hover {
    border-color: #d0093d;
    box-shadow: 0 0 0 3px rgba(208, 9, 61, .10);
}

body.single-product .genosys-product__gallery .woocommerce-product-gallery__trigger {
    top: 22px;
    left: 22px;
    right: auto;
    z-index: 4;
    width: 50px;
    height: 50px;
    border: 1px solid #eeeeef;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 6px 16px rgba(0, 0, 0, .08);
}

.genosys-product__gallery-badge {
    position: absolute;
    top: 24px;
    right: 24px;
    z-index: 5;
    padding: 10px 22px;
    border-radius: 999px;
    background: linear-gradient(110deg, #d0093d, #a80630);
    box-shadow: 0 8px 16px rgba(186, 6, 49, .20);
    color: #fff;
    font-size: 13px;
    font-weight: 600;
    line-height: 1.6;
}

.genosys-product__gallery-badge--stock {
    background: #56575b;
    box-shadow: none;
}

.genosys-product__info .genosys-product__category {
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    min-height: 38px;
    max-width: 100%;
    padding: 6px 17px;
    overflow: hidden;
    border: 1px solid #f6c0c9;
    border-radius: 999px;
    background: #fff4f6;
    color: #c8103b;
    font-size: 13px;
    line-height: 1.5;
    text-decoration: none;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.genosys-product__info .genosys-product__category:hover {
    background: #ffe7eb;
}

body.single-product .genosys-product__info .product_title {
    margin: 25px 0 12px;
    color: #20242a;
    font-size: clamp(25px, 2.2vw, 34px);
    font-weight: 650;
    line-height: 1.55;
    overflow-wrap: anywhere;
}

.genosys-product__info .woocommerce-product-details__short-description {
    margin: 0;
    color: #797b80;
    font-size: 15px;
    line-height: 1.9;
}

.genosys-product__info .woocommerce-product-details__short-description p {
    margin: 0;
}

.genosys-product__info .woocommerce-product-rating {
    margin: 0 0 8px;
    color: #7c7d81;
    font-size: 13px;
}

.genosys-product__info .woocommerce-product-rating .star-rating {
    color: #c8103b;
}

.genosys-product__info .woocommerce-product-rating a {
    color: inherit;
}

.genosys-product__info .genosys-product__price {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 12px 20px;
    min-height: 112px;
    margin: 27px 0 0;
    padding: 22px 0;
    border-top: 1px solid rgba(115, 91, 97, .17);
    border-bottom: 1px solid rgba(115, 91, 97, .17);
}

body.single-product .genosys-product__info .genosys-product__price .price {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 4px 14px;
    min-width: 0;
    margin: 0;
    color: #c8103b;
    font-size: clamp(24px, 2.35vw, 36px);
    font-weight: 700;
    line-height: 1.45;
    overflow-wrap: anywhere;
}

.genosys-product__price .price ins {
    order: -1;
    background: transparent;
    color: inherit;
    font-weight: inherit;
    text-decoration: none;
}

.genosys-product__price .price del {
    color: #898b8f;
    font-size: 15px;
    font-weight: 400;
    opacity: 1;
}

.genosys-product__price .woocommerce-Price-currencySymbol {
    font-size: .48em;
    font-weight: 600;
}

.genosys-product__price .genosys-product__discount {
    display: inline-flex;
    align-items: center;
    min-height: 37px;
    padding: 6px 15px;
    border: 1px solid #f2c5cc;
    border-radius: 999px;
    background: rgba(255, 255, 255, .75);
    color: #bc1039;
    font-size: 13px;
    font-weight: 600;
    line-height: 1.4;
    white-space: nowrap;
}

body.single-product .genosys-product__price .price.genosys-product__price--unavailable {
    color: #66686d;
    font-size: 18px;
    font-weight: 500;
}

.genosys-product__info .genosys-product__stock,
.genosys-product__info .stock {
    margin: 15px 0 0;
    color: #696b70;
    font-size: 14px;
    font-weight: 500;
}

body.single-product .genosys-product__info p.stock.in-stock {
    display: inline-flex;
    align-items: center;
    align-self: flex-start;
    width: fit-content;
    max-width: 100%;
    padding: 7px 15px;
    border: 1px solid #b8dec9;
    border-radius: 999px;
    background: #eef8f2;
    color: #27734a;
    font-size: 13px;
    line-height: 1.5;
}

.genosys-product__info .genosys-product__sku {
    margin: 18px 0 0;
    color: #818287;
    font-size: 12px;
}

.genosys-product__info .genosys-product__sku a {
    color: #c8103b;
}

/* Native WooCommerce forms remain functional: these rules only restyle them. */
body.single-product .genosys-product__info form.cart {
    width: 100%;
    margin: auto 0 0;
    padding-top: 28px;
}

body.single-product .genosys-product.product-type-simple .genosys-product__info form.cart {
    display: flex;
    flex-wrap: nowrap;
    align-items: center;
    gap: 16px;
}

body.single-product .genosys-product.product-type-simple .genosys-product__info form.cart::before,
body.single-product .genosys-product.product-type-simple .genosys-product__info form.cart::after {
    display: none;
}

body.single-product .genosys-product.product-type-simple .genosys-product__info form.cart .quantity {
    flex: 0 0 148px;
}

body.single-product .genosys-product__info form.cart .quantity,
body.single-product .genosys-product__info .woocommerce-variation-add-to-cart .quantity {
    float: none;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 148px;
    height: 54px;
    min-width: 0;
    margin: 0;
    padding: 0 6px;
    border: 1px solid #e1e2e4;
    border-radius: 999px;
    background: #fff;
}

body.single-product .genosys-product__info form.cart .quantity input.qty {
    float: none;
    flex: 1 1 auto;
    width: 50px;
    min-width: 0;
    height: 50px;
    margin: 0;
    padding: 0 4px;
    border: 0;
    background: transparent;
    color: #24282d;
    font-size: 17px;
    font-weight: 600;
    line-height: 1;
    text-align: center;
    box-shadow: none;
}

body.single-product .genosys-product__info form.cart .quantity input.qty[readonly] {
    pointer-events: none;
    user-select: none;
    caret-color: transparent;
}

.genosys-product__info form.cart .quantity .genosys-qty-value {
    flex: 1 1 auto;
    min-width: 0;
    color: #24282d;
    font-size: 17px;
    font-weight: 600;
    line-height: 1;
    text-align: center;
    user-select: none;
}

.genosys-product__info form.cart .quantity .genosys-qty-button {
    flex: 0 0 32px;
    display: grid;
    place-items: center;
    width: 32px;
    height: 40px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: #252a30;
    font-family: inherit;
    font-size: 23px;
    font-weight: 400;
    line-height: 1;
    cursor: pointer;
}

.genosys-product__info form.cart .quantity .genosys-qty-button:hover {
    background: #fff0f3;
    color: #c8103b;
}

.genosys-product__info form.cart .quantity .genosys-qty-button:disabled {
    color: #b9b9bb;
    cursor: not-allowed;
}

.genosys-product__info form.cart .quantity input.qty::-webkit-inner-spin-button,
.genosys-product__info form.cart .quantity input.qty::-webkit-outer-spin-button {
    margin: 0;
    -webkit-appearance: none;
}

.genosys-product__info form.cart .quantity input.qty[type="number"] {
    -moz-appearance: textfield;
    appearance: textfield;
}

.genosys-product__info form.cart .quantity input.qty:focus-visible {
    outline: 2px solid #c8103b;
    outline-offset: 0;
    border-radius: 12px;
}

body.single-product .genosys-product__info form.cart .single_add_to_cart_button,
body.single-product .genosys-product__info form.cart .single_add_to_cart_button.button,
body.single-product .genosys-product__info form.cart .single_add_to_cart_button.button.alt {
    float: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-height: 54px;
    margin: 0;
    padding: 11px 22px;
    border: 0;
    border-radius: 999px;
    background: linear-gradient(110deg, #cf0839, #a80831);
    box-shadow: 0 10px 20px rgba(185, 10, 52, .20);
    color: #fff;
    font-family: inherit;
    font-size: 15px;
    font-weight: 600;
    line-height: 1.5;
    text-align: center;
    transition: box-shadow 180ms ease, transform 180ms ease, background-color 180ms ease;
}

body.single-product .genosys-product__info form.cart .single_add_to_cart_button:hover,
body.single-product .genosys-product__info form.cart .single_add_to_cart_button.button:hover,
body.single-product .genosys-product__info form.cart .single_add_to_cart_button.button.alt:hover {
    background: #a80831;
    box-shadow: 0 12px 23px rgba(185, 10, 52, .27);
    transform: translateY(-1px);
}

body.single-product .genosys-product__info form.cart .single_add_to_cart_button:disabled {
    box-shadow: none;
    opacity: .5;
    transform: none;
    cursor: not-allowed;
}

body.single-product .genosys-product.product-type-simple .genosys-product__info form.cart .single_add_to_cart_button {
    flex: 1 1 0;
    width: auto;
    min-width: 0;
    max-width: none;
}

.genosys-product__info form.variations_form {
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.genosys-product__info form.variations_form table.variations {
    width: 100%;
    margin: 0;
    border: 0;
}

.genosys-product__info form.variations_form table.variations tbody,
.genosys-product__info form.variations_form table.variations tr {
    display: block;
    width: 100%;
}

.genosys-product__info form.variations_form table.variations td,
.genosys-product__info form.variations_form table.variations th {
    display: block;
    width: 100%;
    padding: 0;
    border: 0;
    text-align: right;
}

.genosys-product__info form.variations_form table.variations label {
    display: block;
    margin: 0 0 7px;
    color: #45484d;
    font-size: 13px;
}

.genosys-product__info form.variations_form table.variations select {
    width: 100%;
    min-height: 46px;
    padding: 8px 14px;
    border: 1px solid #e8cdd1;
    border-radius: 13px;
    background: #fff;
    color: #2d3034;
    font-family: inherit;
    font-size: 14px;
}

.genosys-product__info form.variations_form .reset_variations {
    display: inline-block;
    margin: 7px 0 0;
    color: #a13a50;
    font-size: 12px;
}

.genosys-product__info .woocommerce-variation-description,
.genosys-product__info .woocommerce-variation-availability {
    color: #6a6d71;
    font-size: 13px;
}

.genosys-product__info .woocommerce-variation-price {
    margin: 5px 0 12px;
}

.genosys-product.is-variation-synced .woocommerce-variation-price {
    display: none;
}

.genosys-product__info .woocommerce-variation-add-to-cart {
    display: grid;
    grid-template-columns: 148px minmax(0, 1fr);
    align-items: center;
    gap: 16px;
    margin-top: 8px;
}

/* Native description, attributes, comments and related products follow the hero. */
.genosys-product-page .woocommerce-tabs {
    clear: both;
    margin-top: clamp(60px, 6vw, 94px);
}

body.single-product .genosys-product .woocommerce-tabs ul.tabs {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    width: fit-content;
    max-width: 100%;
    margin: 0 0 26px;
    padding: 5px;
    border: 0;
    border-radius: 999px;
    background: #f5f5f6;
}

body.single-product .genosys-product .woocommerce-tabs ul.tabs::before,
body.single-product .genosys-product .woocommerce-tabs ul.tabs li::before,
body.single-product .genosys-product .woocommerce-tabs ul.tabs li::after {
    content: none;
    display: none;
}

body.single-product .genosys-product .woocommerce-tabs ul.tabs li,
body.single-product .genosys-product .woocommerce-tabs ul.tabs li.active {
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: transparent;
    box-shadow: none;
}

body.single-product .genosys-product .woocommerce-tabs ul.tabs li.active {
    background: #fff;
